function focusVent2Coordination(routeId){
 $('source-dialog').close();
 return activateTab(constructionViewer?'masonry':'model','floor1',()=>{
  const g=renderer, floor=MODEL.floor1, study=floor.shaft_masonry.vent2_coordination;
  const shaft=floor.shaft_masonry.rows.find(row=>row.id==='vent2');
  const route=study.variants.find(item=>item.id===routeId);
  const [x,y,z,X,Y,Z]=study.original_bounds_mm;
  const [,py,,px,pY]=route.probe_mm;
  const maxX=Math.max(X,px,...route.boxes_mm.map(b=>b[3]));
  const view=[x-340,Math.min(y,py)-130,z-160,maxX+90,Math.max(Y,pY)+90,z];
  experience.savedVisibility=new Map([...g.layers.values()].map(layer=>[layer.id,layer.visible]));
  for(const layer of g.layers.values())layer.visible=false;
  const layers={};
  for(const [kind,options] of Object.entries({
   Brick:{showEdges:false}, Aac:{showEdges:false}, Throat:{showEdges:true},
   Passage:{showEdges:true}, Exit:{opacity:.36,showEdges:true}, Fill:{showEdges:true},
  })){
   const id='ventCoord'+kind;
   layers[kind]=addLayer(g,id,options);
   experience.savedVisibility.set(id,false);
  }
  const showContext=(layer,parts)=>{
   for(const a of parts){
    const bounds=view.map((b,i)=>i<3?Math.max(b,Number(a[i])):Math.min(b,Number(a[i])));
    if(bounds.slice(0,3).every((lo,i)=>lo<bounds[i+3]))g.box(layer,...bounds,null,false);
   }
  };
  showContext(layers.Brick,route.id===study.selected_variant?shaft.masonry_boxes_mm:shaft.source_masonry_boxes_mm);
  showContext(layers.Aac,FloorGeometry.solids(floor).filter(piece=>piece.material==='aac').map(piece=>piece.bounds));
  const id='vent2-route:'+route.id;
  g.box(route.east_infill_m3?layers.Fill:layers.Throat,...study.original_bounds_mm,id);
  for(const box of route.boxes_mm)g.box(layers.Passage,...box,id);
  g.box(layers.Exit,...route.probe_mm,id);
  expInfo(g,id,{title:route.label, facts:study.source_fact_ids, sheets:study.references,
   note:`${route.id===study.selected_variant?'Вариант Г действующей модели.':'Сравнительная примерка от исходного АР-20.'} Подвод ВК-2 в помещение ${route.room_id}. ${study.method}`});
  for(const layer of Object.values(layers))g.commitLayer(layer);
  indexSceneObjects(g);
  g.target=[(view[0]+view[3])/2,(view[1]+view[4])/2,(z+Z)/2];
  g.span=Math.max(720,view[3]-view[0]+80,view[4]-view[1]+80)*g.fitAspect();
  g.yaw=-.48;g.pitch=.88;g.pan=[0,0];g.labels=[];
  $('scene-title').textContent='ВК-2 · '+route.label;
  $('scene-notice').innerHTML=`Синим показана примерка подвода. Прозрачный участок отмечает выход в помещение ${esc(route.room_id)}.
   ${route.east_infill_m3?'Оранжевым показан габарит заделки.':''} <button data-vent2-coordination>Сравнить варианты</button>`;
  renderLayerControls();g.request();
 });
}

function focusInletMesh(inlet){
 $('source-dialog').close();
 return activateTab(constructionViewer?'masonry':'model',inlet.floor,()=>{
  const context=inlet.floor==='floor1'?'floor1Brick':'vents';
  experience.savedVisibility=new Map([...renderer.layers.values()].map(layer=>[layer.id,layer.visible]));
  for(const layer of renderer.layers.values())layer.visible=[context,'ventInletMesh'].includes(layer.id);
  const b=inlet.bounds_mm.map(Number);
  renderer.target=b.slice(0,3).map((v,i)=>(v+b[i+3])/2);
  renderer.span=550*renderer.fitAspect();
  renderer.yaw={east:-Math.PI/2,north:Math.PI,south:0}[inlet.side]+.16;
  renderer.pitch=1.39;renderer.pan=[0,0];
  selectSceneObject('vent-mesh:'+inlet.id);
  renderer.layers.get('selection').visible=false;
  renderLayerControls();renderer.request();
 });
}

