function currentFloorTakeoff(){
 const variant=activeStair().id,live=floorCourseLevel==='lower'&&floorScenario;
 const saved=MODEL.floor1.masonry_takeoff;
 if(!live)return {variant,parameters:saved.parameters,result:saved.variants.find(v=>v.stair_variant===variant)};
 if(floorTakeoff?.scenario!==live||floorTakeoff.variant!==variant){
  const envelopes=stairWallEnvelopes();
  floorTakeoff={scenario:live,variant,parameters:live.parameters,
   result:{...FloorGeometry.masonryTakeoff(MODEL.floor1,live,envelopes,activeStair().landing_joint.masonry_seats.boxes_mm.shared_courses),
    reinforcement:FloorGeometry.masonryReinforcement(MODEL.floor1,live,envelopes,saved.reinforcement_rules)}};
 }
 return floorTakeoff;
}
function openFloorMasonry(){
 return prepareDialog(['facts','floor1','structure','floor'],()=>{
  const {variant,parameters,result}=currentFloorTakeoff();
  const model=MODEL.floor1.masonry_takeoff,groups={external:'Наружные стены',internal:'Внутренние несущие',partition:'Перегородки',unconfirmed:'У двери 7 · материал открыт'};
  const shared=result.landing_shared_masonry;
  const net=r=>{
   const q={...r};
   for(const [key,amount] of Object.entries(shared.accounted_m3))q[key]-=amount;
   if(q.block_volume_equivalent!=null)
    q.block_volume_equivalent=Math.ceil(q.net_blocks_m3*1e9/(parameters.length*parameters.height*q.thickness_mm)-1e-9);
   return q;
  };
  const groupRow=g=>`<tr><td>${esc(groups[g.role])} · ${g.thickness_mm} мм</td><td>${fmt(g.placed_pieces)}</td><td>${fmt(g.net_blocks_m3,6)}</td><td>${g.block_volume_equivalent===null?'—':fmt(g.block_volume_equivalent)}</td><td>${fmt(g.bed_m3,6)}</td><td>${fmt(g.horizontal_glue_m3,6)}</td><td>${fmt(g.vertical_glue_m3,6)}</td></tr>`;
  const walls=new Map(MODEL.floor1.walls.map(w=>[w.id,w]));
  const wallRows=result.walls.map(w=>w.wall_id==='boiler'?net(w):w)
   .map(w=>`<tr><td>${esc(walls.get(w.wall_id).label)}</td><td>${w.thickness_mm}</td><td>${fmt(w.placed_pieces)}</td><td>${fmt(w.net_blocks_m3,6)}</td><td>${fmt(w.bed_m3,6)}</td><td>${fmt(w.horizontal_glue_m3+w.vertical_glue_m3,6)}</td></tr>`).join('');
  const t=net(result.total);
  const bases=MODEL.floor1.bearing_review.variants.find(v=>v.id===variant);
  const boiler=bases.rows.find(row=>row.wall_id==='boiler');
  showDialog('АР-1 / АР-2','Кладка первого этажа',`
   <p>Блок ${fmt(parameters.length)} × ${fmt(parameters.height)} мм, шов ${fmt(parameters.joint)} мм, постель ${fmt(parameters.bed)} мм. ${esc(activeStair().label)}.</p>
   <button data-masonry-rebar>Раскладка арматуры и штраб</button> <button data-wall-bearing>Опирание стен и перегородок</button>
   <div class="table-wrap"><table><thead><tr><th>Участок</th><th>Части</th><th>AAC, м³</th><th>Целые по объёму, шт.</th><th>Постель, м³</th><th>Клей в постелях, м³</th><th>Клей в торцах, м³</th></tr></thead>
   <tbody>${result.groups.map(g=>groupRow(g.role==='partition'&&g.thickness_mm===250?net(g):g)).join('')}<tr><th>Всего</th><td>${fmt(t.placed_pieces)}</td><td>${fmt(t.net_blocks_m3,6)}</td><td>—</td><td>${fmt(t.bed_m3,6)}</td><td>${fmt(t.horizontal_glue_m3,6)}</td><td>${fmt(t.vertical_glue_m3,6)}</td></tr></tbody></table></div>
   <p>Кладка над наружной аркой входа учтена по габариту в ведомости перемычек. Раскладка блоков и швов над аркой открыта. <button data-floor-lintels>Перемычки первого этажа</button></p>
   <p>От −0,500 до −0,130 м перегородка котельной занимает ${fmt(boiler.below_wall_level_m3,6)} м³ по габариту. Из них ${fmt(bases.below_wall_level_shared_with_stair_brick_m3,6)} м³ совпадают с габаритами кирпичных простенков Лм 1. Материал общей части и раскладка нижнего участка открыты. ${factBtn('wall.boiler.base_support','Разрез АР-9')}</p>
   <p>Выше −0,130 м общий габарит со стеной котельной составляет ${fmt(shared.envelope_m3,6)} м³. Блоки, постель и швы в нём вычтены из объёмов газобетонной кладки. Число частей показано по порядовке. <button data-stair-landing>Опоры площадки Лм 1</button></p>
   <p>${esc(model.methods.block_volume_equivalent)} Перегородка у двери 7 включена в объём текущей 3D-модели по габариту 200 мм. Её материал требует подтверждения. Объём торцевых швов соответствует сплошному заполнению. Для закупки клея нужны фактические швы и выход выбранного состава.</p>
   <details><summary>Количества по стенам</summary><div class="table-wrap"><table><thead><tr><th>Стена</th><th>Ширина, мм</th><th>Части</th><th>AAC, м³</th><th>Постель, м³</th><th>Клей, м³</th></tr></thead><tbody>${wallRows}</tbody></table></div></details>
   <details><summary>Источники и открытые количества</summary>
   <p>АР-1 даёт объёмы по всему дому и общий запас ${factBtn('material.allowance_ar.percent','2 %')}. Применение запаса требует сверки с договором поставки и раскроем.</p>
   <p>АР-2 задаёт тонкослойный состав несущей кладки и арматуру А500С Ø8 для первого и каждого четвёртого ряда. Под наружными окнами предусмотрен дополнительный ряд. Длины и стыки арматуры требуют рабочей раскладки. Кирпичные вентблоки требуют вычета каналов и назначения швов.</p>
   ${factBtn('wall.external.masonry_binder','АР-2 · клеевой состав')} ${factBtn('masonry.appendix.joint_range','Приложение · шов 1–3 мм')} ${factBtn('masonry.appendix.bed_mortar_grade','Приложение · первый ряд')} ${sheetBtn('house_1',2,'АР-1 · ведомость дома')}
   </details>`);
 });
}
const wallBearingColors={plinth:'#4e7262',slab:'#3d7790',above_slab:'#c57e34',outside:'#a33929'};
function wallBearingPlan(variant,selected){
 const shapes=row=>Object.entries(row.plan).flatMap(([kind,polygons])=>polygons.map(polygon=>({kind,polygon})));
 const plot=variant.rows.flatMap(shapes),selection=selected?shapes(selected):plot;
 const focus=selected?.role==='bearing'&&selected.plan.above_slab.length?selected.plan.above_slab:selection.map(shape=>shape.polygon);
 const points=(focus.length?focus:plot.map(shape=>shape.polygon)).flat();
 const pad=selected?140:300;
 const [x0,y0,x1,y1]=[Math.min(...points.map(p=>p[0]))-pad,Math.min(...points.map(p=>p[1]))-pad,
  Math.max(...points.map(p=>p[0]))+pad,Math.max(...points.map(p=>p[1]))+pad];
 const concrete=MODEL.foundation.plinth.disjoint_rectangles_mm.map(([x,y,X,Y])=>
  `<rect x="${x}" y="${y}" width="${X-x}" height="${Y-y}" fill="#b5b9ae"/>`).join('');
 const layer=(items,opacity)=>items.map(({kind,polygon})=>
  `<polygon points="${polygon.map(p=>p.join(',')).join(' ')}" fill="${wallBearingColors[kind]}" opacity="${opacity}"/>`).join('');
 const opacity=selected?.area_m2>0?0.22:1;
 return `<svg class="plan-svg" viewBox="${x0} ${-y1} ${x1-x0} ${y1-y0}" role="img" aria-label="План опирания стен первого этажа"><g transform="scale(1,-1)">${concrete}${layer(plot,opacity)}${selected?layer(selection,1):''}</g></svg>`;
}
function openWallBearing(selected){
 return prepareDialog(['floor1','foundation','facts'],()=>{
  const report=MODEL.floor1.bearing_review;
  const variant=report.variants.find(v=>v.id===stairState.stairVariant)??report.variants.find(v=>v.id===report.default_variant);
  const walls=new Map(MODEL.floor1.walls.map(w=>[w.id,w.label]));
  const quantities=row=>`<td>${fmt(row.area_m2,6)}</td><td>${fmt(row.plinth_contact_m2,6)}</td><td>${fmt(row.slab_contact_m2,6)}</td><td>${fmt(row.slab_below_m2,6)}</td><td>${fmt(row.outside_slab_m2,6)}</td>`;
  const gate=report.gate_interface;
  const threshold=report.threshold;
  const trial=report.partition_trial.variants.find(item=>item.id===variant.id);
  const insulation=threshold.adjacent_layers.find(layer=>layer.id==='insulation');
  const sewerGap=scheme=>Math.min(...trial.services.filter(row=>row.sewer===scheme).map(row=>row.conservative_gap_mm));
  showDialog('АР-2 / АР-9…10 / АР-16 / КЖ-2…3','Опирание стен первого этажа',`
   <p>По АР-2 несущие стены начинаются над ростверком на ${factBtn('walls_support.elevation','−0,130 м')}. Перегородка котельной доходит до плиты Фм 1 на ${factBtn('foundation.Фм1.top_elevation','−0,500 м')} по разрезу ${factBtn('wall.boiler.base_support','АР-9')}.</p>
   <div class="table-wrap"><table id="wall-bearing-totals"><thead><tr><th>Основания</th><th>Всего, м²</th><th>На ростверке, м²</th><th>На плите, м²</th><th>Над плитой с зазором, м²</th><th>Вне плиты, м²</th></tr></thead><tbody>
   ${variant.totals.map(row=>`<tr><th>${row.role==='bearing'?'Несущие стены':'Перегородки'}</th>${quantities(row)}</tr>`).join('')}</tbody></table></div>
   <p>Разрыв ростверка совпадает с проёмом Д-3 шириной ${fmt(gate.opening_to_mm-gate.opening_from_mm)} мм. Восточный торец под простенком доходит до X = ${fmt(gate.cut_to_mm)} мм. Для восьми перегородок выбраны опорные полосы до Фм 1. Материал и крепление уточняются.</p>
   <button data-gate-jamb>Опирание простенков ворот</button>
   <label>Участок <select id="wall-bearing-select"><option value="">Весь этаж</option>${variant.rows.map(row=>`<option value="${esc(row.wall_id)}">${esc(walls.get(row.wall_id))}</option>`).join('')}</select></label>
   <div class="legend"><span><i style="--c:${wallBearingColors.plinth}"></i>На ростверке</span><span><i style="--c:${wallBearingColors.slab}"></i>На плите</span><span><i style="--c:${wallBearingColors.above_slab}"></i>Над плитой с зазором</span><span><i style="--c:${wallBearingColors.outside}"></i>Вне плиты</span></div>
   <div id="wall-bearing-plan"></div><p id="wall-bearing-detail"></p><button id="boiler-bearing-view">Перегородка котельной в 3D</button>
   <h3>Габариты до плиты под перегородками</h3>
   <p>В модели подошвы ${fmt(trial.rows.length)} перегородок лежат на ${fmt(trial.rows[0].z_mm[1]-trial.rows[0].z_mm[0])} мм выше Фм 1. Отметка −0,130 м попадает в диапазон ${fmt(insulation.z_mm[0])}…${fmt(insulation.z_mm[1])} мм соседнего XPS по ${factBtn(insulation.fact_ids[0],'АР-16')}. Материал и крепление оснований открыты.</p>
   <div class="table-wrap"><table id="partition-base-trial"><thead><tr><th>Толщина перегородки, мм</th><th>Площадь, м²</th><th>Габарит, м³</th></tr></thead><tbody>
   ${trial.by_width.map(row=>`<tr><th>${fmt(row.width_mm)}</th><td>${fmt(row.area_m2,6)}</td><td>${fmt(row.envelope_m3,6)}</td></tr>`).join('')}
   <tr><th>Итого</th><td>${fmt(trial.total_area_m2,6)}</td><td>${fmt(trial.envelope_m3,6)}</td></tr></tbody></table></div>
   <p>Для труб, достигающих высот габаритов, расчётный просвет в плане составляет от ${fmt(sewerGap('source'))} мм с исходной трассой К1 и от ${fmt(sewerGap('coordinated'))} мм со смещённой. Проверено ${fmt(trial.services.length)} сочетаний К1 и В1.</p>
   <button id="partition-base-view">Габариты до плиты в 3D</button>
   <h3>Участок под дверью из тамбура</h3>
   <p id="tambour-threshold-summary">В разрезе ${factBtn('wall.tambour_threshold.base_support','АР-10')} участок шириной ${factBtn('wall.tambour_threshold.section_width',fmt(threshold.section_width_mm)+' мм')} доходит до плиты. Для 3D-сверки профиль показан на ${fmt(threshold.opening_span_mm)} мм проёма. Справочный объём ${fmt(threshold.envelope_m3,6)} м³. Протяжённость вдоль перегородки, материал и крепление к плите остаются открытыми.</p>
   <p>По АР-16 в тамбуре плитка 10 мм, в гостиной ламинат 7 мм на подложке 3 мм. Под обоими покрытиями стяжка 90 мм. Оба покрытия вровень. По решению владельца стык проходит под серединой закрытого полотна. Рабочий профиль шва уточняет отделочник.</p><button id="tambour-threshold-view">Дверь 4 · сечение в 3D</button>
   <div class="dialog-links">${report.reference_sheets.map(args=>sheetBtn(...args)).join('')}</div>`);
  const select=$('wall-bearing-select');
  if(variant.rows.some(row=>row.wall_id===selected))select.value=selected;
  const render=()=>{
   const row=variant.rows.find(item=>item.wall_id===select.value);
   $('wall-bearing-plan').innerHTML=wallBearingPlan(variant,row);
   const envelope=trial.rows.find(item=>item.wall_id===select.value);
   $('wall-bearing-detail').textContent=row?.area_m2===0?'Площадь под совмещённым участком отнесена к соседним стенам.':row
    ?`Низ ${fmt(row.base_mm)} мм. На ростверке ${fmt(row.plinth_contact_m2,6)} м², на плите ${fmt(row.slab_contact_m2,6)} м², над плитой с зазором ${fmt(row.slab_below_m2,6)} м².${envelope?` Габарит до плиты ${fmt(envelope.envelope_m3,6)} м³.`:''}`:'';
   $('partition-base-view').disabled=!!select.value&&!envelope;
  };
  select.onchange=render;
  render();
  $('partition-base-view').onclick=()=>showPartitionBases(variant,trial,walls,select.value);
  $('tambour-threshold-view').onclick=showTambourThreshold;
  $('boiler-bearing-view').onclick=()=>{
   $('source-dialog').close();
   activateTab(constructionViewer?'masonry':'model','floor1',()=>{
    const g=renderer,wall=MODEL.floor1.walls.find(w=>w.id==='boiler'),[x0,y0,x1,y1]=wall.bounds_mm.map(Number);
    for(const layer of g.layers.values())layer.visible=['walls1','slab','beams'].includes(layer.id);
    g.target=[(x0+x1)/2,(y0+y1)/2,+wall.base_mm+250];g.span=3900*g.fitAspect();g.yaw=-.75;g.pitch=.6;g.labels=[];
    selectSceneObject('wall:boiler');
    renderLayerControls();g.request();
   });
  };
 });
}

function drawPartitionSupports(g){
 const report=MODEL.floor1.bearing_review;
 const variant=report.variants.find(row=>row.id===stairState.stairVariant)??report.variants.find(row=>row.id===report.default_variant);
 const trial=report.partition_trial.variants.find(row=>row.id===variant.id);
 const layer=addLayer(g,'partitionSupports',{showEdges:false,explodeOrder:1,order:10});
 for(const row of trial.rows){
  const support=variant.rows.find(wall=>wall.wall_id===row.wall_id);
  const id='partition-support:'+row.wall_id;
  for(const polygon of support.plan.above_slab)g.prism(layer,polygon,...row.z_mm,id);
  const wall=MODEL.floor1.walls.find(wall=>wall.id===row.wall_id);
  expInfo(g,id,{title:wall.label+' · опорная полоса на Фм 1',status:'partition_base_envelope',
   facts:report.partition_trial.source_fact_ids,sheets:[['house_1',4],['house_1',17],['house_2',7]],
   note:`Площадь ${fmt(row.area_m2,6)} м². Габарит ${fmt(row.envelope_m3,6)} м³. Материал и крепление уточняются по расчёту.`});
 }
}
function showPartitionBases(variant,trial,walls,selected){
 $('source-dialog').close();
 return activateTab(constructionViewer?'masonry':'model','floor1',()=>{
  const g=renderer,report=MODEL.floor1.bearing_review;
  experience.savedVisibility=new Map([...g.layers.values()].map(layer=>[layer.id,layer.visible]));
  for(const layer of g.layers.values())layer.visible=['slab','beams'].includes(layer.id);
  const bases=addLayer(g,'partitionBaseEnvelope',{showEdges:false,order:12});
  const wallsLayer=addLayer(g,'partitionBaseWall',{showEdges:false,opacity:.4,order:13});
  for(const layer of [bases,wallsLayer])experience.savedVisibility.set(layer.id,false);
  const rows=selected?trial.rows.filter(row=>row.wall_id===selected):trial.rows;
  for(const row of rows){
   const id='partition-base:'+row.wall_id;
   const [bottom,top]=row.z_mm;
   const support=variant.rows.find(item=>item.wall_id===row.wall_id);
   for(const polygon of support.plan.above_slab){
    g.prism(bases,polygon,bottom,top,id);
    g.prism(wallsLayer,polygon,top,top+300);
   }
   const wall=MODEL.floor1.walls.find(item=>item.id===row.wall_id);
   expInfo(g,id,{title:walls.get(row.wall_id)+' · габарит до плиты',status:'partition_base_envelope',
    facts:[...new Set([...report.partition_trial.source_fact_ids,...wall.input_fact_ids])],
    sheets:[['house_1',4],['house_1',17],['house_2',7]],
    note:`Площадь ${fmt(row.area_m2,6)} м², объём ${fmt(row.envelope_m3,6)} м³. Материал основания и крепление открыты.`});
  }
  g.commitLayer(bases);g.commitLayer(wallsLayer);indexSceneObjects(g);
  const bounds=rows.map(row=>g.sceneObjects.get('partition-base:'+row.wall_id).bounds);
  const min=i=>Math.min(...bounds.map(box=>box[i])),max=i=>Math.max(...bounds.map(box=>box[i+3]));
  g.target=[0,1,2].map(i=>(min(i)+max(i))/2);
  g.span=Math.max(2200,1.5*Math.max(max(0)-min(0),max(1)-min(1)))*g.fitAspect();
  g.yaw=-.67;g.pitch=.94;g.pan=[0,0];g.labels=[];
  $('scene-title').textContent=selected?walls.get(selected)+' · габарит до плиты':'Габариты до плиты под перегородками';
  $('scene-notice').textContent='Оранжевые тела показывают промежуток между Фм 1 и подошвами. Серым показаны нижние 300 мм перегородок на этих участках.';
  if(selected){selectSceneObject('partition-base:'+selected);g.layers.get('selection').visible=false;}
  renderLayerControls();g.request();
 });
}

function openGateJamb(){
 return prepareDialog(['floor1','foundation','facts'],()=>{
  const study=MODEL.floor1.bearing_review.gate_jamb;
  const side={west:'Западный',east:'Восточный'};
  const material={brick:'Лицевой кирпич',air:'Воздушный зазор',xps:'XPS',aac:'Газобетон'};
  const rows=study.variants.map(variant=>{
   const [x,X]=variant.opening_x_mm;
   const gaps=variant.gaps.map(gap=>`${side[gap.side]} · ${fmt(gap.width_mm)} мм`).join(', ');
   const projection=variant.lintel_seats.map(seat=>fmt(seat.over_plinth_m2,6)).join(' / ');
   return `<tr><th>От ${variant.id==='west'?'западной':'восточной'} грани ${variant.id===study.active_variant?'· принято для модели':'· сравнение'}</th><td>${fmt(x)}…${fmt(X)}</td><td>${gaps||'0 мм'}</td><td>${projection}</td></tr>`;
  });
  const current=study.variants.find(row=>row.id===study.active_variant);
  const steel=study.east_end_reinforcement;
  showDialog('АР-3 / АР-7 / АР-16 / КЖ-2 / КЖ-11','Ворота · опирание простенков',`
   <p>Цепь АР-3 складывается из двух простенков по ${factBtn('plan.floor_1.anchors.gate_return_outer','1165 мм')} и проёма ${factBtn('door.3.opening_width','5000 мм')}. Она даёт ${fmt(study.source_chain_mm)} мм при ${fmt(study.exterior_span_mm)} мм между наружными гранями по осям модели. Исходный разрыв КЖ-2 по осям модели X = ${study.source_plinth_cut_x_mm.map(x=>fmt(x)).join('…')} мм. В действующей редакции восточный торец цельного ростверка продлён до откоса ворот. Разрыв X = ${study.plinth_cut_x_mm.map(x=>fmt(x)).join('…')} мм.</p>
   <div class="table-wrap"><table id="gate-jamb-anchors"><thead><tr><th>Привязка по АР-3</th><th>Проём X, мм</th><th>Полоса над разрывом</th><th>Проекция площадок ПР-3 на ростверк, м²<br>Запад / восток</th></tr></thead><tbody>${rows.join('')}</tbody></table></div>
   <p>Обе площадки ПР-3 на кладке имеют длину ${fmt(current.lintel_seats[0].length_mm)} мм. В варианте от восточной грани перемычка и проём смещены вместе. Номинальный блок ${study.block_size_mm.map(x=>fmt(x)).join(' × ')} мм. Рабочие зазоры и крепление направляющих требуют уточнения. Передачу усилия от ПР-3 на ростверк проверяет конструктор.</p>
   <div class="table-wrap"><table id="gate-jamb-layers"><thead><tr><th>Слой простенка</th><th>Толщина, мм</th><th>Площадь над разрывом, м²</th></tr></thead><tbody>
   ${study.layer_y_mm.map(({id,y_mm:[y,Y]})=>`<tr><th>${material[id]}</th><td>${fmt(Y-y)}</td><td>${fmt(current.gaps.reduce((sum,gap)=>sum+gap.layers.find(layer=>layer.id===id).area_m2,0),6)}</td></tr>`).join('')}
   </tbody></table></div>
   <h3>Шов под восточным простенком</h3>
   <p>Для проверки конструктором приняты две заливки: сначала плита, затем ростверк. Для шва под правым простенком предусмотрен ${factBtn(MODEL.foundation.waterproofing.gate_east_joint.cord_fact_id,'гидроизоляционный шнур по КЖ-3')}. В проёме продолжается плита. Трасса, сечение и окончание шнура у торца требуют деталировки.</p>
   <button data-gate-jamb-view="slab-pour">Шов у ворот в 3D</button>
   <h3>Бетон В25 на весь Фм 1</h3>
   <div class="table-wrap"><table id="fm1-gate-pour-quantities"><thead><tr><th>Заливка</th><th>Чистый геометрический объём, м³</th></tr></thead>
   <tbody><tr><th><button data-fm1-pour="slab">1 · вся плита</button></th><td>${fm1PourVolume('slab')}</td></tr>
   <tr><th><button data-fm1-pour="plinth">2 · все ростверки над плитой</button></th><td>${fm1PourVolume('plinth')}</td></tr></tbody>
   <tfoot><tr><th>Всего Фм 1</th><td>${fm1PourVolume('total')}</td></tr></tfoot></table></div>
   <h3>Армирование восточного торца</h3>
   <p>Для расчёта согласованы прямые окончания поз. ${steel.position}. По КЖ-3 и КЖ-4 это ${steel.bar_count} стержня Ø${steel.diameter_mm} ${esc(steel.grade)}, по два в ярусе. Защитный слой торца, длина анкеровки и рабочий раскрой уточняются расчётом.</p>
   <figure style="max-width:480px;margin:12px 0"><svg viewBox="0 0 400 122" style="width:100%;height:auto" role="img" aria-label="Вид сверху. Поз. 6 заканчивается прямыми концами в бетоне до грани ворот. Зазор нарисован условно.">
    <rect x="122" y="10" width="263" height="76" fill="#e2e9e7" stroke="#637673"/>
    <path d="M122 9V90" stroke="#b53d26" stroke-width="3"/><path d="M149 29H385 M149 67H385" stroke="#007668" stroke-width="4"/>
    <g font-family="sans-serif" font-size="14" fill="#20363c"><text x="10" y="52">Проём ворот</text><text x="163" y="53">Вид сверху · один ярус</text></g>
    <text x="10" y="111" font-family="sans-serif" font-size="13" fill="currentColor">Красным показана грань бетона. Отступ стержней условный.</text>
   </svg></figure>
   <div class="buttons-row"><button data-gate-jamb-view="steel">Четыре стержня в 3D</button><button data-gate-jamb-view="active">Восточный простенок · действующая редакция в 3D</button><button data-gate-jamb-view="source">Восточный простенок · исходный торец КЖ-2</button><button data-gate-jamb-view="east">Западный простенок · сравнение при сдвиге ворот</button></div>
   <div class="dialog-links">${sheetBtn('house_1',4,'АР-3')}${factBtn('plan.floor_1.anchors.gate_right_return_outer','Правый простенок · АР-3')}${sheetBtn('house_1',17,'АР-16')}${sheetBtn('house_2',7,'КЖ-2','revision')}${sheetBtn('house_2',8,'КЖ-3 · сечение 2–2')}${sheetBtn('house_2',9,'КЖ-4 · поз. 6','revision')}${sheetBtn('house_2',16,'КЖ-11')}</div>`);
 });
}

function showGateJamb(view){
 $('source-dialog').close();
 return activateTab(constructionViewer?'masonry':'model','floor1',()=>{
  const g=renderer,study=MODEL.floor1.bearing_review.gate_jamb;
  const steelView=view==='steel';
  const pourView=view==='slab-pour'||view==='plinth-pour';
  const active=view==='active'||steelView||pourView;
  const variant=study.variants.find(row=>row.id===(view==='east'?'east':study.active_variant));
  const gap=view==='east'?variant.gaps[0]:study.historical_east_gap;
  const east=gap.side==='east';
  const [x,y,z,X,Y,Z]=gap.bounds_mm;
  const left=x-300,right=X+300;
  const slabBottom=z-Number(FACTS.get('foundation.Фм1.slab_thickness').value);
  experience.savedVisibility=new Map([...g.layers.values()].map(layer=>[layer.id,layer.visible]));
  for(const layer of g.layers.values())layer.visible=false;
  const draw=(id,box,opacity=1)=>{
   const layer=addLayer(g,id,{showEdges:false,order:12,opacity});
   g.box(layer,...box,id,false);g.commitLayer(layer);
   experience.savedVisibility.set(id,false);
  };
  const plinthStart=east?(active?study.plinth_cut_x_mm[1]:study.source_plinth_cut_x_mm[1]):left;
  if(steelView){
   // Only the interior slice is measurable. Bar ends and end cover have no working dimensions.
   const steel=study.east_end_reinforcement;
   const start=(plinthStart+right)/2;
   const slice=addLayer(g,'gateJambSection',{opacity:.18,showEdges:true,order:15});
   g.box(slice,start,y,z,right,Y,Z,'gateJambSection',true);g.commitLayer(slice);
   const bars=addLayer(g,'gateJambLongitudinal',{showEdges:false,order:12});
   for(const barY of steel.section_bar_y_mm)for(const barZ of steel.section_bar_z_mm){
    g.tube(bars,[start,barY,barZ],[right,barY,barZ],steel.diameter_mm/2,12,'gateJambLongitudinal');
   }
   g.commitLayer(bars);
   for(const layer of [slice,bars])experience.savedVisibility.set(layer.id,false);
   expInfo(g,'gateJambLongitudinal',{title:'Прямые стержни поз. 6',facts:steel.input_fact_ids,
    note:'Обе границы показанного фрагмента проходят через каркас. Рабочую длину анкеровки и защитный слой у торца определяет расчёт.',
    sheets:[['house_2',8],['house_2',9]]});
  }else if(pourView){
   const joint=MODEL.foundation.waterproofing.gate_east_joint,h=joint.elevation_mm;
   draw('gateJambSlab',[left,y,slabBottom,right,Y+150,h]);
   const face=addLayer(g,'gateJambJoint',{order:13,depthBias:1});
   g.face(face,[[plinthStart,y,h],[right,y,h],[right,Y,h],[plinthStart,Y,h]],[0,0,1],face.id);
   g.commitLayer(face);experience.savedVisibility.set(face.id,false);
   if(view==='plinth-pour')draw('gateJambPlinth',[plinthStart,y,h,right,Y,Z],.3);
   expInfo(g,face.id,{title:'Рабочий шов плиты с ростверком',facts:[joint.cord_fact_id],
    note:'Выделена поверхность контакта под восточным простенком. Расположение шнура и его окончание уточняет конструктор.',sheets:[['house_2',8]]});
  }else{
   draw('gateJambSlab',[left,y,slabBottom,right,Y+150,z]);
   draw('gateJambPlinth',[plinthStart,y,z,east?right:x,Y,Z]);
   for(const {id,y_mm:[a,b]} of study.layer_y_mm.filter(layer=>layer.id!=='air')){
    draw('gateJamb-'+id,[east?x:left,a,Z,east?right:X,b,Z+280]);
   }
  }
  if(!active){
   draw('gateJambGap',gap.bounds_mm,.66);
   expInfo(g,'gateJambGap',{title:'Полоса над разрывом ростверка',facts:study.input_fact_ids,
    note:`Ширина ${fmt(gap.width_mm)} мм и высота ${fmt(Z-z)} мм. Справочный габарит ${fmt(gap.envelope_m3,6)} м³.`,
    sheets:[['house_1',4],['house_2',7]]});
  }
  g.target=[(x+X)/2,(y+Y)/2,(Z+slabBottom)/2+140];
  g.span=1540*g.fitAspect();g.yaw=east?.55:-.55;g.pitch=1.13;g.pan=[0,0];g.labels=[];
  $('scene-title').textContent=(east?'Восточный':'Западный')+' простенок ворот';
  const variantLabel=view==='source'?'Исходный торец КЖ-2':'Сравнение при сдвиге ворот на восток';
  $('scene-notice').innerHTML=(active
   ?`Действующая редакция. Восточный торец цельного ростверка доходит до X = ${fmt(plinthStart)} мм. Разрыв ${fmt(study.plinth_cut_x_mm[1]-study.plinth_cut_x_mm[0])} мм. Обе площадки ПР-3 полностью проецируются на ростверк. Для расчёта принят вариант с прямыми концами поз. 6.`
   :`${variantLabel}. Оранжевым показана полоса ${fmt(gap.width_mm)} мм над разрывом.`)+' <button data-gate-jamb>Опирание простенков</button>';
  if(steelView){
   g.target=[(plinthStart+3*right)/4,(y+Y)/2,(z+Z)/2];g.span=850*g.fitAspect();
   g.yaw=-.95;g.pitch=.42;
   $('scene-title').textContent='Арматура восточного ростверка · фрагмент внутри бетона';
   $('scene-notice').innerHTML='Зелёным показаны четыре прямых стержня поз. 6. Обе плоскости сечения проходят внутри ростверка. Их положение в этом виде условно. <button data-gate-jamb>Схема торца</button>';
  }else if(pourView){
   const slabStage=view==='slab-pour';
   g.target=[plinthStart,(y+Y)/2,z-40];g.span=1010*g.fitAspect();g.yaw=-.8;g.pitch=.65;
   $('scene-title').textContent=slabStage?'Первая заливка · плита у Д-3':'Вторая заливка · ростверк у Д-3';
   $('scene-notice').innerHTML=(slabStage
    ?'Плита проходит под проёмом. Зелёным выделен участок, на котором будет стоять ростверк.'
    :'Ростверк показан полупрозрачным. Зелёным выделен рабочий шов под простенком. Здесь предусмотрен шнур по КЖ-3, его трасса и окончание требуют деталировки.')+
    (slabStage?' <button data-gate-jamb-view="plinth-pour">Вторая заливка · ростверк</button>':' <button data-gate-jamb-view="slab-pour">Первая заливка · плита</button>')+
    ' <button data-gate-jamb>Схема узла</button>';
  }else if(active){
   $('scene-notice').innerHTML+=' <button data-gate-jamb-view="slab-pour">Две заливки в 3D</button>';
   $('scene-notice').innerHTML+=' <button data-gate-jamb-view="steel">Четыре стержня в 3D</button>';
  }
  indexSceneObjects(g);renderLayerControls();g.request();
 });
}

function showTambourThreshold(){
 $('source-dialog').close();
 return activateTab(constructionViewer?'masonry':'model','floor1',()=>{
  const g=renderer,t=MODEL.floor1.bearing_review.threshold;
  const [x,y,base,X,Y,top]=t.bounds_mm;
  const south=y-630,north=Y+630;
  const slabBottom=base-Number(FACTS.get('foundation.Фм1.slab_thickness').value);
  const layers=[];
  const draw=(id,boxes)=>{
   const layer=addLayer(g,id,{showEdges:false,order:13});
   for(const box of boxes)g.box(layer,...box,id,false);
   g.commitLayer(layer);layers.push(id);
  };
  draw('tambourThreshold',[t.bounds_mm]);
  draw('tambourThresholdSlab',[[x,south,slabBottom,X,north,base]]);
  draw('tambourThresholdTop',[[x,south,top,X,north,t.upper_screed.z_mm[1]]]);
  for(const {id,z_mm:[z,Z]} of t.adjacent_layers){
   draw('tambourThreshold-'+id,[[x,south,z,X,y,Z],[x,Y,z,X,north,Z]]);
  }
  for(const {side,layers:finishes} of t.finishes){
   const mid=t.finish_joint.y_mm;
   const [a,b]=side==='south'?[south,mid]:[mid,north];
   for(const {id,z_mm:[z,Z]} of finishes)draw('tambourThreshold-'+id,[[x,a,z,X,b,Z]]);
  }
  expInfo(g,'tambourThreshold',{title:'Участок под дверью 4',status:'threshold_section_trial',facts:t.input_fact_ids,
   sheets:[['house_1',11],['house_1',4],['house_1',17]],
   note:`Площадь на плите ${fmt(t.footing_m2,6)} м² в пределах проёма. Материал и фактическая длина требуют уточнения.`});
  experience.savedVisibility=new Map([...g.layers.values()].map(layer=>[layer.id,layer.visible]));
  for(const id of layers)experience.savedVisibility.set(id,false);
  for(const layer of g.layers.values())layer.visible=layers.includes(layer.id);
  g.target=[(x+X)/2,(y+Y)/2,(base+top)/2-80];g.span=2050*g.fitAspect();g.yaw=-1.03;g.pitch=.97;g.pan=[0,0];g.labels=[];
  $('scene-title').textContent='Дверь 4 · участок под полом';
  $('scene-notice').textContent='По решению владельца плитка тамбура и ламинат гостиной сходятся под серединой закрытого полотна. Верх обоих покрытий ±0,000.';
  indexSceneObjects(g);selectSceneObject('tambourThreshold');
  g.layers.get('selection').visible=false;
  renderLayerControls();g.request();
 });
}
