function focusMasonryCorner(rowIndex,kind){
 $('source-dialog').close();
 return activateTab(constructionViewer?'masonry':'model','floor1',()=>{
  const g=renderer, floor=MODEL.floor1, masonry=floor.masonry_takeoff, s=masonry.corner_study;
  const detail=s.corners.find(corner=>corner.id===s.detail_id);
  const row=detail.rows.find(item=>item.row===rowIndex);
  const course=FloorGeometry.courses(floor,masonry.parameters).rows[rowIndex-1];
  const [x,y,X,Y]=detail.limits_mm, max=[X+330,Y+330];
  const z=row.routes[0].endpoints_mm[0][2], half=s.groove_mm/2;
  const clipEnd=(point,axis)=>point.map((value,i)=>i===axis?Math.min(value,max[axis]):value);
  experience.savedVisibility=new Map([...g.layers.values()].map(layer=>[layer.id,layer.visible]));
  for(const layer of g.layers.values())layer.visible=false;
  const base=addLayer(g,'masonryCornerBase',{showEdges:true});
  const groove=addLayer(g,'masonryCornerGroove',{opacity:.42,showEdges:false});
  const steel=addLayer(g,'masonryCornerSteel',{showEdges:false});
  for(const layer of [base,groove,steel])experience.savedVisibility.set(layer.id,false);
  for(const piece of course.pieces.filter(piece=>detail.walls.includes(piece.wall_id))){
   const [a,b,c,d,e,f]=piece.bounds_mm;
   const bottom=Math.max(c,z-145),top=Math.min(f,z-half);
   if(a<max[0]&&b<max[1]&&a>=x&&b>=y&&bottom<top){
    g.box(base,a,b,bottom,Math.min(d,max[0]),Math.min(e,max[1]),top,null,true);
   }
  }
  const id='corner-garage:'+rowIndex+':'+kind;
  for(const route of row.routes){
   const bent=kind==='bent';
   const near=bent?route.tangent_mm:route.old_endpoints_mm;
   for(const [axis,end] of route.endpoints_mm.entries()){
    const start=near[axis], stop=clipEnd(end,axis);
    const a=start.map((v,i)=>i===axis?Math.min(v,stop[i]):v-half);
    const b=start.map((v,i)=>i===axis?Math.max(v,stop[i]):v+half);
    if(stop[axis]>start[axis]){
     g.box(groove,...a,...b,id,false);
     g.tube(steel,start,stop,s.diameter_mm/2,12,id);
    }
   }
   if(bent){
    const [cx,cy,cz]=route.centre_mm;
    const arc=radius=>Array.from({length:25},(_,i)=>{
     const angle=Math.PI*i/48;
     return [cx-radius*Math.sin(angle),cy-radius*Math.cos(angle)];
    });
    const poly=arc(s.radius_mm+half).concat(arc(s.radius_mm-half).reverse());
    g.prism(groove,poly,cz-half,cz+half,id);
    g.rod(steel,arc(s.radius_mm).map(p=>[...p,cz]),s.diameter_mm/2,id);
   }
  }
  expInfo(g,id,{title:'Штрабы · юго-западный угол',facts:s.source_fact_ids,sheets:s.references,
   note:'Габарит угловой примерки на выбранной отметке. Кладка показана под уровнем штраб.'});
  for(const layer of [base,groove,steel])g.commitLayer(layer);
  indexSceneObjects(g);
  g.target=[(x+max[0])/2,(y+max[1])/2,z-25];g.span=1020*g.fitAspect();
  g.yaw=-.44;g.pitch=.80;g.pan=[0,0];g.labels=[];
  $('scene-title').textContent='Угол гаража · ряд '+rowIndex;
  $('scene-status').textContent='Примерка';
  $('scene-notice').innerHTML=`${kind==='bent'?'Повороты с пробным радиусом '+s.radius_mm+' мм.':'Прямые участки по текущей раскладке.'}
   Синяя арматура показана внутри полупрозрачных штраб. <button data-masonry-corners>К таблице углов</button>`;
  renderLayerControls();g.request();
 });
}

