function focusLintelShaftJoint(variantId){
 $('source-dialog').close();
 return activateTab(constructionViewer?'masonry':'model','floor1',()=>{
  const g=renderer,model=MODEL.floor1,joint=model.lintel_takeoff.shaft_joint;
  const data=joint.variants.find(row=>row.id===variantId);
  const shaft=model.shaft_masonry.rows.find(row=>row.id===joint.shaft_id);
  const cage=model.lintel_takeoff.reinforcement.find(row=>row.lintel_id===joint.lintel_id);
  const pocket=data.pocket_bounds_mm.map(Number);
  const low=pocket[2]-320,high=pocket[5]+920;
  experience.savedVisibility=new Map([...g.layers.values()].map(layer=>[layer.id,layer.visible]));
  for(const layer of g.layers.values())layer.visible=false;
  const add=(id,opacity,order)=>{
   const layer=addLayer(g,id,{showEdges:false,opacity,order});
   experience.savedVisibility.set(id,false);
   return layer;
  };
  const brick=add('pr2JointBrick',.48,12),concrete=add('pr2JointConcrete',.20,13),
   recess=add('pr2JointPocket',.72,17),duct=add('pr2JointDuct',.8,14),steel=add('pr2JointSteel',1,16);
  drawShaftBrick(g,brick,{masonry_boxes_mm:data.shaft_recess_boxes_mm},low,high,'pr2JointBrick');
  g.box(concrete,...cage.bounds_mm.map(Number),'pr2JointConcrete',false);
  g.box(recess,...pocket,'pr2JointPocket',false);
  const offset=Number(data.offset_x_mm);
  for(const feature of [shaft.cores.find(r=>r.id===data.nearest_core.id),shaft.inlets.find(r=>r.id===data.nearest_inlet.id)]){
   const [a,b,c,A,B,C]=feature.bounds_mm.map(Number);
   g.box(duct,a+offset,b,Math.max(c,low),A+offset,B,Math.min(C,high),'pr2JointDuct',false);
  }
  for(const set of [cage.longitudinal,cage.stirrups])for(const raw of set.axes_mm){
   const path=raw.map(point=>point.map(Number));
   for(let i=1;i<path.length;i++)g.tube(steel,path[i-1],path[i],Number(set.diameter_mm)/2,12,'pr2JointSteel');
  }
  for(const layer of [brick,concrete,recess,duct,steel])g.commitLayer(layer);
  g.target=[pocket[0]-165,(pocket[1]+pocket[4])/2,(high+low)/2-70];
  g.span=3240*g.fitAspect();g.yaw=.27;g.pitch=1.16;g.pan=[0,0];g.labels=[];
  $('scene-title').textContent='Карман ПР-2 в ВК-3 · '+(data.id==='ar21'?'АР-21':'АР-3 от западной стены');
  $('scene-notice').innerHTML=`Оранжевым показан карман глубиной ${fmt(data.insertion_mm)} мм, синим — ближайший канал и подвод. <button data-lintel-shaft-joint>Сравнить привязки</button>`;
  indexSceneObjects(g);renderLayerControls();g.request();
 });
}
