'use strict';
let floorFinishRenderer=null;

function disposeFloorFinishViewer(){
 floorFinishRenderer?.dispose();
 floorFinishRenderer=null;
}

function floorRange(range){
 if(!range)return '—';
 const [a,b]=range.map(Number);
 return a===b?fmt(a):fmt(a)+'…'+fmt(b);
}

function openFloorFinishes(){
 return prepareDialog(['renderer','facts','experience','foundation'],()=>{
  const {types,totals,upper_area_audit,platform_section_fact_ids,reference_sheets}=MODEL.experience.floor_finishes;
  const levels={floor1:'Первый этаж',platform:'Наружные площадки',floor2:'Мансарда'};
  const hall=upper_area_audit.find(r=>r.room_id==='14');
  const vent=hall.variants[0].opening_areas_m2.vent1;
  showDialog('АР-16 / РАЗРЕЗЫ АР-9 И АР-10','Ведомость полов',`
   <p>Внутренние площади взяты из АР-16. Для покрытия типа 6 учтена только входная площадка № 12. Восточная терраса № 13 снята. Подсчёт слоёв использует горизонтальные площади.</p>
   <div class="buttons-row"><button data-floor-waterproofing>Гидроизоляция полов и стен</button><button data-wall-vapour>Пароизоляция наружных стен</button><button data-garage-drain>Уклоны пола гаража и водоотвод</button></div>
   <div class="table-wrap"><table><thead><tr><th>Тип</th><th>Помещения</th><th>АР-16, м²</th><th>Для обмера, м²</th><th>Отметка чистого пола, м</th><th>Остаток до бетона, мм</th></tr></thead><tbody>
   ${types.map(t=>`<tr><th>${t.id}</th><td>${t.id==='6'?'12 (в исходнике 12, 13)':t.room_ids.join(', ')}</td><td>${factBtn(t.area_fact_id,t.issued_area_m2)}</td><td>${fmt(t.takeoff_area_m2)}</td><td>${fmt(Number(t.finish_z_mm)/1000)}</td><td>${floorRange(t.level_difference_mm)}</td></tr>`).join('')}
   </tbody></table></div>
   <p>У типа 6 в остатке учтено отдельное основание 120 мм из исходного состава. Сверху исходные АР-9 и АР-10 показывают ${factBtn(platform_section_fact_ids[0],'50 мм')}, снизу до плиты ${factBtn(platform_section_fact_ids[1],'280 мм')}. Три подъёма Крм 1 по 150 мм показаны на КЖ-5. Вертикальные грани ступеней учтены отдельной строкой ведомости.</p>
   <div class="roof-detail-controls"><label>Разрез <select id="floor-finish-type">${types.map(t=>`<option value="${t.id}">Тип ${t.id} · ${levels[t.section]}</option>`).join('')}</select></label>
    <label id="floor-finish-range-label">Толщина стяжки <select id="floor-finish-range"><option value="1">Верхняя граница</option><option value="0">Нижняя граница</option></select></label></div>
   <div class="viewport roof-detail-viewport"><canvas id="floor-finish-canvas" tabindex="0" aria-label="Разрез пола"></canvas><div class="scene-help">Вращение и масштабирование</div></div>
   <p id="floor-finish-section-note" class="tiny" aria-live="polite"></p><div id="floor-finish-layers"></div>
   <details><summary>Материалы по этажам и площадкам</summary><div class="table-wrap"><table><thead><tr><th>Зона</th><th>Материал</th><th>Площадь в плане, м²</th><th>Объём, м³</th></tr></thead><tbody>
   ${totals.map(r=>`<tr><th>${levels[r.section]}</th><td>${esc(r.material)}</td><td>${fmt(r.horizontal_area_m2)}</td><td>${floorRange(r.material_volume_range_m3)}</td></tr>`).join('')}</tbody></table></div></details>
   <p>Чистовой пол холла № 14 подрезан по бетону Пм 1, в том числе по отверстию ВК-1 площадью ${fmt(vent)} м². Ламинат заканчивается вровень с гранью верхнего подступенка по всей ширине марша.</p>
   ${reference_sheets.map(([album,page,label])=>sheetBtn(album,page,label)).join('')}`);
  const select=$('floor-finish-type'),range=$('floor-finish-range');
  try{
   floorFinishRenderer=new HouseGL($('floor-finish-canvas'),()=>{});
   floorFinishRenderer.yaw=-.48;floorFinishRenderer.pitch=1.18;
  }catch(error){
   $('floor-finish-canvas').hidden=true;
   $('floor-finish-canvas').parentElement.append(document.createTextNode(error.message));
  }
  const refresh=()=>drawFloorFinishSection(types[Number(select.value)-1],Number(range.value));
  select.onchange=refresh;range.onchange=refresh;refresh();
 });
}

function drawFloorFinishSection(type,end){
 const g=floorFinishRenderer,platform=type.section==='platform',top=Number(type.finish_z_mm);
 const lower=Number(type.structural_z_mm),reference=Number(type.structural_reference_depth_mm);
 const vary=type.layers.some(row=>row.depth_mm?.[0]!==row.depth_mm?.[1]);
 const colors=[[.73,.46,.28],[.24,.48,.57],[.54,.59,.55],[.19,.41,.54],[.83,.61,.29],[.54,.56,.58],[.77,.68,.47]];
 $('floor-finish-range-label').hidden=!vary;
 const note=platform?
  'Исходный состав типа 6 показан над действующей отметкой Фм 1. Ширина образца условная.':
  'Отметки и толщины сохранены в масштабе. Слои без указанной толщины показаны в таблице. Ширина образца условная.';
 $('floor-finish-section-note').textContent=note+` Разность в этом разрезе ${fmt(type.level_difference_mm[1-end])} мм.`;
 $('floor-finish-layers').innerHTML=`<div class="table-wrap"><table><thead><tr><th>Слой сверху вниз</th><th>Подпись, толщина или высота</th><th>Площадь, м²</th><th>Объём, м³</th></tr></thead><tbody>
 ${type.layers.map(row=>{
  const fact=FACTS.get(row.dimension_fact_id),label=fact?`${fact.raw_value} ${fact.unit==='um'?'мкм':unit(fact.unit)}${row.upturn_height_mm?' · заведение':''}`:'—';
  return `<tr><th>${factBtn(row.material_fact_id,row.material)}</th><td>${fact?factBtn(row.dimension_fact_id,label):label}</td><td>${row.horizontal_area_m2===null?'—':fmt(row.horizontal_area_m2)}</td><td>${floorRange(row.material_volume_range_m3)}</td></tr>`;
 }).join('')}</tbody></table></div>`;
 if(!g)return;
 g.clear();
 const concrete=g.addLayer('floor-reference',[.52,.57,.55],{order:0});
 g.box(concrete,-520,-275,lower-reference,520,275,lower,'floor-reference');
 let z=top,layerIndex=0;
 for(const row of type.layers){
  if(!row.depth_mm||row.basis==='existing_structure_reference'&&!platform)continue;
  const below=z-Number(row.depth_mm[end]);
  const layer=g.addLayer(row.id,colors[layerIndex++%colors.length],{order:1});
  g.box(layer,-500,-250,below,500,250,z,row.id);
  z=below;
 }
 const measure=g.addLayer('floor-datum',[.76,.26,.14],{showEdges:true,order:2});
 if(z>lower+.201){
  g.line(measure,[530,0,lower],[530,0,z]);
  for(const value of [lower,z])g.line(measure,[510,0,value],[555,0,value]);
  g.labels=[{text:fmt(z-lower)+' мм',p:[580,0,(z+lower)/2],layer:'floor-datum'}];
 }
 g.target=[0,0,(top+lower-reference)/2];
 g.span=Math.max(1600,(top-lower+reference)*2)*g.fitAspect();
 g.pan=[0,0];g.commit();g.request();
}

