'use strict';

const partWorldAxes=[[1,0,0],[0,1,0],[0,0,1]];

function bindPartInspection(host,part){
 const button=document.createElement('button');
 button.type='button';
 button.className='part-inspect-open';
 button.textContent='Осмотреть в 3D';
 host.after(button);
 button.onclick=()=>withResources(['renderer'],()=>{
  if(button.isConnected)openPartInspection(part);
 });
}

function openPartInspection({title,source,sheets=[],faces,outlines,color,axes=partWorldAxes,origin=[0,0,0],names=['X','Y','Z'],placement}){
 const local=p=>axes.map(axis=>contactDot(contactSub(p,origin),axis));
 const geometry=faces.map(face=>face.map(local));
 const bounds=axes.map(()=>[Infinity,-Infinity]);
 for(const face of geometry)for(const p of face)p.forEach((v,i)=>{
  bounds[i][0]=Math.min(bounds[i][0],v);
  bounds[i][1]=Math.max(bounds[i][1],v);
 });
 if(!bounds.every(pair=>pair.every(Number.isFinite))){toast('Для этой позиции доступна схема на листе.');return;}
 const size=bounds.map(([lo,hi])=>hi-lo);
 const centre=bounds.map(([lo,hi])=>(lo+hi)/2);
 const length=Math.max(...size),axis=size.indexOf(length);
 const crossSize=Math.max(...size.filter((_,i)=>i!==axis));
 const longPart=length>crossSize*3;
 const dialog=document.createElement('dialog');
 dialog.id='part-inspection';
 dialog.setAttribute('aria-labelledby','part-title');
 dialog.innerHTML=`<header><div><small>${esc(source)}</small><h2 id="part-title">${esc(title)}</h2></div><button data-action="close" aria-label="Закрыть осмотр">Закрыть</button></header>
  <div class="part-stage"><canvas tabindex="0" aria-label="Деталь в 3D. Стрелки — вращение, Shift и стрелки — сдвиг, плюс и минус — масштаб"></canvas>
  <div class="part-zoom"><button data-action="in" aria-label="Приблизить">+</button><button data-action="out" aria-label="Отдалить">−</button></div></div>
  <footer><p class="part-size" hidden>Габариты по модели, мм · ${size.map((v,i)=>`<span>${esc(names[i])} ${fmt(v,2)}</span>`).join(' ')}</p>
  <div class="part-commands">${sheets.map(([s,p])=>sheetBtn(s,p)).join('')}<button data-action="home">Деталь целиком</button>${longPart?'<button data-action="first">Торец А</button><button data-action="last">Торец Б</button>':''}<button data-action="turn">С другой стороны</button><button data-action="sizes" aria-pressed="false">Размеры</button>${placement?'<button data-action="place">Место установки</button>':''}</div>
  <small class="part-help"></small></footer>`;
 document.body.append(dialog);
 dialog.showModal();
 const canvas=dialog.querySelector('canvas');
 let g;
 dialog.addEventListener('close',()=>{g?.dispose();dialog.remove();},{once:true});
 const close=()=>dialog.close();
 dialog.querySelector('[data-action=close]').onclick=close;
 try{
  g=new HouseGL(canvas);
  const layer=g.addLayer('part',color||[.72,.60,.42]);
  for(const face of geometry){
   g.face(layer,face);
   if(!outlines?.length)g.polyline(layer,face,true);
  }
  if(outlines)for(const line of outlines)g.polyline(layer,line.map(local));
  const dimensions=g.addLayer('dimensions',[.65,.30,.14],{visible:false});
  const corner=bounds.map(([lo])=>lo);
  for(let i=0;i<3;i++){
   const end=[...corner];end[i]+=size[i];
   g.line(dimensions,corner,end);
  }
  g.commit();
  const yaw=.38,pitch=1.12;
  // Project the local bounding box about its midpoint. Fit either limiting screen axis.
  const width=Math.abs(Math.cos(yaw))*size[0]+Math.abs(Math.sin(yaw))*size[1];
  const height=Math.sin(yaw)*Math.cos(pitch)*size[0]+Math.cos(yaw)*Math.cos(pitch)*size[1]+Math.sin(pitch)*size[2];
  g.viewWidthRatio=width/Math.max(height,.01);
  g.minSpan=Math.max(.1,Math.min(crossSize,length)/30);
  g.homeView={target:centre,yaw,pitch,span:Math.max(height,1)*1.18};
  g.home();
  function focusEnd(side){
   // Use the vertices nearest the end so that a sloped cut stays in the frame.
   const end=bounds[axis][side],samples=[];
   for(const face of geometry)for(const p of face)if(Math.abs(p[axis]-end)<=crossSize*.5)samples.push(p);
   g.target=centre.map((v,i)=>i===axis?end:samples.reduce((sum,p)=>sum+p[i],0)/samples.length);
   g.span=Math.max(crossSize*2.7,length*.035)*Math.max(1,canvas.clientHeight/canvas.clientWidth);
   g.pan=[0,0];g.request();
  }
  const actions={
   home:()=>g.home(),first:()=>focusEnd(0),last:()=>focusEnd(1),
   in:()=>g.zoom(.72),out:()=>g.zoom(1/.72),
   turn:()=>{g.yaw+=Math.PI;g.request();},
   sizes:button=>{
    const row=dialog.querySelector('.part-size');
    row.hidden=!row.hidden;dimensions.visible=!row.hidden;g.request();
    button.setAttribute('aria-pressed',String(!row.hidden));
   },
   place:()=>{close();placement();}
  };
  for(const button of dialog.querySelectorAll('[data-action]')){
   const act=actions[button.dataset.action];
   if(act)button.onclick=()=>act(button);
  }
  dialog.querySelector('.part-help').textContent=matchMedia('(pointer: coarse)').matches
   ?'Одним пальцем вращайте деталь, двумя — приближайте и сдвигайте.'
   :'Тяните мышью для вращения. Shift — сдвиг, колесо — масштаб у курсора.';
  canvas.focus({preventScroll:true});
 }catch(error){
  close();toast(error.message);
 }
}

function showPartInScene(){
 if($('panel-dialog')?.open)$('panel-dialog').close();
 if($('construction-inspector'))$('construction-inspector').open=false;
 if($('construction-controls'))$('construction-controls').open=false;
 $('viewport').scrollIntoView({block:'center'});
}

