// Fit the archived short timber to the two bodies emitted by the current frame.
function currentWindow17Detail(source,selected=MODEL.roof_frame.window17_rafter){
 const window=roofWindowSpecs().find(s=>s.location.room_id==='17');
 const header=roofWindowFrameMembers().find(m=>m.window_id===window.id);
 const diagonal=roofFrameMember('diagonal-2');
 const stock=source.components.find(p=>p.id==='rafter-ok11-head-trial');
 const components=[header,diagonal,...['rafter-77','rafter-78'].map(roofFrameMember)].map(member=>{
  const solids=frameDisplaySolids(member).map(body=>body.faces);
  return window17Component(member.id,member.label,solids,member.a_mm,frameAxes(framePieces(member)[0]));
 });
 let fitted=selected?.fitted_envelope_faces_mm??stock.solids;
 if(!selected)for(const support of components.slice(0,2)){
  for(const faces of support.solids){
   const obstacle=roofContactSolid(support.id,'',faces);
   fitted=fitted.flatMap(timber=>subtractFrameOverlap(timber,obstacle));
  }
 }
 components.unshift(window17Component(stock.id,stock.label,fitted,stock.dimensions.origin_mm,stock.dimensions.axes));
 return {...source,components,membrane_patch_mm:null,default_part:stock.id,
  notes:['Короткое стропило подрезано по верхней поперечине и диагонали № 2 действующей сборки. Поперечина примыкает торцами к стропилам № 77 и 78. Крепление поперечины, опирание стропила и удержание от отрыва требуют расчёта.']};
}
function window17Component(id,label,solids,origin,axes){
 const vertices=solids.flat(2);
 const extents=axes.map(axis=>{
  const values=vertices.map(p=>contactDot(contactSub(p,origin),axis));
  return [Math.min(...values),Math.max(...values)];
 });
 return {id,label,group:'wood',kind:'solid_faces',solids,dimensions:{origin_mm:origin,axes,extents_mm:extents}};
}
