const roofDrainageNames={
 horizontal_eave:'Карнизы',valley:'Ендовы',height_step:'Перепады скатов',
 plane_residual:'Стыки с перепадом до 3 мм',opening:'Проходки и окна',
 hip:'Наклонные рёбра',ridge:'Коньки',rake:'Наклонные торцы',unmatched:'Границы без привязки',
};
function roofDrainageLabel(row){
 const tails={west:'запад',east:'восток',north:'север',south:'юг'};
 if(row.kind==='horizontal_eave')return 'Карниз '+row.id.split('-')[1]+(row.side?' · '+tails[row.side]:'');
 if(row.kind==='opening')return row.opening_kind==='shaft'?'ВК-'+row.id.slice(4):'ОК-11 · помещение '+row.room_id;
 if(row.kind==='unmatched')return 'Границы без привязки';
 const number=row.id.split(/[-_]/).at(-1);
 return row.kind==='valley'?'Ендова · участок '+number:
  row.kind==='height_step'?'Перепад скатов '+number:'Стык плоскостей '+number;
}
