function focusRoofDrainage(id){
 const row=MODEL.roof_geometry.drainage.rows.find(item=>item.id===id);
 $('source-dialog').close();
 return activateTab(constructionViewer?'roof':'model','roof',()=>{
  const g=renderer;
  roofFrameState.coverHidden=false;
  applyRoofCover(g);
  const surface=g.addLayer('roofDrainage',[.14,.57,.60],{order:27,depthBias:g.layers.get('roof').depthBias,showEdges:false});
  const arrows=g.addLayer('roofDrainageArrows',[.99,.91,.59],{order:28,showEdges:false});
  const raised=([x,y,z],lift)=>[x,y,z+lift];
  const objectId='drainage:'+row.id;
  LAYER_META.roofDrainage=['Площадь стока · '+roofDrainageLabel(row),surface.color];
  LAYER_META.roofDrainageArrows=['Направление стока',arrows.color];
  for(const patch of row.patches)g.face(surface,patch.polygon_mm.map(p=>raised(p,8)),[0,0,1],objectId);
  for(const patch of [...row.patches].sort((a,b)=>b.area_m2-a.area_m2).slice(0,8)){
   const from=raised(patch.from_mm,54),to=raised(patch.to_mm,54),delta=to.map((v,i)=>v-from[i]);
   const h=Math.hypot(delta[0],delta[1]);
   if(h<5)continue;
   const arrowSize=Math.min(240,h*.28),base=to.map((v,i)=>v-delta[i]*arrowSize/h);
   const side=[-delta[1]/h*arrowSize*.45,delta[0]/h*arrowSize*.45,0];
   g.tube(arrows,from,to,23,6);
   for(const sign of [-1,1])g.tube(arrows,to,base.map((v,i)=>v+side[i]*sign),23,6);
  }
  if(row.points_mm?.every(point=>point.length===3)){
   const line=row.points_mm.map(p=>raised(p,24));
   g.tube(arrows,line[0],line[1],22,8);
  }
  const points=row.patches.flatMap(patch=>patch.polygon_mm);
  if(points.length){
   const bounds=[0,1,2].map(i=>[Math.min(...points.map(p=>p[i])),Math.max(...points.map(p=>p[i]))]);
   g.target=bounds.map(([lo,hi])=>(lo+hi)/2);
   g.span=Math.max(4400,Math.hypot(...bounds.slice(0,2).map(([lo,hi])=>hi-lo))*1.28)*g.fitAspect();
  }
  g.yaw=0;g.pitch=.12;g.pan=[0,0];g.labels=[];
  expInfo(g,objectId,{title:roofDrainageLabel(row),note:`Прямая площадь стока в плане ${fmt(row.area_m2,6)} м². Трасса после первой границы открыта.`,
   facts:['roof.pitch'],sheets:[['house_1',9],['house_1',19]]});
  g.commitLayer(surface);g.commitLayer(arrows);indexSceneObjects(g);
  renderLayerControls();g.request();
 });
}
