function drawUpperFloor(g,wallLayer,visible){
 const frame=addLayer(g,'upperFrame',{visible,explodeOrder:3,order:14});
 const belt=g.addLayer('roofBelt',[.53,.57,.58],{visible,explodeOrder:3,order:14});
 LAYER_META.roofBelt=['Монолитный пояс Мп 2',[.53,.57,.58]];
 belt.useTint=true;belt.faceTints=[];
 const addRun=(run,color)=>{
  const start=belt.vertices.length;
  const [x0,y0,x1,y1]=run.bounds_mm;
  if(run.cad_mesh)emitCadMesh(g,belt,run.cad_mesh,run.id);
  else if(run.top_limit_plane){
   for(const piece of roofBeltInsulationPrisms(run))HouseShapes.prism(g,belt,piece,run.id);
  }else g.box(belt,x0,y0,run.bottom_mm,x1,y1,run.top_mm,run.id);
  for(let i=start;i<belt.vertices.length;i+=6)belt.faceTints.push(...color);
 };
 for(const run of MODEL.floor2.roof_belt.runs)addRun(run,belt.color);
 for(const strip of MODEL.floor2.roof_belt.insulation)addRun(strip,[.71,.47,.28]);
 drawUpperLintels(g,visible);
 if(mode==='floor2'){
  drawRoofBeltSteel(g);
  const rebar=MODEL.floor2.masonry_takeoff.reinforcement.variants.find(v=>v.id===upperRebarViewId);
  drawMasonrySteel(g,rebar,()=>true,true);
 }
 const z=(plane,p)=>plane[0]*p[0]+plane[1]*p[1]+plane[2];
 const wallPieces=mode==='floor2'?MODEL.floor2.course_prisms:MODEL.floor2.mesh_prisms.flatMap(mesh=>wallDisplayPieces(mesh));
 for(const piece of wallPieces){
  const l=piece.material==='frame'?frame:wallLayer,p=piece.polygon_mm,id='upperwall:'+piece.wall_id;
  const low=p.map(q=>[...q,z(piece.bottom_plane,q)]),high=p.map(q=>[...q,z(piece.top_plane,q)]);
  drawUpperWallFace(g,l,high,[-piece.top_plane[0],-piece.top_plane[1],1],id);
  drawUpperWallFace(g,l,[...low].reverse(),[piece.bottom_plane[0],piece.bottom_plane[1],-1],id);
  for(let i=0;i<p.length;i++){const j=(i+1)%p.length;drawUpperWallFace(g,l,[low[i],low[j],high[j],high[i]],null,id);}
 }
}
function drawUpperLintels(g,visible=true,limit=Infinity){
 const concrete=addLayer(g,'upperLintels',{visible,explodeOrder:3,order:14});
 const insulation=addLayer(g,'upperLintelXps',{visible,explodeOrder:3,order:14});
 for(const lintel of MODEL.floor2.lintels.runs)for(const part of lintel.parts){
  const layer=part.material==='concrete'?concrete:insulation;
  for(const visiblePart of courseContextBelow(part,limit))HouseShapes.prism(g,layer,visiblePart,lintel.id);
 }
 if(g!==renderer)return;
 const probe=MODEL.floor2.lintels.south_dormer_fronton;
 const run=MODEL.floor2.lintels.runs.find(r=>r.id===probe.lintel_id);
 const [concreteHit,xpsHit,aac,timber]=dormerFrontonLayers.map((id,i)=>addLayer(g,id,{visible:false,
  opacity:i===3?.25:.88,explodeOrder:3,order:16+i}));
 for(const row of probe.rows){
  const id='roof:dormer-fronton';
  for(const part of row.overlaps)HouseShapes.prism(g,part.material==='concrete'?concreteHit:xpsHit,part,id);
  for(const patch of row.aac_patches_mm)g.face(aac,patch.map(p=>[...p,row.seat_level_mm+.05]),[0,0,1],id);
  const hit=run.dormer_conflicts.find(hit=>hit.member_id===row.member_id);
  const [x,y,z,X,Y,Z]=hit.timber_bounds_mm;
  g.box(timber,x,Math.max(y,hit.pocket_bounds_mm[1]-200),z,X,Math.min(Y,hit.pocket_bounds_mm[4]+200),Z,id);
 }
}
const dormerFrontonLayers=['upperLintelConflict','upperLintelXpsConflict','dormerFrontonAac','dormerFrontonTimber'];
