const roofBeltSteelLayers=['roofBeltLongitudinal','roofBeltVertical','roofBeltTransverse'];
function drawRoofBeltSteel(g){
 const register=MODEL.floor2.roof_belt.material_register;
 const layers=roofBeltSteelLayers.map(id=>addLayer(g,id,{visible:false,order:15,explodeOrder:3}));
 const radii=register.positions.map(row=>+row.diameter.value/2);
 for(const run of register.runs)run.positions.forEach((bars,i)=>{
  for(const [a,b] of bars)g.tube(layers[i],a,b,radii[i],8,run.run_id);
 });
}
