function showBeamPinCase(id,pos){
 $('source-dialog').close();
 return activateTab(constructionViewer?'foundation':'model','rebar',()=>{
  const g=renderer,s=MODEL.foundation.beam_pin_study;
  const c=s.comparisons.find(row=>row.id===id),sample=c.samples[pos],profile=c.profiles[pos];
  for(const layer of g.layers.values())layer.visible=false;
  const pins=addLayer(g,'pinCasePins',{showEdges:false}),longitudinal=addLayer(g,'pinCaseLong',{showEdges:false});
  const starters=addLayer(g,'pinCaseStarters',{showEdges:false}),concrete=addLayer(g,'pinCaseConcrete');
  for(const rod of [...sample.pins,...sample.context]){
   const layer=rod.position===pos?pins:rod.position===6?longitudinal:starters;
   rod.points_mm.slice(1).forEach((p,i)=>g.tube(layer,rod.points_mm[i],p,rod.diameter_mm/2,16,layer.id));
  }
  const [x,y]=sample.focus_mm,along=sample.station_axis;
  const half=n('foundation.Фм1.'+(pos===5?'external':'internal')+'_beam_width')/2;
  const frame=along===0?[[x-250,y-half],[x+250,y-half],[x+250,y+half],[x-250,y+half]]:
   [[x-half,y-250],[x+half,y-250],[x+half,y+250],[x-half,y+250]];
  for(const z of [-500,-130])g.polyline(concrete,frame.map(p=>[...p,z]),true);
  for(const layer of [pins,longitudinal,starters,concrete])g.commitLayer(layer);
  g.labels=[];g.homeView={target:sample.focus_mm,yaw:along===0?-.60:.97,pitch:.54,span:1050};g.home();
  $('scene-title').textContent=pinLocationLabels[pos]+' · поз. '+pos;
  $('scene-status').textContent='Примерка шпильки';
  $('scene-notice').textContent=pinGaugeLabels[id]+'.';
  $('experience-tools').innerHTML='';
  $('rebar-tools').innerHTML=`<p>Радиус оси ${fmt(profile.hook_axis_radius_mm)} мм. Просвет к продольному стержню ${fmt(profile.radial_clearance_to_bar_mm)} мм.</p><div class="buttons-row">
   <button data-beam-pin-case="${id==='axis'?'steel':'axis'}" data-pin-pos="${pos}">${pinGaugeLabels[id==='axis'?'steel':'axis']}</button>
   <button data-beam-pin-study>Сравнение и источники</button><button id="beam-pin-back">К общей схеме</button></div>`;
  $('beam-pin-back').onclick=()=>buildScene('rebar');
  $('inspector').innerHTML=`<h3>${pinLocationLabels[pos]}</h3><p>Фиолетовые шпильки охватывают жёлтые продольные стержни поз. 6. Стойки поз. 4 показаны красным.</p>${sheetBtn('house_2',8,'КЖ-3 · сечение')}${sheetBtn('house_2',9,'КЖ-4 · эскиз')}`;
  indexSceneObjects(g);renderLayerControls();g.request();
 });
}
const longitudinalViewLabels={overview:'Все трассы',corner:'Южный угол',junction:'Примыкание по оси Е'};
function openBeamLongitudinalStudy(){
 return prepareDialog(['foundation','facts'],()=>{
  const s=MODEL.foundation.beam_longitudinal_study;
  const t=s.trial,ends=s.internal_ends.filter(e=>!e.opening_id);
  const gaps=ends.map(e=>e.centreline_gap_mm);
  showDialog('ФМ 1 / КЖ-2…4 / I017','Продольная арматура ростверков · позиция 6',`
   <p>По КЖ-3 четыре стержня на сечение, по два в каждом ярусе. На КЖ-4 указаны Ø8 А500С и погонная длина. Отметки осей в модели −0,220 и −0,420 м.</p>
   ${gateRebarNote}
   <div class="table-wrap"><table id="longitudinal-quantities"><thead><tr><th>Раскладка</th><th>Длина, м</th><th>Масса, кг</th><th>Трассы</th></tr></thead><tbody>
   <tr><th>Ведомость КЖ-4</th><td>${fmt(s.issued.length_m)}</td><td>${fmt(s.issued.mass_kg,3)}</td><td>—</td></tr>
   <tr><th>Базовая схема</th><td>${fmt(s.baseline.length_m)}</td><td>${fmt(s.baseline.mass_kg,3)}</td><td>${s.baseline.trace_count}</td></tr>
   <tr><th>Проба с сопряжениями</th><td>${fmt(t.length_m,3)}</td><td>${fmt(t.mass_kg,3)}</td><td>${t.paths.length}</td></tr>
   </tbody></table></div>
   <p>Сопряжение осей в наружных углах даёт те же ${fmt(t.orthogonal_m)} м. При пробном радиусе по оси ${t.bend_radius_mm} мм получено ${t.bend_count} загибов. До боковых граней остаётся от ${fmt(t.side_cover_mm)} мм. У ${ends.length} торцов внутренних трасс расстояние до соседней оси ${fmt(Math.min(...gaps),3)}–${fmt(Math.max(...gaps),3)} мм. Рабочие примыкания, анкеровка и загибы требуют привязки.</p>
   <p>Обе прямые продольные оси проходят через загибы ${s.pin_support.pins_on_two_straight_axes} из ${s.pin_support.checked_pins} шпилек. Угловые шпильки из оставшихся позиций требуют увязки с поворотами продольных трасс.</p>
   <div class="buttons-row">${Object.entries(longitudinalViewLabels).map(([id,name])=>`<button data-longitudinal-view="${id}">${name} · 3D</button>`).join('')}</div>
   <h3>Чувствительность расхода к стыкам</h3>
   <p>До количества КЖ-4 остаётся ${fmt(t.remaining_to_issued_m,3)} м. В таблице приведены нижние оценки по длине. Прямые зоны стыков, анкеровка и остатки мерных стержней открыты. Деталь 600 мм на КЖ-2 относится к полевым сеткам Ø12.</p>
   <div class="table-wrap"><table id="longitudinal-stock"><thead><tr><th>Предел детали, м</th><th>Пробная длина стыка, мм</th><th>Отрезки, от</th><th>Стыки, от</th><th>Длина, от, м</th></tr></thead><tbody>
   ${s.stock_sensitivity.map(r=>`<tr><td>${r.stock_mm/1000}</td><td>${r.test_overlap_mm}</td><td>${r.minimum_pieces}</td><td>${r.minimum_joints}</td><td>${fmt(r.minimum_length_m,3)}</td></tr>`).join('')}</tbody></table></div>
   <div class="dialog-links">${sheetBtn('house_2',7,'КЖ-2 · план ростверков')}${sheetBtn('house_2',8,'КЖ-3 · сечения')}${sheetBtn('house_2',9,'КЖ-4 · поз. 6')}</div>`);
 });
}
function showBeamLongitudinalView(id,joined=true){
 $('source-dialog').close();
 return activateTab(constructionViewer?'foundation':'model','rebar',()=>{
  const g=renderer,f=MODEL.foundation,s=f.beam_longitudinal_study,view=s.views[id];
  for(const layer of g.layers.values())layer.visible=false;
  const upper=addLayer(g,'longitudinalUpper',{showEdges:false}),lower=addLayer(g,'longitudinalLower',{showEdges:false});
  const concrete=addLayer(g,'longitudinalConcrete');
  const draw=points=>{
   const layer=points[0][2]>-300?upper:lower;
   points.slice(1).forEach((p,i)=>g.tube(layer,points[i],p,s.trial.diameter_mm/2,12,layer.id));
  };
  if(view){
   for(const points of joined?view.trial_paths_mm:view.baseline_paths_mm)draw(points);
  }else for(const route of s.trial.paths)for(const part of route.parts){
   if(part.kind==='line'){
    draw(part.points_mm);
    continue;
   }
   const a=part.points_mm[0],b=part.points_mm[2],o=part.centre_mm;
   draw(Array.from({length:9},(_,i)=>o.map((v,k)=>v+(a[k]-v)*Math.cos(i*Math.PI/16)+(b[k]-v)*Math.sin(i*Math.PI/16))));
  }
  const concreteEdges=view?view.concrete_edges_mm:f.plinth.boundary_edges_mm;
  for(const edge of concreteEdges)g.line(concrete,[...edge[0].map(Number),-130],[...edge[1].map(Number),-130]);
  for(const layer of [upper,lower,concrete])g.commitLayer(layer);
  g.labels=[];g.homeView=view?{target:[...view.centre_mm,-280],yaw:-.66,pitch:.85,span:1740}:
   {target:[7000,7900,-280],yaw:-.45,pitch:1.28,span:20500};g.home();
  $('scene-title').textContent=longitudinalViewLabels[id]+' · поз. 6';
  $('scene-status').textContent=joined?'Проба сопряжений':'Прямые оси';
  $('scene-notice').textContent=id==='junction'?'У внутренних ветвей показаны торцы перед примыканием.':'Синим и жёлтым показаны оси двух ярусов. У восточного простенка ворот оси доведены до грани бетона для предварительного обмера. Рабочая длина стержней уточняется расчётом.';
  $('experience-tools').innerHTML='';
  $('rebar-tools').innerHTML=`<div class="buttons-row">${view?`<button id="longitudinal-toggle">${joined?'Прямые оси':'Показать сопряжения'}</button>`:''}
   <button data-beam-longitudinal-study>Сравнение и источники</button><button id="longitudinal-back">К общей схеме</button></div>`;
  if(view)$('longitudinal-toggle').onclick=()=>showBeamLongitudinalView(id,!joined);
  $('longitudinal-back').onclick=()=>buildScene('rebar');
  $('inspector').innerHTML=`<h3>${longitudinalViewLabels[id]}</h3><p>Наружные оси соединены по углам. Разрывы под проёмами и торцы внутренних ветвей видны в модели.</p>${sheetBtn('house_2',7,'КЖ-2 · план')}${sheetBtn('house_2',9,'КЖ-4 · ведомость')}`;
  indexSceneObjects(g);renderLayerControls();g.request();
 });
}
const edgeMeshZoneLabels={source_return:'Верхний уступ КЖ-2',free_upper_side:'Верхний свободный участок восточной кромки'};
const edgeMeshModeLabels={baseline:'Поле 200 мм',replacement:'Замена в полосе',supplement:'Добавка к полю 200 мм'};
function openEdgeMeshStudy(){
 return prepareDialog(['foundation','facts'],()=>{
  const s=MODEL.foundation.edge_mesh_study;
  showDialog('ФМ 1 / КЖ-2 И КЖ-3 / I015','Верхняя сетка у края · шаг 150 мм',`
   <p>На КЖ-2 сечение 3–3 пересекает северный участок восточной кромки. На КЖ-3 выноска «поз. 2 ш.150» указывает на оба направления верхней сетки. Граница полосы в плане открыта.</p>
   <p>Ширина полосы ${s.width_mm} мм принята для сравнения по длине лапы хомута поз. 7. Для одной границы сохранён диапазон Y исходного верхнего уступа. Вторая охватывает весь верхний свободный участок кромки. Исходное положение кромки X = ${fmt(s.historic_edge_x_mm)} мм, действующее X = ${fmt(s.recent_edge_x_mm)} мм.</p>
   <div class="table-wrap"><table id="edge-mesh-quantities"><thead><tr><th>Граница и вариант</th><th>Вся верхняя сетка, м</th><th>Добавка, м</th><th>Добавка, кг</th><th>Торцы на переходе</th><th>3D</th></tr></thead><tbody>
   ${s.zones.map(z=>`<tr><th colspan="6">${edgeMeshZoneLabels[z.id]} · Y ${fmt(z.bounds_mm[1])}–${fmt(z.bounds_mm[3])} мм</th></tr>${z.variants.map(v=>`<tr data-edge-mesh-row="${z.id}-${v.id}"><th>${edgeMeshModeLabels[v.id]}</th><td>${fmt(v.total_m,3)}</td><td>${fmt(v.delta_m,3)}</td><td>${fmt(v.delta_mass_kg,3)}</td><td>${fmt(v.seam_ends.length)}</td><td><button data-edge-mesh-zone="${z.id}" data-edge-mesh-mode="${v.id}">Открыть</button></td></tr>`).join('')}`).join('')}</tbody></table></div>
   <p>При замене шаг внутри полосы 150 мм в обоих направлениях. При добавке сохранены все оси полевой сетки, шаги в полосе 50–150 мм. Совпадающие отрезки учтены один раз. В таблице приведена чистая длина. Нахлёсты, анкеровка торцов и рабочая граница сгущения остаются открытыми.</p>
   <div class="dialog-links">${sheetBtn('house_2',7,'КЖ-2 · выноска сечения')}${sheetBtn('house_2',8,'КЖ-3 · сечение 3–3')}${sheetBtn('house_2',9,'КЖ-4 · ведомость')}</div>`);
 });
}
function showEdgeMeshZone(zoneId,mode){
 $('source-dialog').close();
 return activateTab(constructionViewer?'foundation':'model','rebar',()=>{
  const g=renderer,f=MODEL.foundation,s=f.edge_mesh_study;
  const zone=s.zones.find(z=>z.id===zoneId),v=zone.variants.find(row=>row.id===mode);
  for(const layer of g.layers.values())layer.visible=false;
  const alongX=addLayer(g,'edgeMeshX',{showEdges:false}),alongY=addLayer(g,'edgeMeshY',{showEdges:false});
  const guide=addLayer(g,'edgeMeshOutline'),ends=addLayer(g,'edgeMeshEnds',{showEdges:false});
  for(const rod of v.preview){
   const [a,b]=rod.points_mm,layer=a[0]===b[0]?alongY:alongX;
   g.tube(layer,a,b,rod.diameter_mm/2,12,layer.id);
  }
  for(const end of v.seam_ends){
   const [x,y,z]=end.point_mm;
   if(end.axis==='X')g.tube(ends,[x,y-17,z+10],[x,y+17,z+10],3,8,ends.id);
   else g.tube(ends,[x-17,y,z+10],[x+17,y,z+10],3,8,ends.id);
  }
  const [x0,y0,x1,y1]=zone.bounds_mm;
  const z=n('foundation.Фм1.top_elevation')*1000;
  g.polyline(guide,[[x0,y0,z],[x1,y0,z],[x1,y1,z],[x0,y1,z]],true);
  for(const layer of [alongX,alongY,ends,guide])g.commitLayer(layer);
  g.labels=[];g.homeView={target:[x0-100,(y0+y1)/2-40,-560],yaw:-.63,pitch:1.2,span:(y1-y0)*1.24};g.home();
  $('scene-title').textContent=edgeMeshZoneLabels[zoneId];
  $('scene-status').textContent=edgeMeshModeLabels[mode];
  $('scene-notice').textContent='Рамка показывает пробную границу сгущения. Красные метки показывают торцы на переходе.';
  $('experience-tools').innerHTML='';
  $('rebar-tools').innerHTML=`<p>К полевой раскладке ${fmt(v.delta_m,3)} м. Торцы на переходе ${v.seam_ends.length}.</p><div class="buttons-row">
   ${zone.variants.filter(row=>row.id!==mode).map(row=>`<button data-edge-mesh-zone="${zoneId}" data-edge-mesh-mode="${row.id}">${edgeMeshModeLabels[row.id]}</button>`).join('')}
   <button data-edge-mesh-study>Сравнение и источники</button><button id="edge-mesh-back">К общей схеме</button></div>`;
  $('edge-mesh-back').onclick=()=>buildScene('rebar');
  $('inspector').innerHTML=`<h3>${edgeMeshModeLabels[mode]}</h3><p>Синий цвет показывает направление X, зелёный — Y.</p>${sheetBtn('house_2',8,'КЖ-3 · сечение 3–3')}`;
  indexSceneObjects(g);renderLayerControls();g.request();
 });
}
function openFoundationSpliceStudy(){
 return prepareDialog(['foundation','facts'],()=>{
  const study=MODEL.foundation.splice_study;
  const short=study.scenarios[0],long=study.scenarios[1];
  const stockAlternative=short.stock_comparison.find(row=>row.blanks<short.pooled_stock.count);
  const proof=short.directions.flatMap(d=>d.disjoint_forced_pairs),sample=proof[0];
  showDialog('ФМ 1 / КЖ-2 И КЖ-4 / I017','Нахлёсты полевых сеток Фм 1',`
   <p>Длина нахлёста ${factBtn('foundation.Фм1.lap_length',fmt(study.lap_length_mm)+' мм')}, чистый промежуток между нахлёстами соседних рядов ${factBtn('foundation.Фм1.lap_min_stagger',fmt(study.clear_between_laps_mm)+' мм')}. В каждом ярусе ${fmt(short.per_mesh.projected_without_laps_m)} м непрерывных линий. В КЖ-4 указано по ${fmt(study.issued_lengths_m[0])} м.</p>
   <div class="table-wrap"><table id="fm1-splice-summary"><thead><tr><th>Предел детали</th><th>Деталей на сетку</th><th>Стыков на сетку</th><th>Сталь на стыки, м</th><th>Всего на сетку, м</th><th>Заготовок на две сетки</th><th>Остаток, м</th></tr></thead><tbody>
   ${study.scenarios.map(trial=>{const q=trial.per_mesh,s=trial.pooled_stock;return `<tr data-fm1-splice-row="${trial.limit_mm}"><th><button data-fm1-splice-view="${trial.limit_mm}">${fmt(trial.limit_mm/1000)} м · 3D</button></th><td>${fmt(q.pieces)}</td><td>${fmt(q.laps)}</td><td>${fmt(q.added_lap_m,3)}</td><td>${fmt(q.cut_length_m,3)}</td><td>${fmt(s.count)}</td><td>${fmt(s.offcut_m,3)}</td></tr>`;}).join('')}
   </tbody></table></div>
   <p>Для 6 м найдено ${fmt(proof.length)} пар без общих стержней, где разбежка требует добавить стык. Например, при X = ${sample.stations_mm.map(mm=>fmt(mm)).join(' и ')} мм первые нахлёсты двух рядов можно разнести максимум на ${fmt(sample.max_start_separation_mm)} мм при нужных ${fmt(study.lap_length_mm+study.clear_between_laps_mm)} мм. Вместе с ${fmt(short.per_mesh.arithmetical_minimum_laps)} стыками по длинам это даёт ${fmt(short.per_mesh.stagger_lower_bound)} на сетку.</p>
   <p>Для 6 м показана раскладка с минимальным числом стыков. ${stockAlternative?`В ещё одной шестиметровой пробе по ${fmt(stockAlternative.laps)} стыков, а на обе сетки уходит ${fmt(stockAlternative.blanks)} заготовки. `:''}В раскрое принят нулевой припуск на рез. Для 12 м длина деталей на две сетки вместе ${fmt(long.both_meshes.cut_length_m,3)} м.</p>
   <h3>Привязки у проходок в плане</h3>
   <div class="table-wrap"><table id="fm1-splice-sleeves"><thead><tr><th>Предел детали</th><th>Гильза</th><th>Рядов в базовой сетке</th><th>Рядов до / после увязки</th><th>Нахлёстов до / после</th><th>Просвет до нахлёста после, мм</th></tr></thead><tbody>
   ${study.scenarios.map(trial=>trial.sleeve_checks_before.filter(site=>site.lap_ids.length||site.baseline_row_ids.length!==site.trial_row_ids.length).map(site=>{
    const after=trial.sleeve_checks.find(row=>row.id===site.id);
    return `<tr><td>${fmt(trial.limit_mm/1000)} м</td><td><button data-fm1-splice-view="${trial.limit_mm}" data-fm1-splice-site="${esc(site.id)}">${esc(site.id)} · 3D</button></td><td>${fmt(site.baseline_row_ids.length)}</td><td>${fmt(site.trial_row_ids.length)} / ${fmt(after.trial_row_ids.length)}</td><td>${fmt(site.lap_ids.length)} / ${fmt(after.lap_ids.length)}</td><td>${fmt(after.minimum_lap_gap_mm,3)}</td></tr>`;
   }).join('')).join('')}</tbody></table></div>
   <p>У К1-4 изменена сторона бокового смещения стержня. У К1-5 перенесены два нахлёста одного ряда. Положение гильз взято по текущим ориентирам. Рабочие допуски, зоны стыков, усиления у проходок и зона шага 150 мм открыты. Для поставки предварительно выбраны прутки по ${fmt(study.preferred_stock_length_mm/1000)} м.</p>
   <div class="dialog-links"><button data-passage-splice-refit>Перенос нахлёстов у К1</button>${sheetBtn('house_2',7,'КЖ-2 · деталь нахлёста')}${sheetBtn('house_2',9,'КЖ-4 · ведомость')}</div>`);
 });
}
function showFoundationSplices(limit,position=1,siteId=null){
 $('source-dialog').close();
 return activateTab(constructionViewer?'foundation':'model','rebar',()=>{
  const g=renderer,foundation=MODEL.foundation,study=foundation.splice_study;
  const scenario=study.scenarios.find(row=>row.limit_mm===limit);
  const seats=foundation.mesh_seat_study,[bottom,top]=seats.concrete_span_mm;
  const axes=seats.cases[0].axes_mm,level=position===1?'lower':'upper';
  for(const layer of g.layers.values())layer.visible=false;
  const steel=addLayer(g,'fm1SpliceSteel',{showEdges:false}),marks=addLayer(g,'fm1SpliceMarks');
  const outline=addLayer(g,'fm1SpliceOutline'),guides=addLayer(g,'fm1SpliceSleeves');
  const radius=study.lateral_axis_spacing_mm/2;
  for(const direction of scenario.directions){
   const z=axes[level+'_'+direction.axis];
   const point=(station,value,base)=>direction.axis==='x'?[value,station,base]:[station,value,base];
   for(const row of direction.rows){
    for(const [i,[station,start,end]] of row.pieces.entries()){
     const overlapEnd=i?row.laps[i-1][1]:start;
     if(i){
      g.tube(marks,point(station,start,z),point(station,overlapEnd,z),radius,8,row.id);
      g.line(marks,point(station,start,z+radius),point(station,overlapEnd,z+radius),marks.id);
     }
     g.tube(steel,point(station,overlapEnd,z),point(station,end,z),radius,8,row.id);
    }
   }
  }
  for(const z of [bottom,top])g.polyline(outline,core.map(p=>[...p,z]),true);
  const sleeves=foundation.sleeve_review.cases;
  g.labels=[];
  for(const check of scenario.sleeve_checks_before){
   if(check.lap_ids.length||check.trial_row_ids.length!==check.baseline_row_ids.length){
    const site=sleeves.find(item=>item.id===check.id),[x,y]=site.centre_mm;
    g.ring(guides,x,y,top,site.diameter_mm/2);
    g.labels.push({text:check.id,p:[x,y,top+40],id:guides.id,layer:guides.id,color:'#953f27'});
   }
  }
  for(const layer of [steel,marks,outline,guides])g.commitLayer(layer);
  const focus=sleeves.find(item=>item.id===siteId);
  if(focus)g.homeView={target:[...focus.centre_mm,top],yaw:0,pitch:.15,span:1850};
  g.home('rebar');
  const q=scenario.per_mesh;
  $('scene-title').textContent='Нахлёсты Фм 1 · детали до '+fmt(limit/1000)+' м';
  $('scene-status').textContent='Примерка раскроя';
  $('scene-notice').textContent='Жёлтые отрезки показывают нахлёсты 600 мм.';
  $('experience-tools').innerHTML='';
  $('rebar-tools').innerHTML=`<label>Сетка <select id="fm1-splice-level"><option value="1">Нижняя</option><option value="2">Верхняя</option></select></label><p>${fmt(q.laps)} стыков на сетку. Жёлтым отмечены нахлёсты, красным — места увязки с гильзами.</p><div class="buttons-row"><button data-fm1-splice-study>Сравнить варианты</button><button id="fm1-splice-back">К общей схеме</button></div>`;
  $('fm1-splice-level').value=position;
  $('fm1-splice-level').onchange=e=>showFoundationSplices(limit,+e.target.value,siteId);
  $('fm1-splice-back').onclick=()=>buildScene('rebar');
  $('inspector').innerHTML=`<h3>${focus?'Гильза '+esc(focus.id):'Нахлёсты полевой сетки'}</h3><p>${fmt(q.pieces)} деталей длиной ${fmt(q.cut_length_m,3)} м на ярус. Высоты показаны в варианте отсчёта 50 мм до осей крайних рядов.</p><button data-fm1-splice-study>Длины, раскрой и проходки</button>${sheetBtn('house_2',7,'КЖ-2 · нахлёсты')}`;
  indexSceneObjects(g);renderLayerControls();g.request();
 });
}
function openRebarLayout(elementOnly=false){
 const s=foundationRebarState,layout=ensureFoundationRebar(),rod=layout.rods.find(r=>r.id===s.selected);
 const reasons={chair_footprint_does_not_fit_scenario_inset:'Лапы фиксатора не помещаются с выбранным отступом',L_profile_needs_corner_or_end_detail:'Нужна деталь Г-стержня у угла/окончания',U_profile_at_corner_needs_working_detail:'Нужна деталь П-стержня у угла'};
 showDialog('КЖ-2…4 / ОБЩАЯ СХЕМА / I015 / I017 / I018',elementOnly&&rod?'Поз.'+rod.position+' · '+rod.id:'Армирование: схема и сверка',`<div class="callout"><b>I015 / I017 · сценарий, не рабочая карта раскроя</b>Показаны 8 позиций. По проекту связаны диаметры, типовые сечения и шаги. Фазы и часть положений ещё условны; неизвестные стыки/радиусы/анкеровка не заменяются предполагаемыми числами.</div>
 <div class="section-grid"><div>${rebarLayoutPlan()}${rod?`<h3>${esc(rod.id)} · координаты осевой линии</h3><div class="formula">${rod.points_mm.map(p=>p.map(v=>fmt(v,6)).join(' / ')).join('<br>')}<br>Σ√(ΔX²+ΔY²+ΔZ²) = ${fmt(rod.visible_axis_length_mm,6)} мм</div><details><summary>Правило вычисления координат</summary><p class="hash">${esc(layout.coordinate_rules[rod.geometry_rule_id].formula)}</p></details><p>Размеры/высоты этой схемы и рабочая длина заготовки — разные величины.</p><details><summary>Все входные записи</summary>${rod.input_fact_ids.map(id=>factBtn(id,FACTS.get(id)?.label+' / '+FACTS.get(id)?.property)).join('<br>')}</details>`:''}</div><div><h3>Количество сцены и ведомость</h3>${rebarComparisonTable()}<p>В погонных метрах сравниваются только непрерывные линии 1/2/6 без стыков и анкеровки. Для остальных позиций сравнивается число изображённых элементов; видимая линия 5/8 не включает крюки. Остатки не скрыты и не подогнаны.</p><p>Исходный итог: ${factBtn('foundation.Фм1.steel_kg_total','5748,9 кг · 5% уже учтены')}</p><button data-mesh-seat-study>Посадка фиксатора</button></div></div>
 <div class="callout"><b>I018 · класс позиции 7</b>В строке 7 напечатано А500, в группе итоговых масс — А500С. Оба написания сохранены; класс изделия автоматически не исправлен.</div><h3 style="margin-top:25px">Изменяемые параметры схемы</h3><p>Это варианты привязки осевых линий. Они не являются подписями проекта и не назначают рабочий защитный слой. Высотное разведение направлений сетки и контакты фиксаторов ещё не восстановлены.</p><form id="rebar-parameters" class="input-grid"><label>Фаза сетки X, мм<input name="phase_x_mm" type="number" min="0" max="199" step="1" value="${s.parameters.phase_x_mm}" required></label><label>Фаза сетки Y, мм<input name="phase_y_mm" type="number" min="0" max="199" step="1" value="${s.parameters.phase_y_mm}" required></label><label>Отступ линий сеток / поз.7, мм<input name="axis_inset_mm" type="number" min="1" max="150" step="1" value="${s.parameters.axis_inset_mm}" required></label><label>Позиция 7 · область<select name="edge_scope"><option value="entire_perimeter_hypothesis" ${s.parameters.edge_scope==='entire_perimeter_hypothesis'?'selected':''}>Весь периметр · гипотеза</option><option value="free_edge_hypothesis" ${s.parameters.edge_scope==='free_edge_hypothesis'?'selected':''}>Свободные края · гипотеза</option></select></label><div><button type="submit">Показать этот сценарий</button></div></form>
 <details style="margin-top:20px"><summary>Прочие условные положения</summary><div class="formula">Фиксаторы: X=${s.parameters.chair_phase_x_mm}, Y=${s.parameters.chair_phase_y_mm} мм; соседние ряды смещены на400 мм при шаге800.<br>Фаза поперечных деталей: ${s.parameters.beam_station_phase_mm} мм.<br>Отступ окончания продольной линии: ${s.parameters.beam_end_inset_mm} мм.<br>Фаза P7 вдоль периметра: ${s.parameters.edge_station_phase_mm} мм.<br>Z линий сеток: ${layout.z_convention.bottom_mm} / ${layout.z_convention.top_mm} мм; направлений по диаметрам здесь не разнесено.<br>Z лап фиксатора: ${layout.z_convention.chair_foot_mm} мм = Z нижней линии + ${s.parameters.chair_base_lift_mm} мм; добавка — условный параметр, контакты схемные.</div></details>
 <details><summary>Участки проверки: ${layout.omissions.length}</summary><table><thead><tr><th>Поз.</th><th>X / Y, мм</th><th>Причина</th></tr></thead><tbody>${layout.omissions.map(o=>`<tr><td>${o.position}</td><td class="number">${o.at_mm.map(v=>fmt(v,3)).join(' / ')}</td><td>${reasons[o.reason]||esc(o.reason)}</td></tr>`).join('')}</tbody></table><p>Эти случаи не заполнены выдуманным гибом; их метки вынесены в отдельный слой3D.</p></details>
 <div class="callout" style="margin-top:20px">${layout.limitations.map(esc).join('<br>')}</div>${sheetBtn('house_2',7)}${sheetBtn('house_2',8)}${sheetBtn('house_2',9)}`);
 $('rebar-parameters').onsubmit=e=>{e.preventDefault();const form=e.currentTarget;if(!form.reportValidity())return;const values=new FormData(form);s.parameters={...s.parameters,phase_x_mm:+values.get('phase_x_mm'),phase_y_mm:+values.get('phase_y_mm'),axis_inset_mm:+values.get('axis_inset_mm'),edge_scope:values.get('edge_scope')};s.layout=RebarLayout.build(MODEL.foundation,DATA.facts,s.parameters);applyFoundationMeshCuts(s.layout);s.selected=null;$('source-dialog').close();activateTab('model');buildScene('rebar');};
}
document.addEventListener('click',e=>{
 if(e.target.closest('[data-rebar-layout]'))openRebarLayout();
 if(e.target.closest('[data-rebar-element-details]'))openRebarLayout(true);
 if(e.target.closest('[data-mesh-seat-study]'))openMeshSeatStudy();
 if(e.target.closest('[data-fm1-splice-study]'))openFoundationSpliceStudy();
 if(e.target.closest('[data-edge-link-study]'))openEdgeLinkStudy();
 if(e.target.closest('[data-beam-starter-study]'))openBeamStarterStudy();
 if(e.target.closest('[data-beam-pin-study]'))openBeamPinStudy();
 if(e.target.closest('[data-beam-longitudinal-study]'))openBeamLongitudinalStudy();
 const longView=e.target.closest('[data-longitudinal-view]');
 if(longView)showBeamLongitudinalView(longView.dataset.longitudinalView);
 if(e.target.closest('[data-edge-mesh-study]'))openEdgeMeshStudy();
 const edgeMesh=e.target.closest('[data-edge-mesh-zone]');
 if(edgeMesh)showEdgeMeshZone(edgeMesh.dataset.edgeMeshZone,edgeMesh.dataset.edgeMeshMode);
 const pin=e.target.closest('[data-beam-pin-case]');
 if(pin)showBeamPinCase(pin.dataset.beamPinCase,+pin.dataset.pinPos);
 const pinCorner=e.target.closest('[data-beam-pin-corner]');
 if(pinCorner)showBeamPinCorner(pinCorner.dataset.beamPinCorner);
 const starter=e.target.closest('[data-beam-starter-case]');
 if(starter)showBeamStarterCase(starter.dataset.beamStarterCase);
 const corner=e.target.closest('[data-edge-link-corner]');
 if(corner)showEdgeLinkDetail(+corner.dataset.edgeLinkCorner);
 if(e.target.closest('[data-edge-link-beam]'))showEdgeLinkDetail(null);
 const trial=e.target.closest('[data-mesh-seat-case]');
 if(trial)showMeshSeatCase(trial.dataset.meshSeatCase);
 const splice=e.target.closest('[data-fm1-splice-view]');
 if(splice)showFoundationSplices(+splice.dataset.fm1SpliceView,1,splice.dataset.fm1SpliceSite);
});

'use strict';
let serviceDetailRenderer=null,serviceDetailState=null;
const SERVICE_GROUPS={slab:{label:'Плита',color:[.65,.71,.61]},base:{label:'Подготовка / щебень',color:[.63,.63,.53]},sleeve:{label:'Стальная гильза',color:[.37,.46,.48]},pipe:{label:'Труба · наружная поверхность',color:[.64,.37,.22]},seal:{label:'Место герметизации',color:[.27,.55,.62]}};
function disposeServiceDetailViewer(){serviceDetailRenderer?.dispose();serviceDetailRenderer=null;serviceDetailState=null;}
function serviceDetailButtons(){return `<div class="card"><div class="eyebrow">ЛОКАЛЬНЫЕ РАЗРЕЗЫ</div><h3>Посмотреть проход изнутри</h3><p>Полые гильзы, плита и основание. Известные размеры отделены от условных длин фрагментов.</p><div class="buttons-row">${MODEL.service_details.map(d=>`<button data-service-detail="${d.id}">${esc(d.title)} ↗</button>`).join('')}</div></div>`;}
function openServiceDetail(id){
 return prepareDialog(['renderer','facts','service-details'],()=>renderServiceDetail(id));
}
function renderServiceDetail(id){
 const d=MODEL.service_details.find(d=>d.id===id);if(!d)return;
 const groups=id==='electric'?['sleeve']:Object.keys(SERVICE_GROUPS);
 showDialog(d.sheet+' / ЛОКАЛЬНЫЙ УЗЕЛ',d.title,`<div class="callout"><b>${d.issue_ids.join(' / ')} · известные размеры и открытые вопросы</b>${d.notes.map(esc).join('<br>')}</div>
 <div class="roof-detail-controls" style="margin:18px 0"><label>Элемент<select id="service-detail-part"><option value="all">Весь узел</option>${groups.map(k=>`<option value="${k}">${SERVICE_GROUPS[k].label}</option>`).join('')}</select></label><label class="control"><input id="service-detail-isolate" type="checkbox"> Только выбранный элемент</label><label class="control"><input id="service-detail-section" type="checkbox" checked> Открыть половину сечения</label>${d.variants?`<label>Диаметр воды · I008<select id="service-detail-variant">${d.variants.map(v=>`<option value="${v.id}">${esc(v.label)}</option>`).join('')}</select></label>`:''}</div>
 <div class="viewport roof-detail-viewport"><canvas id="service-detail-canvas" tabindex="0" aria-label="3D-узел прохода через плиту"></canvas><div class="viewport-top"><span class="status amber">Верх плиты = 0 · локальная схема</span></div><div class="view-tools"><button id="service-detail-iso">3D</button><button id="service-detail-front">Сечение</button><button id="service-detail-top">Сверху</button><button id="service-detail-reset">↺</button></div><div class="scene-help">ЛКМ — вращение · Shift — сдвиг · колесо — масштаб</div></div>
 <div class="roof-detail-layers">${groups.map(k=>`<label>${SERVICE_GROUPS[k].label}<input data-service-opacity="${k}" type="range" min="0" max="100" value="${k==='slab'?35:k==='base'?20:k==='seal'?65:100}"></label>`).join('')}</div><div id="service-detail-inspector" class="card"></div>
 <div class="buttons-row"><span id="service-detail-stat" class="tiny muted"></span>${sheetBtn(d.source_id,d.pdf_page,'Открыть '+d.sheet)}</div>
 <details style="margin:20px 0"><summary>Условные длины и локальная система</summary><p>${esc(d.local_origin)} Все числа ниже — параметры просмотра. Длина гильзы и трубы для закупки не определена.</p><div class="hash">${Object.entries(d.conditional_parameters).map(([k,v])=>esc(({fragment_half_width_mm:'Половина ширины фрагмента, мм',sleeve_below_plate_mm:'Условное продолжение гильзы под плитой, мм',pipe_top_mm:'Верх фрагмента трубы, мм',pipe_below_sleeve_mm:'Продолжение трубы под гильзой, мм',pipe_sample_run_mm:'Проекция демонстрационного выпуска, мм',bend_radius_mm:'Демонстрационный радиус, мм',seal_display_depth_mm:'Глубина цветного указателя уплотнения, мм',circular_display_sides:'Стороны аппроксимации окружности',display_length_mm:'Длина видимого отрезка, мм'})[k])+': '+v).join('<br>')}</div></details>
 <h3>Источник рядом с моделью</h3><img src="${DATA.crops['service-'+id]}" alt="Исходный узел прохода">${fragmentButton('service-'+id)}`);
 serviceDetailState={detail:d,part:'all',variant:d.variants?.[0].id||null,opacities:{slab:.35,base:.2,sleeve:1,pipe:1,seal:.65}};
 try{serviceDetailRenderer=new HouseGL($('service-detail-canvas'),id=>{if(id.startsWith('service-part:')){$('service-detail-part').value=id.slice(13);serviceDetailState.part=id.slice(13);drawServiceDetail();}},s=>{if(s.error&&$('service-detail-stat'))$('service-detail-stat').textContent=s.error;});resetServiceDetail();drawServiceDetail();}catch(e){$('service-detail-inspector').textContent=e.message;}
 $('service-detail-part').onchange=e=>{serviceDetailState.part=e.target.value;drawServiceDetail();};$('service-detail-isolate').onchange=drawServiceDetail;$('service-detail-section').onchange=drawServiceDetail;
 if($('service-detail-variant'))$('service-detail-variant').onchange=e=>{serviceDetailState.variant=e.target.value;drawServiceDetail();};
 document.querySelectorAll('[data-service-opacity]').forEach(e=>e.oninput=()=>{const k=e.dataset.serviceOpacity;serviceDetailState.opacities[k]=+e.value/100;const l=serviceDetailRenderer.layers.get(k);if(l)l.opacity=+e.value/100;serviceDetailRenderer.request();});
 $('service-detail-iso').onclick=()=>{serviceDetailRenderer.yaw=-.55;serviceDetailRenderer.pitch=1.05;serviceDetailRenderer.request();};$('service-detail-front').onclick=()=>{serviceDetailRenderer.yaw=0;serviceDetailRenderer.pitch=Math.PI/2;serviceDetailRenderer.request();};$('service-detail-top').onclick=()=>{serviceDetailRenderer.yaw=0;serviceDetailRenderer.pitch=.00001;serviceDetailRenderer.request();};$('service-detail-reset').onclick=resetServiceDetail;
}
function resetServiceDetail(){const r=serviceDetailRenderer;if(!r)return;r.yaw=-.55;r.pitch=1.05;r.pan=[0,0];r.target=serviceDetailState.detail.id==='electric'?[0,0,0]:[200,0,-450];r.span=serviceDetailState.detail.id==='electric'?650:2000;r.request();}
function drawServiceDetail(){
 const g=serviceDetailRenderer,s=serviceDetailState;if(!g||!s)return;const d=s.detail,p=d.conditional_parameters,section=$('service-detail-section').checked;g.clear();
 const layers={};for(const [id,m]of Object.entries(SERVICE_GROUPS)){if($('service-detail-isolate').checked&&s.part!=='all'&&s.part!==id)continue;layers[id]=g.addLayer(id,s.part===id?[.84,.55,.20]:m.color,{opacity:s.opacities[id],order:id==='slab'?4:id==='base'?5:2});}
 const id=k=>'service-part:'+k,allowed=a=>!section||Math.sin(a)>=-1e-8;
 // Annulus with open, selectable inner wall: no solid cylinder masquerading as a sleeve.
 const shell=(key,r0,r1,z0,z1)=>{
  const l=layers[key];if(!l)return;
  const at=(r,t,z)=>[r*Math.cos(t),r*Math.sin(t),z];
  for(let i=0;i<(section?16:32);i++){
   const a=i*Math.PI/16,b=(i+1)*Math.PI/16;
   g.face(l,[at(r1,a,z0),at(r1,b,z0),at(r1,b,z1),at(r1,a,z1)],null,id(key));
   if(r0!==null){
    g.face(l,[at(r0,b,z0),at(r0,a,z0),at(r0,a,z1),at(r0,b,z1)],null,id(key));
    for(const z of [z0,z1])g.face(l,[at(r0,a,z),at(r0,b,z),at(r1,b,z),at(r1,a,z)],null,id(key));
   }
   for(const z of [z0,z1])g.line(l,at(r1,a,z),at(r1,b,z));
   if(i%4===0)g.line(l,at(r1,a,z0),at(r1,a,z1));
  }
  if(section&&r0!==null)for(const t of [0,Math.PI])g.face(l,[at(r0,t,z0),at(r1,t,z0),at(r1,t,z1),at(r0,t,z1)],null,id(key));
 };
 if(d.id==='electric'){shell('sleeve',null,d.sleeve_outer_diameter_mm/2,-200,200);}
 else{
  const outer=d.sleeve_outer_diameter_mm/2,inner=d.sleeve_inner_diameter.value_mm/2,variant=d.variants?.find(v=>v.id===s.variant),pipe=(variant?.pipe_diameter_mm||d.pipe_diameter_mm)/2;
  // A square source-thickness fragment with a circular opening; radial sectors cover it without filling the sleeve.
  const plate=(key,z0,z1)=>{const l=layers[key];if(!l)return;for(let i=0;i<32;i++){const a=i*Math.PI/16,b=(i+1)*Math.PI/16;if(!allowed((a+b)/2))continue;const at=(t,r,z)=>[r*Math.cos(t),r*Math.sin(t),z],far=t=>p.fragment_half_width_mm/Math.max(Math.abs(Math.cos(t)),Math.abs(Math.sin(t)));for(const z of [z0,z1])g.face(l,[at(a,outer,z),at(a,far(a),z),at(b,far(b),z),at(b,outer,z)],null,id(key));g.face(l,[at(a,far(a),z0),at(b,far(b),z0),at(b,far(b),z1),at(a,far(a),z1)],null,id(key));g.face(l,[at(b,outer,z0),at(a,outer,z0),at(a,outer,z1),at(b,outer,z1)],null,id(key));if(section&&(i===0||i===15)){const t=i===0?a:b;g.face(l,[at(t,outer,z0),at(t,far(t),z0),at(t,far(t),z1),at(t,outer,z1)],null,id(key));}g.line(l,at(a,far(a),z0),at(b,far(b),z0));g.line(l,at(a,far(a),z1),at(b,far(b),z1));}};
  plate('slab',-d.slab_thickness_mm,0);let z=-d.slab_thickness_mm;for(const h of [d.blinding_thickness_mm,...d.gravel_thicknesses_mm]){plate('base',z-h,z);z-=h;}
  const bottom=-d.slab_thickness_mm-p.sleeve_below_plate_mm;shell('sleeve',inner,outer,bottom,d.sleeve_above_plate_mm);shell('seal',pipe,inner,d.sleeve_above_plate_mm-p.seal_display_depth_mm,d.sleeve_above_plate_mm);
  if(layers.pipe){
   const z0=bottom-p.pipe_below_sleeve_mm,run=p.pipe_sample_run_mm,bend=p.bend_radius_mm;
   shell('pipe',null,pipe,z0,p.pipe_top_mm);
   const slope=d.id==='sewer'?d.outlet_slope:0;
   const ring=(x,z,angle)=>Array.from({length:33},(_,j)=>{
    const t=j*Math.PI/16,radial=pipe*Math.cos(t);
    return [x+radial*Math.cos(angle),pipe*Math.sin(t),z+radial*Math.sin(angle)];
   });
   let previous=ring(0,z0,0);
   const join=next=>{
    for(let j=0;j<(section?16:32);j++)g.face(layers.pipe,[previous[j],previous[j+1],next[j+1],next[j]],null,id('pipe'));
    previous=next;
   };
   for(let i=1;i<=16;i++){
    const angle=i*Math.PI/32;
    join(ring(bend*(1-Math.cos(angle)),z0-bend*Math.sin(angle),angle));
    if(d.id==='sewer'&&i===8)g.polyline(layers.pipe,previous.slice(0,section?17:33));
   }
   join(ring(bend+run,z0-bend-run*slope,Math.PI/2-Math.atan(slope)));
  }
 }
 g.commit();g.request();
 const keys=s.part==='all'?d.input_fact_ids:d.input_fact_ids.filter(i=>s.part==='sleeve'?/sleeve_/.test(i):s.part==='pipe'?/pipe_|elbow|slope/.test(i):s.part==='seal'?/seal_/.test(i):s.part==='slab'?/slab_thickness/.test(i):/blinding|gravel/.test(i));
 $('service-detail-inspector').innerHTML=`<div class="eyebrow">${s.part==='all'?'УЗЕЛ ЦЕЛИКОМ':'ВЫБРАННЫЙ ЭЛЕМЕНТ'}</div><h3>${s.part==='all'?esc(d.title):SERVICE_GROUPS[s.part].label}</h3><p>Гильза: Ø${d.sleeve_outer_diameter_mm}${d.sleeve_wall_mm?'×'+d.sleeve_wall_mm:' · стенка неизвестна'} мм.${d.sleeve_inner_diameter?` Внутренний диаметр = ${d.sleeve_outer_diameter_mm} − 2 × ${d.sleeve_wall_mm} = ${d.sleeve_inner_diameter.value_mm} мм (derived).`:''}</p><p class="check-bad">Длина гильзы и абсолютная отметка трубы не заданы. Видимые отрезки — условные параметры; закупочного количества труб здесь нет.</p>${d.id==='sewer'?'<p>Две части дуги по 45°, радиус условный. Прямой выпуск показан с i=0,02; сопряжение его оси с коленом условное. Раструбы не восстановлены.</p>':''}${d.id==='water'?'<p class="check-bad">I008 · выбор Ø63 / 65 / Ø32 меняет только сценарий просмотра, а не проектную базу.</p>':''}${keys.map(i=>factBtn(i,FACTS.get(i)?.label+' · '+FACTS.get(i)?.value+' '+unit(FACTS.get(i)?.unit))).join('<br>')}`;
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-service-detail]');if(b)openServiceDetail(b.dataset.serviceDetail);});

function drawServiceSlabClashes(g){
 const key='serviceSlabClashes',color=[.93,.32,.15];
 const layer=g.resetLayer(key,color,{visible:g.layers.get(key)?.visible??false,order:27,showEdges:false});
 LAYER_META[key]=['Трубы в теле Пм 1',color];
 g.serviceSlabClashes=serviceSlabCrossings(g.servicePaths,MODEL.slab2);
 for(const row of g.serviceSlabClashes){
  if(!row.variants.some(v=>v.slab_variant===activeSlab().id&&v.contact_m2>1e-9))continue;
  const [x,y]=row.xy_mm,id='service-clash:'+row.route_id,r=row.diameter_mm/2;
  g.tube(layer,[x,y,row.bottom_mm],[x,y,row.top_mm],r,24,id);
  g.ring(layer,x,y,row.top_mm+8,Math.max(r+25,85),40,id);
  expInfo(g,id,{title:row.label+' · пересечение Пм 1',note:'Труба пересекает бетон в текущей разводке. На КЖ-7 в этом месте нет отверстия.',
   facts:['level.slab.Pm1_top.elevation','level.slab.Pm1_bottom.elevation'],sheets:[['house_2',12]],status:'user_design_scenario'});
 }
}

