  const live=!requested&&mode==='services3d'&&renderer?.servicePaths?.length;
  const placement=requested==='selected'||requested==='coordinated'||(!requested&&experience.sewerPlacement==='coordinated')?'coordinated':'source';
  const id=live?waterPlacementId():chosen?'coordinated-E':requested&&requested!=='coordinated'?requested:(experience.waterCorner?'corner-E':'source');
