function slabProfilePoints(points,bottom,top){
 const out=[];
 const add=p=>{if(!out.length||Math.hypot(...p.map((v,i)=>v-out.at(-1)[i]))>.001)out.push(p);};
 for(const [i,a] of points.slice(0,-1).entries()){
  const b=points[i+1],dz=b[2]-a[2];
  if(Math.max(a[2],b[2])<bottom||Math.min(a[2],b[2])>top)continue;
  const limits=dz===0?[0,1]:[(bottom-a[2])/dz,(top-a[2])/dz].sort((u,v)=>u-v);
  for(const t of [Math.max(0,limits[0]),Math.min(1,limits[1])])add(a.map((x,k)=>x+(b[k]-x)*t));
 }
 return out;
}
function showConnectedSlabProfile(selected){
 const study=MODEL.experience.service_takeoff;
 const s=study.connected_slab_offsets;
 const candidate=selected==='toilet'?s.offsets.find(r=>r.status==='space_required'):s.offsets[+selected];
 if(!candidate)return;
 const row=study.coordinated_scenarios[0].slab_crossings.find(r=>r.route_id===candidate.route_id);
 if(selected==='toilet'){
  const moved=s.moved_fixture;
  if(moved)focusServiceSlabSteel(row,activeSlab().id,{points_mm:moved.paths.find(p=>p.id===row.route_id).points_mm,
   footprint_mm:moved.footprint_mm,toilet:true});
 }else if(candidate.status==='connected')focusServiceSlabSteel(row,activeSlab().id,candidate);
}
function focusServiceSlabSteel(row,variantId,profile){
 $('source-dialog').close();
 stairState.slabVariant=variantId;
 return activateTab(constructionViewer?'slab':'model','stairs',()=>{
  const g=renderer,slab=MODEL.slab2,variant=activeSlab(),[x,y]=row.xy_mm,radius=row.diameter_mm/2;
  const z0=row.bottom_mm,z1=row.top_mm,half=Math.max(150,radius+110);
  const lo=[x-half,y-half],hi=[x+half,y+half];
  const trial=row.shift_trial;
  experience.savedVisibility=new Map([...g.layers.values()].map(layer=>[layer.id,layer.visible]));
  for(const layer of g.layers.values())layer.visible=false;
  const concrete=addLayer(g,'serviceSteelSlab',{opacity:.16,showEdges:false});
  const pipe=addLayer(g,'serviceSteelPipe',{opacity:.72,showEdges:false});
  const regular=addLayer(g,'serviceSteelBars',{showEdges:false});
  const hits=addLayer(g,'serviceSteelHits',{showEdges:false});
  const layers=[concrete,pipe,regular,hits];
  const shifted=trial?addLayer(g,'serviceSteelShift',{opacity:profile ? .86 : .4,showEdges:false}):null;
  if(shifted)layers.push(shifted);
  for(const layer of layers)experience.savedVisibility.set(layer.id,false);
  for(const tile of variant.disjoint_rectangles_mm){
   const [a,b,c,d]=tile.map(Number),u=Math.max(a,lo[0]),v=Math.max(b,lo[1]),U=Math.min(c,hi[0]),V=Math.min(d,hi[1]);
   if(u<U&&v<V)g.box(concrete,u,v,z0,U,V,z1,null,false);
  }
  const id='service-steel:'+row.route_id;
  const cylinder=(layer,[u,v],key)=>g.tube(layer,[u,v,z0-35],[u,v,z1+35],radius,32,key);
  cylinder(pipe,row.xy_mm,id);
  if(shifted){
   if(profile){
    const upper=profile.toilet?z1+120:z1+160;
    const points=profile.upper_connection_mm?[...profile.points_mm,profile.upper_connection_mm.at(-1)]:profile.points_mm;
    drawPipeRun(g,shifted,slabProfilePoints(points,z0-160,upper),radius,null,false);
    const outline=profile.footprint_mm?.map(p=>[...p,z1+100])??[];
    for(const [i,p] of outline.entries())g.tube(shifted,p,outline[(i+1)%outline.length],3,8);
   }else cylinder(shifted,trial.xy_mm,null);
  }
  const review=row.variants.find(v=>v.slab_variant===variant.id).steel;
  const colliding=new Set(Object.values(review.groups).flatMap(group=>group.hits));
  for(const bar of serviceSlabSteel(slab,variant)){
   if(serviceSteelGap(row,bar)>110)continue;
   const layer=colliding.has(bar.id)?hits:regular;
   for(const {axis,a,b} of bar.segments){
    const across=axis==='x'?1:0;
    if(a[across]<lo[across]||a[across]>hi[across]||
      axis==='z'&&(a[1]<lo[1]||a[1]>hi[1]))continue;
    const from=[...a],to=[...b];
    if(axis!=='z'){
     const along=1-across;
     from[along]=Math.max(from[along],lo[along]);to[along]=Math.min(to[along],hi[along]);
     if(from[along]>=to[along])continue;
    }
    g.tube(layer,from,to,bar.diameter_mm/2,12);
   }
  }
  const gap=Math.min(...Object.values(review.groups).map(group=>group.minimum_mm??Infinity));
  const note=colliding.size?`${profile?'Исходная труба. ':''}Пересечения со сталью: ${fmt(colliding.size)}. Красным показаны затронутые детали. `
                          :`Ближайшая сталь находится в ${fmt(gap,2)} мм от трубы. `;
  expInfo(g,id,{title:row.label+' · Пм 1',facts:['slab.Пм1.section.thickness','slab.Пм1.rebar.1.diameter'],
   sheets:[['house_2',12],['house_2',13],['house_1',7]],
   note:note+(trial?`Зелёная ось X = ${fmt(trial.xy_mm[0])}, Y = ${fmt(trial.xy_mm[1])} мм. Зазор до проверенной стали ${fmt(trial.min_steel_gap_mm,2)} мм. `:'')+
    (profile?.toilet?'Контур прибора смещён на 50 мм. ':profile?'Переход соединён с трассой по обе стороны плиты. ':'')+
    'Рабочие гильзы, фасонные части и монтажные размеры открыты.'});
  for(const layer of layers)g.commitLayer(layer);
  indexSceneObjects(g);
  g.target=[x+(profile?.toilet?160:0),y,(z0+z1)/2];g.span=Math.max(profile?.toilet?980:profile?650:460,half*2.4)*g.fitAspect();
  g.yaw=-.53;g.pitch=.85;g.pan=[0,0];
  selectSceneObject(id);
  g.layers.get('selection').visible=false;
  renderLayerControls();g.request();
 });
}

