function drawStairInterior(g,s,hole){
 const landing=s.landing.bounds_mm.map(Number),upper=s.flights.find(f=>f.id==='upper');
 const walls=addLayer(g,'stairPartitions',{showEdges:false,explodeOrder:1});
 const rear=MODEL.floor2.walls.find(w=>w.id==='upper-stair-west').bounds_mm.map(Number);
 // AR-9: the stairwell wall stands on the intermediate landing above the boiler room.
 const closure=[...rear.slice(0,2),landing[5],...rear.slice(2),Number(MODEL.slab2.top_mm)];
 g.box(walls,...closure,'stair:landing-wall',false);
 g.stairBarriers=[closure];
 // Close the return at the inner string of the upper flight above room 9.
 // The under-flight wall reaches the soffit across the strip between it and the flight.
 const wc=MODEL.floor1.walls.find(w=>w.id==='wc2-frame').bounds_mm.map(Number);
 const yInner=Number(upper.y_bounds_mm[0]),soffit=stairWallEnvelopes()[1].plane;
 const eastWall=MODEL.floor1.walls.find(w=>w.id==='bearing3').bounds_mm.map(Number);
 const foot=[[wc[0],wc[3]],[eastWall[0],wc[3]],[eastWall[0],yInner],[wc[0],yInner]];
 HouseShapes.prism(g,walls,{polygon_mm:foot,bottom_plane:[0,0,0],top_plane:soffit},'stair:wc-return');
 g.stairWcReturn={foot,top:soffit};
 // The passage to room 9 crosses axis E below the upper flight. Close the
 // space above its clear height, from the flight's soffit to the slab.
 const [minX,,,maxX]=MODEL.floor1.openings.find(o=>o.id==='o-wc2-access').bounds_mm.map(Number);
 const [,minY,,maxY]=MODEL.floor1.walls.find(w=>w.id==='bearingЕ').bounds_mm.map(Number);
 const apron={polygon_mm:[[minX,minY],[maxX,minY],[maxX,maxY],[minX,maxY]],
  bottom_plane:soffit,top_plane:[0,0,Number(MODEL.slab2.bottom_mm)]};
 const bearingLayer=['house','floor1'].includes(mode)?g.layers.get('walls1'):walls;
 HouseShapes.prism(g,bearingLayer,apron,'stair:wc-apron');
 g.stairWcApron=apron;
 drawStairGuards(g);
}
function activeStairGuards(){
 return MODEL.stairs.guard_layout.variants.find(row=>row.stair_variant===stairState.stairVariant&&row.slab_variant===stairState.slabVariant);
}
function drawStairGuards(g){
 const metal=addLayer(g,'stairGuards',{showEdges:false}),wood=addLayer(g,'stairHandrail',{showEdges:false});
 const style=MODEL.stairs.finish_rules.appearance;
 metal.color=style.posts_rgb;wood.color=style.rails_rgb;
 const rules=MODEL.stairs.guard_layout.display_parameters,height=rules.rail_axis_height_mm,half=rules.post_width_mm/2;
 g.guardRuns=[];
 for(const run of activeStairGuards().runs){
  const offset=run.level==='tread'?stairFinishMm():0;
  const rise=([x,y,z],zOffset)=>[x,y,z+zOffset];
  const id='stair-guard:'+run.id;
  g.tube(wood,rise(run.a_mm,offset+height),rise(run.b_mm,offset+height),rules.rail_diameter_mm/2,12,id);
  for(const [x,y,bottom,top] of run.posts_mm)
   g.box(metal,x-half,y-half,bottom+offset,x+half,y+half,top+offset+height,id,false);
  for(const [a,b] of run.brackets_mm)
   g.tube(metal,rise(a,offset+height),rise(b,offset+height),rules.bracket_diameter_mm/2,8,id);
  if(run.posts_mm.length)
   g.guardRuns.push({a:rise(run.a_mm,offset),b:rise(run.b_mm,offset),height_mm:height});
 }
}
function drawIntermediateSlab(g,l){
 const m=MODEL.slab2,v=activeSlab(),z0=+m.bottom_mm,z1=+m.top_mm;
 for(const r of v.disjoint_rectangles_mm){const [x0,y0,x1,y1]=r.map(Number);g.face(l,[[x0,y0,z0],[x0,y1,z0],[x1,y1,z0],[x1,y0,z0]],[0,0,-1],'slab2');g.face(l,[[x0,y0,z1],[x1,y0,z1],[x1,y1,z1],[x0,y1,z1]],[0,0,1],'slab2');}
 for(const edge of v.boundary_edges_mm){const [a,b]=edge.map(p=>p.map(Number));g.face(l,[[...a,z0],[...b,z0],[...b,z1],[...a,z1]],null,'slab2');for(const z of [z0,z1])g.line(l,[...a,z],[...b,z]);}
}
function drawSlabMesh(g){
 const chair=activeChairView(),trial=activeSpliceTrial();
 const marks=trial&&addLayer(g,'slabSpliceMarks',{visible:stairState.showMesh,opacity:.68,order:14,explodeOrder:2});
 for(const mat of activeSlab().field_mesh){
  const id=slabMeshLayers[mat.position-1];
  const layer=addLayer(g,id,{visible:stairState.showMesh,order:12,explodeOrder:2});
  for(const [index,{axis,axis_z_mm,segments_mm}] of mat.directions.entries()){
   const z=+axis_z_mm+Number(chair?.z_shift_by_mesh_mm[mat.position-1]??0);
   const point=axis==='x'?(station,end)=>[+end,station,z]:(station,end)=>[station,+end,z];
   const draw=(pieces,key)=>{
    for(const [station,start,end] of pieces)g.tube(layer,point(station,start),point(station,end),mat.diameter_mm/2,8,key);
   };
   if(trial){
    const route=trial.directions[index];
    for(const r of route.rows){
     draw(r.pieces,r.id);
     for(const [i,[a,b]] of r.laps.entries()){
      const lo=Math.min(r.pieces[i][0],r.pieces[i+1][0])-2,hi=Math.max(r.pieces[i][0],r.pieces[i+1][0])+2;
      const corners=[[lo,a],[hi,a],[hi,b],[lo,b]].map(([u,v])=>[...point(u,v).slice(0,2),z+8]);
      if(axis==='x')corners.reverse();
      g.face(marks,corners,[0,0,1],r.id);
     }
    }
    for(const r of route.unplaced)draw([[r.station_mm,...r.source_span_mm]],id);
   }else{
    draw(segments_mm,id);
   }
  }
 }
 drawSlabOpeningTrim(g);
 drawSlabHoops(g);
 if(chair)drawSlabChairs(g,chair);
}
