const chairSeatViews={issued:'Высота 90 мм · пересечение',fitted:'Высота 78 мм · три касания',
 obstacle:'ВК-1 · до смещения',shift:'ВК-1 · после смещения'};
function openChairSeat(initialLimit=6000,initialMode='existing'){
 return prepareDialog(['facts','structure'],()=>{
  const slab=MODEL.slab2,r=slab.chair_coordination_rules;
  showDialog('КЖ-7 / КЖ-8 · I020','Посадка фиксаторов Пм 1',`
   <p>Для сеток с 30 мм до наружной поверхности стержня между двумя ножками и мостиком требуется ${fmt(r.derived_height_mm)} мм по осям. КЖ-8 указывает ${fmt(r.issued_height_mm)} мм. Проверены две нижние опоры и касание верхней сетки с учётом обрамления, прямых участков хомутов и вертикальных труб.</p>
   <div class="row-controls">
    <label>Привязка проёма <select id="chair-seat-variant">${slab.variants.map(v=>`<option value="${esc(v.id)}">${esc(v.label)}</option>`).join('')}</select></label>
    <label>Предел заготовки <select id="chair-seat-limit">${slab.splice_rules.piece_length_limits_mm.map(n=>`<option value="${n}">${fmt(n/1000)} м</option>`).join('')}</select></label>
    <label>Разводка <select id="chair-seat-mode">${Object.entries(slab.splice_coordination_rules.service_modes).map(([key,label])=>`<option value="${key}">${esc(label)}</option>`).join('')}</select></label>
   </div>
   <div id="chair-seat-summary"></div>
   <p>По осевой схеме 78 мм на деталь приходится ${fmt(r.derived_axis_length_mm)} мм без учёта гибов. Расчётная масса пропорциональна осевой длине. Форма гибов, монтажное положение и закупочное количество остаются открытыми.</p>
   <div class="dialog-links">${sheetBtn('house_2',12,'КЖ-7 · установка')}${sheetBtn('house_2',13,'КЖ-8 · эскиз и ведомость')}</div>`);
  const variant=$('chair-seat-variant'),limit=$('chair-seat-limit'),mode=$('chair-seat-mode'),summary=$('chair-seat-summary');
  variant.value=activeSlab().id;limit.value=String(initialLimit);mode.value=initialMode;
  function render(){
   const v=slab.variants.find(v=>v.id===variant.value),t=v.chair_coordination[mode.value].find(t=>t.limit_mm===+limit.value);
   const heights=[['Высота по КЖ-8',t.issued],['Высота по посадке',t.fitted],['С местным смещением',t.fitted.shifted_quantities]];
   summary.innerHTML=`<div class="table-wrap"><table><thead><tr><th>Примерка</th><th>Сели из ${fmt(v.chair_fit.count)} мест</th><th>Длина осей, м</th><th>Масса, кг</th></tr></thead><tbody>
    ${heights.map(([label,h])=>`<tr><th>${label}</th><td>${fmt(h.count)}</td><td>${fmt(h.axis_length_m,3)}</td><td>${fmt(h.equivalent_mass_kg,3)}</td></tr>`).join('')}
   </tbody></table></div>
   ${t.fitted.shifts.length?`<div class="table-wrap"><table><thead><tr><th>Исходный центр X / Y, мм</th><th>Новый X, мм</th><th>До прежней помехи, мм</th></tr></thead><tbody>
    ${t.fitted.shifts.map(s=>`<tr><td>${s.original_centre_mm.map(n=>fmt(n)).join(' / ')}</td><td>${fmt(s.centre_mm[0])}</td><td>${s.gap_to_original_obstacles_mm===null?'—':fmt(s.gap_to_original_obstacles_mm,3)}</td></tr>`).join('')}
   </tbody></table></div>`:''}
   <div class="buttons-row">${Object.entries(chairSeatViews).filter(([key])=>['issued','fitted'].includes(key)||t.fitted.examples[key])
    .map(([key,label])=>`<button data-chair-seat-view="${key}">${label}</button>`).join('')}</div>`;
   for(const button of summary.querySelectorAll('[data-chair-seat-view]'))
    button.onclick=()=>focusChairSeat(v.id,t,mode.value,button.dataset.chairSeatView);
  }
  variant.onchange=limit.onchange=mode.onchange=render;
  render();
 });
}

function focusChairSeat(slabId,trial,mode,view){
 const chair=view==='issued'?trial.issued.examples.section:trial.fitted.examples[view==='fitted'?'section':view];
 $('source-dialog').close();
 stairState.slabVariant=slabId;
 return activateTab(constructionViewer?'slab':'model','stairs',()=>{
  const g=renderer,slab=MODEL.slab2,[x,y]=chair.centre_mm,z=+slab.bottom_mm;
  const reach=310,clip=[x-reach,y-reach,x+reach,y+reach];
  experience.savedVisibility=new Map([...g.layers.values()].map(l=>[l.id,l.visible]));
  for(const layer of g.layers.values())layer.visible=false;
  const layers=Object.fromEntries(['Concrete','Lower','Upper','Obstacle','Chair'].map(kind=>{
   const layer=addLayer(g,'slabChairSeat'+kind,{showEdges:false});
   experience.savedVisibility.set(layer.id,false);
   return [kind,layer];
  }));
  for(const b of activeSlab().disjoint_rectangles_mm){
   const [x0,y0,x1,y1]=b.map((value,i)=>i<2?Math.max(value,clip[i]):Math.min(value,clip[i]));
   if(x0<x1&&y0<y1)g.box(layers.Concrete,x0,y0,z,x1,y1,z+12,null,false);
  }
  const id='chair-seat:'+view;
  const clamp=p=>p.map((n,i)=>i<2?Math.max(clip[i],Math.min(n,clip[i+2])):n);
  for(const [,kind,mat,,radius,a,b] of chair.steel){
   const start=clamp(a),end=clamp(b);
   if(start.some((n,i)=>n!==end[i]))g.tube(kind==='field'?(mat===1?layers.Lower:layers.Upper):layers.Obstacle,start,end,radius,14,id);
  }
  for(let i=1;i<chair.wire_mm.length;i++)g.tube(layers.Chair,chair.wire_mm[i-1],chair.wire_mm[i],+slab.chair_rules.diameter_mm/2,14,id);
  expInfo(g,id,{title:chairSeatViews[view],facts:slab.chair_coordination_rules.input_fact_ids,sheets:[['house_2',12],['house_2',13]]});
  for(const layer of Object.values(layers))g.commitLayer(layer);
  indexSceneObjects(g);
  g.target=[x,y,z+85];g.span=760*g.fitAspect();g.yaw=-.58;g.pitch=.63;g.pan=[0,0];g.labels=[];
  $('scene-title').textContent='Пм 1 · фиксатор позиции 3';
  $('scene-status').textContent=chairSeatViews[view];
  $('scene-notice').innerHTML=`Фиксатор зелёный, нижняя сетка серая, верхняя синяя. Помеха обрамления показана красным.
   <button data-chair-seat="${trial.limit_mm}" data-chair-seat-mode="${esc(mode)}">К таблице посадки</button>`;
  renderLayerControls();g.request();
 });
}
function drawSlabOpeningTrim(g){
 const trim=activeSlab().opening_trim,rules=MODEL.slab2.opening_trim_rules;
 const layers=slabTrimLayers.map(id=>addLayer(g,id,{visible:stairState.showOpeningTrim&&!stairState.openingPlanHole,order:14,explodeOrder:2}));
 for(const row of trim.axes){
  const t=Number(row.station_mm);
  const point=(along,z)=>row.axis==='x'?[+along,t,+z]:[t,+along,+z];
  for(const interval of row.intervals){
   const layer=layers[['covered','reduced_cover','outside'].indexOf(interval.status)];
   for(const z of row.z_mm){
    g.tube(layer,point(interval.start_mm,z),point(interval.end_mm,z),+rules.diameter_mm/2,8,row.id);
   }
  }
 }
 const [x,y,X,Y]=trim.between_openings.bounds_mm.map(Number),z=+MODEL.slab2.top_mm+4;
 const mark=[[x,y,z],[X,y,z],[X,Y,z],[x,Y,z]],layer=layers.at(-1);
 g.face(layer,mark,[0,0,1],layer.id);
 g.polyline(layer,mark,true);
 g.labels.push({text:`Между проёмами · ${fmt(trim.between_openings.width_mm)} мм`,p:[(x+X)/2, (y+Y)/2, z+65],
  id:layer.id,layer:layer.id,color:'#8b3c24'});
 const plan=addLayer(g,'slabTrimPlan',{visible:stairState.showOpeningTrim&&Boolean(stairState.openingPlanHole),order:15,explodeOrder:2});
 for(const {hole_id,plan_group} of trim.sides){
  if(hole_id!==stairState.openingPlanHole||!plan_group.edge_segment_mm)continue;
  const [[a,b],[c,d]]=plan_group.edge_segment_mm.map(p=>p.map(Number));
  const halfWidth=27;
  const dx=a===c?halfWidth:0,dy=b===d?halfWidth:0,top=z+10;
  const corners=[[a-dx,b-dy,top],[c-dx,d-dy,top],[c+dx,d+dy,top],[a+dx,b+dy,top]];
  if(dx)corners.reverse();
  g.face(plan,corners,[0,0,1],plan.id);
 }
}
function focusSlabOpeningTrim(hole,showPlan=false){
 $('dialog-close').click();
 stairState.showOpeningTrim=true;
 stairState.openingPlanHole=showPlan?hole:'';
 stairState.showLandingJoint=false;
 stairState.chairView='';
 stairState.spliceLimit=0;
 buildScene('stairs',()=>{
  const slab=activeSlab(),between=slab.opening_trim.between_openings;
  const target=hole==='between'?between:[slab.opening,...slab.holes].find(k=>k.id===hole);
  const [x,y,X,Y]=target.bounds_mm.map(Number);
  renderer.target=[(x+X)/2,(y+Y)/2,+MODEL.slab2.top_mm];
  renderer.span=(hole==='between'?2200:Math.max(X-x,Y-y)+1800)*renderer.fitAspect();
  renderer.yaw=0;
  renderer.pitch=.12;
  renderer.request();
  inspect(showPlan?'slabTrimPlan':'slabTrimGap');
 });
}
