function drawStairReinforcement(g){
 const variant=activeStair(),starter=variant.starter,steel=MODEL.stairs.reinforcement;
 const layout=(mode==='house'||stairState.starterOffset)&&starter.offset_trial||starter;
 const [foot,bars,hits,foundationSteel,cage,field,sketchLayer,transverse]=stairStarterLayers.map(id=>addLayer(g,id,{
  visible:stairState.showStarter,order:id==='stairStarterFoot'?9:14,explodeOrder:1,opacity:id==='stairStarterFoot'?.24:1
 }));
 const [low,top]=steel.foundation_z_mm.map(Number);
 for(const row of starter.contact_rectangles_mm){
  const [x,y,X,Y]=row.map(Number);
  g.box(foot,x,y,low,X,Y,top,foot.id);
 }
 const [z0,z1]=steel.axis_z_mm.map(Number);
 for(const anchor of layout.anchors){
  const [x,y]=anchor.axis_xy_mm.map(Number),layer=anchor.conflicts.length?hits:bars;
  g.tube(layer,[x,y,z0],[x,y,z1],+steel.diameter_mm/2,12,anchor.id);
 }
 for(const rod of layout.foundation_context_rods){
  for(const [a,b] of rod.segments_mm)
   g.tube(foundationSteel,a,b,rod.diameter_mm/2,12,foundationSteel.id);
 }
 for(const [layer,rods] of [[cage,layout.cage_bars],[field,variant.field_bars],[transverse,variant.transverse_fit.bars]]){
  for(const rod of rods)g.tube(layer,rod.a_mm,rod.b_mm,rod.diameter_mm/2,12,rod.id);
 }
 const footCase=variant.foot_detail.cases[layout===starter?'drawing':MODEL.stairs.foot_detail_rules.selected_case];
 for(const {id,points_mm} of footCase.paths){
  for(let i=1;i<points_mm.length;i++)g.tube(field,points_mm[i-1],points_mm[i],variant.foot_detail.radius_mm,16,id);
 }
 for(const sketch of variant.step_bar_sketches){
  const [bottom,corner,end]=sketch.points_mm,r=sketch.diameter_mm/2;
  g.tube(sketchLayer,bottom,corner,r,8,sketch.id);
  g.tube(sketchLayer,corner,end,r,8,sketch.id);
 }
}
function drawStairHeadJoint(g){
 const joint=activeStairCoordination().upper_joint;
 const [end,north,guide]=stairHeadLayers.map(id=>addLayer(g,id,{
  visible:stairState.showHeadJoint,order:16,explodeOrder:1,opacity:id==='stairHeadGuide'?1:.78
 }));
 for(const [contact,layer,axis] of [[joint.end_contact,end,1],[joint.north_contact,north,0]]){
  for(const face of contact.polygons_mm){
   for(const t of HouseGL.triangulate(face.map(p=>[p[axis],p[2]])))
    g.face(layer,t.map(i=>face[i]),null,layer.id);
   g.polyline(layer,face,true);
  }
 }
 const [y0,y1]=joint.flight_y_mm;
 const x=joint.flight_end_x_mm,X=joint.opening_edge_x_mm,y=(y0+y1)/2;
 const z=(joint.slab_z_mm[0]+joint.last_tread_top_mm)/2;
 if(joint.end_gap_mm){
  g.line(guide,[x,y,z],[X,y,z]);
  for(const t of [x,X])g.line(guide,[t,y,z-14],[t,y,z+14]);
  g.labels.push({text:`Зазор ${fmt(joint.end_gap_mm)} мм`,p:[(x+X)/2,y,z+24],id:guide.id,layer:guide.id,color:'#965825'});
 }
 for(const row of joint.field_axis_projection){
  const [u,v,w]=row.point_mm;
  g.line(guide,[u-16,v,w],[u+16,v,w]);
  g.line(guide,[u,v,w-16],[u,v,w+16]);
 }
 const layers=stairHeadSteelLayers.map(id=>addLayer(g,id,{visible:showStairHeadSteel,order:18,explodeOrder:1}));
 const study=activeStairBeltClearance();
 const pairs=study.intersections.length?study.intersections:[study.nearest];
 const spans=layers.map(()=>new Map());
 for(const pair of pairs){
  for(const [i,key] of ['stair','belt'].entries()){
   const rod=pair[key],p=pair.nearest_axis_points_mm[i],a=rod.a_mm,b=rod.b_mm;
   const d=b.map((value,j)=>value-a[j]),length=Math.hypot(...d);
   const direction=d.map(value=>value/length),t=direction.reduce((sum,value,j)=>sum+value*(p[j]-a[j]),0);
   const segmentId=[rod.id,...a,...b].join(':');
   const span=spans[i].get(segmentId)??{rod,a,direction,length,lo:t,hi:t};
   span.lo=Math.min(t,span.lo);
   span.hi=Math.max(t,span.hi);
   spans[i].set(segmentId,span);
  }
 }
 for(const [i,layer] of layers.entries())for(const {rod,a,direction,length,lo,hi} of spans[i].values()){
  const point=along=>a.map((value,j)=>value+direction[j]*along);
  g.tube(layer,point(Math.max(0,lo-85)),point(Math.min(length,hi+85)),rod.diameter_mm/2,12,layer.id);
 }
}
function drawStairLandingJoint(g,joint){
 const [contact,conflict]=stairLandingLayers.map(id=>addLayer(g,id,{visible:stairState.showLandingJoint,opacity:.84,order:15,explodeOrder:1}));
 for(const end of joint.flight_ends){
  const face=end.contact_face_mm.map(p=>p.map(Number));
  if(face.length)g.face(contact,face,[1,0,0],contact.id);
 }
 for(const support of joint.supports){
  for(const patch of [support.foundation_contact,support.landing_contact]){
   const z=Number(patch.z_mm);
   for(const rect of patch.rectangles_mm){
    const [x,y,X,Y]=rect.map(Number);
    const face=[[x,y,z],[X,y,z],[X,Y,z],[x,Y,z]];
    g.face(contact,face,[0,0,1],contact.id);
    g.polyline(contact,face,true);
   }
  }
  if(support.shared_aac_envelope_mm)g.box(conflict,...support.shared_aac_envelope_mm.map(Number),conflict.id);
 }
}
function drawFlightBody(g,l,f,p){
 const [y0,y1]=f.y_bounds_mm.map(Number);
 for(const t of HouseGL.triangulate(p)){
  g.face(l,t.map(i=>[p[i][0],y0,p[i][1]]),[0,-1,0],l.id);
  g.face(l,[...t].reverse().map(i=>[p[i][0],y1,p[i][1]]),[0,1,0],l.id);
 }
 for(let i=0;i<p.length;i++){
  const a=p[i],b=p[(i+1)%p.length],step=i%2===0&&i<2*f.tread_count?i/2+1:null;
  g.face(l,[[a[0],y0,a[1]],[b[0],y0,b[1]],[b[0],y1,b[1]],[a[0],y1,a[1]]],null,step?'stair:'+f.id+':'+step:l.id);
  for(const y of [y0,y1])g.line(l,[a[0],y,a[1]],[b[0],y,b[1]]);
  if(step)g.line(l,[a[0],y0,a[1]],[a[0],y1,a[1]]);
 }
}
function drawMitredStairFinish(g,layer,joint,backX,depth,id,topJoint){
 const x=Number(joint.x_mm),z=Number(joint.concrete_top_mm),top=z+depth;
 const [y,Y]=joint.y_bounds_mm.map(Number),heel=x+joint.direction_x*depth;
 // Extend the selected contact direction through the finish envelope for section views.
 // The envelope includes the adhesive; the ceramic product thickness is still open.
 g.face(layer,[[x,y,top],[x,Y,top],[heel,Y,z],[heel,y,z]],null,id);
 for(const [side,norm] of [[y,-1],[Y,1]]){
  const nose=[x,side,top],inner=[heel,side,z];
  if(topJoint){
   g.face(layer,[nose,[x,side,z],inner],[0,norm,0],id);
   g.face(layer,[nose,inner,[backX,side,z],[backX,side,top]],[0,norm,0],id);
  }
  g.line(layer,nose,inner,id);
 }
 if(topJoint){
  const mid=Number(topJoint.y_mm);
  for(const [a,b] of [[y,mid],[mid,Y]])g.face(layer,[[x,a,top],[backX,a,top],[backX,b,top],[x,b,top]],[0,0,1],id);
  g.line(layer,[x,mid,top],[backX,mid,top],id);
 }
 if(topJoint)g.face(layer,[[backX,y,z],[backX,Y,z],[backX,Y,top],[backX,y,top]],[joint.direction_x,0,0],id);
 g.line(layer,[x,y,top],[x,Y,top],id);
}
function drawStaircase(g,visible){
 const s=activeStair(),slab=activeSlab();
 const joints=new Map(s.horizontal_finish.mitred_joints.map(joint=>[joint.id,joint]));
 const treadJoints=new Map(s.horizontal_finish.tread_layout.joints.map(joint=>[joint.id,joint]));
 const layers={lower:g.addLayer('stairsLower',[.60,.66,.56],{visible,finishOverlay:'stairFinish',explodeOrder:1,order:11}),upper:g.addLayer('stairsUpper',[.66,.71,.61],{visible,finishOverlay:'stairFinish',explodeOrder:1,order:11}),landing:g.addLayer('stairLanding',[.68,.70,.57],{visible,finishOverlay:'stairFinish',explodeOrder:1,order:11}),brick:g.addLayer('stairBrick',[.65,.44,.29],{visible,opacity:.25,explodeOrder:1,order:12}),finish:g.addLayer('stairFinish',MODEL.stairs.finish_rules.appearance.tile_rgb,{visible:visible&&(mode!=='stairs'||stairState.showFinish),depthPriority:1,alignEdgesToFaces:true,stoneGrain:true,edgeAlpha:.32,explodeOrder:1,order:12}),checks:g.addLayer('stairChecks',[.75,.43,.17],{visible:mode==='stairs',order:13,explodeOrder:1})};
 for(const f of s.flights){
  drawFlightBody(g,layers[f.id],f,f.profile_xz_mm);
  if(stairFinishMm()>0){
   const ascent=Number(f.geometry_rule.direction_x), [y,Y]=f.y_bounds_mm.map(Number);
   let level=f.id==='lower'?n('level.floor_1.elevation')*1000:Number(s.landing.bounds_mm[5])+stairFinishMm();
   const riserJoints=s.horizontal_finish.riser_layout.joints.filter(j=>j.flight===f.id);
   function front(x,top,id,index){
    const mid=Number(riserJoints[index].y_mm);
    for(const [a,b] of [[y,mid],[mid,Y]])g.face(layers.finish,[[x,a,level],[x,b,level],[x,b,top],[x,a,top]],[-ascent,0,0],id);
    g.line(layers.finish,[x,mid,level],[x,mid,top],id);
    level=top;
   }
   for(const step of f.steps){
    const [x,,z,X]=step.bounds_mm.map(Number),top=z+stairFinishMm(),id='stair:'+f.id+':'+step.step_index;
    front(ascent>0?x:X,top,id,step.step_index-1);
    drawMitredStairFinish(g,layers.finish,joints.get(step.id),ascent>0?X:x,stairFinishMm(),id,treadJoints.get(step.id));
   }
   if(f.id==='lower'){
    const landing=joints.get('landing');
    front(+landing.x_mm,+landing.concrete_top_mm+stairFinishMm(),layers.finish.id,f.steps.length);
   }else{
    const transition=s.horizontal_finish.upper_hall_transition;
    const x=Number(transition.edge_x_mm),z=Number(transition.elevation_mm);
    front(x,z,layers.finish.id,f.steps.length);
   }
  }
 }
 const r=s.landing.bounds_mm.map(Number),polygon=s.landing.polygon_mm.map(p=>p.map(Number));
 g.prism(layers.landing,polygon,r[2],r[5],'stairLanding');
 if(stairFinishMm()>0){
  const layout=s.horizontal_finish.landing_layout,joint=joints.get('landing'),depth=stairFinishMm(),top=r[5]+depth;
  const outline=layout.outline_mm.map(p=>p.map(Number));
  // The lower-flight nosing keeps its 45° contact. The five top pieces follow the full landing outline.
  drawMitredStairFinish(g,layers.finish,joint,Math.min(...outline.map(p=>p[0])),depth,'stairLanding');
  for(const piece of layout.pieces){
   const ring=piece.polygon_mm.map(p=>p.map(Number));
   for(const t of HouseGL.triangulate(ring))g.face(layers.finish,t.map(i=>[...ring[i],top]),[0,0,1],'stairLanding');
  }
  for(const j of layout.joints){
   const [a,b]=j.x_bounds_mm.map(Number),y=Number(j.y_mm);
   g.line(layers.finish,[a,y,top],[b,y,top],'stairLanding');
  }
  // Close exposed sides of the landing finish. The nosing against the lower riser already has a face.
  const [lowerSouth,lowerNorth]=joint.y_bounds_mm.map(Number);
  for(let i=0;i<outline.length;i++){
   const a=outline[i],b=outline[(i+1)%outline.length];
   if(a[0]===b[0]&&a[0]===+joint.x_mm&&b[1]>a[1]&&a[1]<=lowerSouth&&b[1]>=lowerNorth){
    if(b[1]===lowerNorth)continue;
    const start=[a[0],lowerNorth];
    g.face(layers.finish,[[...start,r[5]],[...b,r[5]],[...b,top],[...start,top]],null,'stairLanding');
   }else g.face(layers.finish,[[...a,r[5]],[...b,r[5]],[...b,top],[...a,top]],null,'stairLanding');
  }
 }
 for(const p of s.brick_piers)g.box(layers.brick,...p.bounds_mm.map(Number),'stairBrick');
 const x3=+MODEL.axis_view_variant.x['3'],y0=r[1],y1=r[4];
 for(const chain of ['lower','upper']){const x=x3+n('stairs.Лм1.plan.'+chain+'_end_right_of_3');g.line(layers.checks,[x,y0,0],[x,y1,0]);}
 const hole=slab.opening.bounds_mm.map(Number);g.polyline(layers.checks,[[hole[0],hole[1],3205],[hole[2],hole[1],3205],[hole[2],hole[3],3205],[hole[0],hole[3],3205]],true);
 if(['house','stairs','floor2','floor1'].includes(mode))drawStairInterior(g,s,hole);
 for(const r of activeStairCoordination().landing_under_slab_patches_mm){const [x0,y0,x1,y1]=r.map(Number);g.face(layers.checks,[[x0,y0,1632],[x1,y0,1632],[x1,y1,1632],[x0,y1,1632]],[0,0,1],'stairChecks');}
 if(mode==='house'||mode==='stairs')drawStairReinforcement(g);
 if(mode==='stairs'){
  drawStairHeadJoint(g);
  drawStairLandingJoint(g,s.landing_joint);
  g.labels.push({text:'Площадка +1.630 · КЖ-15',p:[r[0]+150,r[4]+150,1630],id:'stairLanding',layer:'stairLanding',color:'#916b36'});
  g.labels.push({text:'Проём 3820×2420 · I019',p:[hole[2]+50,hole[3],3350],id:'slab2',layer:'slab2',color:'#916b36'});
 }
}
function applyStairDetailVisibility(){
 for(const id of slabTrimLayers)renderer.layers.get(id).visible=stairState.showOpeningTrim&&!stairState.openingPlanHole;
 renderer.layers.get('slabTrimPlan').visible=stairState.showOpeningTrim&&Boolean(stairState.openingPlanHole);
 for(const id of slabHoopLayers)renderer.layers.get(id).visible=stairState.showHoops;
 for(const id of stairStarterLayers)renderer.layers.get(id).visible=stairState.showStarter;
 for(const id of stairHeadLayers)renderer.layers.get(id).visible=stairState.showHeadJoint;
 for(const id of stairHeadSteelLayers)renderer.layers.get(id).visible=showStairHeadSteel;
 for(const id of stairLandingLayers)renderer.layers.get(id).visible=stairState.showLandingJoint;
 for(const id of stairLandingContext){
  const layer=renderer.layers.get(id);
  if(!layer)continue;
  if(stairState.showLandingJoint&&!stairState.showHeadJoint){
   layer.visibleBeforeLanding??=layer.visible;
   layer.visible=false;
  }else if(layer.visibleBeforeLanding!==undefined){
   layer.visible=layer.visibleBeforeLanding;
   delete layer.visibleBeforeLanding;
  }
 }
 renderer.layers.get('stairsLower').opacity=(stairState.showStarter||stairState.showLandingJoint)?.26:1;
 renderer.layers.get('stairsUpper').opacity=(stairState.showStarter||stairState.showHeadJoint||stairState.showLandingJoint||showStairHeadSteel)?.26:1;
 renderer.layers.get('stairLanding').opacity=stairState.showLandingJoint?.26:1;
 if(showStairHeadSteel)for(const layer of renderer.layers.values())
  layer.visible=layer.id==='stairsUpper'||stairHeadSteelLayers.includes(layer.id);
}
