function focusStairEndDetails(layout){
 const t=activeStairCoordination().upper_joint.end_detail_trial,r=MODEL.stairs.end_detail_rules;
 $('source-dialog').close();
 return activateTab(constructionViewer?'slab':'model','stairs',()=>{
  const g=renderer;
  experience.savedVisibility=new Map([...g.layers.values()].map(l=>[l.id,l.visible]));
  for(const l of g.layers.values())l.visible=['stairsUpper','slab2'].includes(l.id);
  for(const id of ['stairsUpper','slab2'])g.layers.get(id).opacity=.18;
  const layers=['stairEndCongested','stairEndShort','stairEndTransverse','stairHeadRouteContext']
   .map(id=>addLayer(g,id,{showEdges:false}));
  const rod=t.position5[layout][Math.floor(t.position5[layout].length/2)],id='stair-end-detail';
  const [x,y,z]=t.preview_centre_mm;
  for(const row of t.preview){
   const a=row.a_mm,delta=row.b_mm.map((n,i)=>n-a[i]);
   const lo=[x-240,y-100,z-230],hi=[x+350,y+100,z+165];
   let start=0,end=1;
   for(let i=0;i<3;i++){
    if(!delta[i]){if(a[i]<lo[i]||a[i]>hi[i])end=0;continue;}
    const p=(lo[i]-a[i])/delta[i],q=(hi[i]-a[i])/delta[i];
    start=Math.max(start,Math.min(p,q));end=Math.min(end,Math.max(p,q));
   }
   if(start<end){
    const point=t=>a.map((n,i)=>n+delta[i]*t);
    g.tube(layers[3],point(start),point(end),row.radius_mm,12,id);
   }
  }
  for(let i=1;i<rod.points_mm.length;i++)g.tube(layers[layout==='literal'?0:1],rod.points_mm[i-1],rod.points_mm[i],r.position5.radius,16,id);
  if(layout==='short')for(const bar of t.position6.middle.bars){
   const [[x,a,z],[,b]]=bar.points_mm;
   g.tube(layers[2],[x,Math.max(y-105,a),z],[x,Math.min(y+105,b),z],r.position6.radius,16,id);
  }
  expInfo(g,id,{title:'Арматура последней ступени Лм 1',facts:r.input_fact_ids,sheets:[['house_2',20]]});
  for(const layer of layers)g.commitLayer(layer);
  indexSceneObjects(g);
  g.target=[x+25,y,z];g.span=770*g.fitAspect();g.yaw=-.62;g.pitch=.62;g.pan=[0,0];g.labels=[];
  $('scene-title').textContent='Арматура последней ступени Лм 1';
  $('scene-status').textContent=layout==='literal'?'Плечо 440 мм':'Плечо 254 мм и две поперечины';
  $('scene-notice').innerHTML='<button data-stair-end-details data-head-projection-return>К таблице деталей</button>';
  renderLayerControls();g.request();
 });
}
function focusStairHeadProjection(fitted=false){
 const joint=activeStairCoordination().upper_joint,projection=joint.branch_projection,route=joint.route_trial;
 const pair=projection.crossings[Math.floor(projection.crossings.length/2)];
 $('source-dialog').close();
 return activateTab(constructionViewer?'slab':'model','stairs',()=>{
  const g=renderer;
  experience.savedVisibility=new Map([...g.layers.values()].map(l=>[l.id,l.visible]));
  for(const l of g.layers.values())l.visible=['stairsUpper','slab2','belt1Concrete'].includes(l.id);
  for(const id of ['stairsUpper','slab2','belt1Concrete'])g.layers.get(id).opacity=.24;
  const layers=['stairHeadProjectionIn','stairHeadProjectionOut','stairHeadProjectionCross',
   'stairHeadRoute','stairHeadRouteContext'].map(id=>addLayer(g,id,{showEdges:false}));
  const id='stair-head-projection';
  for(const branch of projection.branches.filter(b=>pair.ids.includes(b.id)&&(!fitted||b.layer==='top')))
   for(const p of branch.pieces)g.tube(layers[p.in_concrete?0:1],p.a_mm,p.b_mm,branch.diameter_mm/2,16,id);
  const [x,y,z]=pair.point_mm;
  if(fitted){
   const branch=route.paths.find(b=>b.id===pair.ids[1]).points_mm;
   for(let i=1;i<branch.length;i++)g.tube(layers[3],branch[i-1],branch[i],6,16,id);
   const lo=[branch[0][0]-25,y-85,2770],hi=[branch.at(-1)[0]+30,y+85,3200];
   for(const bar of route.preview){
    if(bar.kind==='upper')continue;
    const a=bar.a_mm,delta=bar.b_mm.map((n,i)=>n-a[i]);
    let start=0,end=1;
    for(let i=0;i<3;i++){
     if(delta[i]===0){if(a[i]<lo[i]||a[i]>hi[i])end=0;continue;}
     const p=(lo[i]-a[i])/delta[i],q=(hi[i]-a[i])/delta[i];
     start=Math.max(start,Math.min(p,q));end=Math.min(end,Math.max(p,q));
    }
    if(start<end){
     const point=t=>a.map((n,i)=>n+delta[i]*t);
     g.tube(layers[4],point(start),point(end),bar.radius_mm,12,id);
    }
   }
  }else g.tube(layers[2],[x,y-15,z],[x,y+15,z],10,16,id);
  for(const layer of layers)g.commitLayer(layer);
  expInfo(g,id,{title:'Продолжение осей Лм 1',facts:MODEL.stairs.head_projection_rules.input_fact_ids,sheets:[['house_2',20]]});
  indexSceneObjects(g);
  g.target=[x-35,y,3040];g.span=1100*g.fitAspect();g.yaw=-.12;g.pitch=.29;g.pan=[0,0];g.labels=[];
  $('scene-title').textContent='Лм 1 · переход осей по виду Б';
  $('scene-status').textContent=fitted?'Ломаная ось нижнего ряда':'Две оси одного поперечного створа';
  $('scene-notice').innerHTML=(fitted?'Зелёным показана ломаная ось, синим — верхний ряд.':'Красным показана часть оси вне бетона. Оранжевый маркер отмечает пересечение.')+
   ' <button data-stair-head data-head-projection-return>К таблице примыкания</button>';
  renderLayerControls();g.request();
 });
}
function focusStairRebar(layer='stairStarterBars',offset=true){
 $('dialog-close').click();
 stairState.showStarter=true;
 stairState.starterOffset=offset;
 buildScene('stairs',()=>{
  const st=activeStair();
  renderer.yaw=-.87;
  renderer.pitch=.61;
  if(layer==='stairFieldSteel'){
   const points=st.field_bars.flatMap(r=>[r.a_mm,r.b_mm]);
   const ranges=[0,1,2].map(i=>[Math.min(...points.map(p=>p[i])),Math.max(...points.map(p=>p[i]))]);
   renderer.target=ranges.map(([lo,hi])=>(lo+hi)/2);
   renderer.span=1.6*Math.max(...ranges.map(([lo,hi])=>hi-lo))*renderer.fitAspect();
  }else if(layer==='stairTransverseSteel'){
   const row=st.transverse_fit.bars.find(r=>r.flight_id==='lower'&&r.step===4&&r.layer==='top');
   renderer.target=row.a_mm.map((v,i)=>(v+row.b_mm[i])/2);
   renderer.span=1340*renderer.fitAspect();
   renderer.pitch=.94;
  }else{
   const [x,y,X,Y]=st.starter.footprint_mm.map(Number);
   renderer.target=[(x+X)/2,(y+Y)/2,-255];
   renderer.span=1560*renderer.fitAspect();
  }
  renderer.request();
  inspect(layer);
 });
}
