function focusRoofBedTakeoff(id){
 $('source-dialog').close();
 Object.assign(roofFrameState,{family:'all',coverHidden:true,selected:null,isolate:null});
 return activateTab(constructionViewer?'roof':'model','frame',()=>{
  const g=renderer,data=MODEL.roof_frame.bed_takeoff,slab=activeSlab().id;
  for(const layer of g.layers.values())layer.visible=['frame-beds','slab2'].includes(layer.id);
  g.layers.get('frame-beds').opacity=.28;
  g.layers.get('slab2').opacity=.20;
  function overlay(id,label,color){
   LAYER_META[id]=[label,color];
   return g.addLayer(id,color,{visible:true,order:23,showEdges:false});
  }
  const film=overlay('frame-bed-film','Гидроизоляция под лежнями',[.16,.57,.52]);
  const axes=overlay('frame-bed-anchors','Пробные оси анкеров',[.25,.34,.65]);
  const covered=overlay('frame-bed-covered','Оси под перегородками',[.84,.28,.10]);
  const rows=id==='all'?data.rows:data.rows.filter(row=>row.member_id===id);
  for(const row of rows){
   for(const rect of row.contact_rects_mm[slab]){
    g.face(film,roofContactRect(rect).map(([x,y])=>[x,y,data.slab_top_mm+.05]),[0,0,1],'roof:beds');
   }
   for(const axis of row.anchors){
    const [x,y]=axis.xyz_mm;
    g.tube(axis.partition_ids.length?covered:axes,[x,y,data.slab_top_mm],axis.xyz_mm,data.anchor_diameter_mm/2,8,'roof:beds');
   }
  }
  for(const layer of [film,axes,covered])g.commitLayer(layer);
  const points=rows.flatMap(row=>row.footprint_mm);
  const centre=[0,1].map(i=>(Math.min(...points.map(p=>p[i]))+Math.max(...points.map(p=>p[i])))/2);
  focusFramePoint([...centre,data.slab_top_mm],id==='all'?13000:2600,{yaw:-.35,pitch:.85});
  renderLayerControls();
 });
}
