/* The entrance study replaces a local volume of the active facing geometry. */
'use strict';

function portalBox(id,family,b){
 return roofContactPrism(id,family,roofContactRect([b[0],b[1],b[3],b[4]]),[0,0,b[2]],[0,0,b[5]]);
}

function portalVolumesOverlap(a,b){
 return [0,1,2].every(i=>Math.min(a.bounds[i+3],b.bounds[i+3])-Math.max(a.bounds[i],b.bounds[i])>.01);
}

function portalMinus(a,b){
 if(!portalVolumesOverlap(a,b))return [a];
 const outside=[];
 let common=a.faces;
 for(const {plane} of b.sides){
  const exposed=clipDisplaySolid(common,plane.map(v=>-v));
  if(exposed.length)outside.push(roofContactSolid(a.id,a.family,exposed));
  common=clipDisplaySolid(common,plane);
  if(!common.length)break;
 }
 return outside;
}

function portalCandidate(portal,closed,original){
 const [from,front,base,to,back,top]=portal.replacement_bounds_mm;
 const [left,right]=portal.clear_x_mm;
 const seat=portal.bearing_z_mm,bed=seat-portal.bed_thickness_mm;
 const box=(id,family,b)=>portalBox('entry-portal:'+id,family,b);
 const legs=[['west',from,left],['east',right,to]].flatMap(([side,a,b])=>[
  box(side,'brick',[a,front,base,b,back,bed]),box('bed-'+side,'bed',[a,front,bed,b,back,seat]),
 ]);
 const profile=(strips)=>facingAnglePrisms(0,closed.profile,strips);
 const body=(id,family,p)=>roofContactPrism('entry-portal:'+id,family,p.polygon_mm,p.bottom_plane,p.top_plane);
 const head=profile([[front,portal.spring_mm-seat,back,0]]).map(p=>body('head','brick',{...p,top_plane:[0,0,top]}));
 const steel=Object.entries(closed.pieces).flatMap(([id,p])=>profile([p.rect_mm]).map(q=>body(id,'steel',q)));
 const z=portal.spring_mm-seat,[low,high]=portal.xps_offsets_mm,[insFront,insBack]=portal.xps_y_mm;
 const originalXps=original.filter(p=>p.family==='xps');
 const insulation=profile([[insFront,z+low,insBack,z+high]])
  .map(p=>body('xps','xps',p)).flatMap(p=>originalXps.reduce((pieces,cut)=>pieces.flatMap(q=>portalMinus(q,cut)),[p]));
 const replace=box('cut','brick',portal.replacement_bounds_mm);
 const substituted=original.flatMap(p=>p.family==='brick'?portalMinus(p,replace):[p]);
 const voids=[box('cheek-recess','brick',portal.cheek_recess_mm),...insulation];
 const retained=substituted.flatMap(p=>p.family==='brick'
  ?voids.reduce((pieces,cut)=>pieces.flatMap(q=>portalMinus(q,cut)),[p]):[p]);

 const mid=portal.centre_x_mm,crown=portal.centre_z_mm+portal.radius_mm;
 const [w0,w1,h,d]=['bottom_width','top_width','profile_height','profile_depth'].map(k=>n('decor.Д-2.'+k));
 const key=[[mid-w0/2,crown],[mid+w0/2,crown],[mid+w1/2,crown+h],[mid-w1/2,crown+h]];
 const run={axis:0};
 const decor=(id,p,depth)=>roofContactSolid('entry-portal:'+id,'decor',facadeExtrusion(run,p,front,front-depth));
 const moulding=decorStrips('Д-4').flatMap(([u,v,depth])=>
  archDecorStrip(left,right,portal.spring_mm,crown-portal.spring_mm,u,v)
   .flatMap(p=>HouseShapes.subtract(facadeProfile(p),key)).map(p=>decor('arch-trim',p,depth)));
 return {substituted,retained,added:[...legs,...head,...steel,...insulation,...moulding,decor('key',key,d)]};
}

function entrancePortalReview(portal,assembly,original,concrete,plinth,upper){
 const {added,retained}=assembly;
 const touching=(a,b)=>a.reduce((area,p)=>area+b.reduce((sum,q)=>sum+(measureRoofContact(p,q)?.area_mm2??0),0),0);
 const named=id=>added.filter(p=>p.id==='entry-portal:'+id);
 const volume=parts=>parts.reduce((s,p)=>s+roofConvexVolume(p.faces,p.centre),0)/1e9;
 const brick=added.filter(p=>p.family==='brick'),beds=added.filter(p=>p.family==='bed');
 const overlaps=[];
 let checked_pairs=0;
 for(const [i,a] of added.entries())for(const b of [...retained,...concrete,...plinth,...added.slice(i+1)]){
  if(!portalVolumesOverlap(a,b))continue;
  checked_pairs++;
  const hit=measureRoofContact(a,b);
  if(hit?.volume_mm3>0)overlaps.push({ids:[a.id,b.id],volume_m3:hit.volume_mm3/1e9});
 }
 const aperture=portalBox('entry-portal:passage','clear',portal.clear_passage_mm);
 const passage_blockers=[...added,...concrete,...retained].filter(p=>portalVolumesOverlap(p,aperture)&&measureRoofContact(p,aperture)?.volume_mm3>0).map(p=>p.id);
 const material=family=>added.filter(p=>p.family===family);
 const totalBrick=parts=>volume(parts.filter(p=>p.family==='brick'));
 const seat=named('shelf');
 const support=['west','east'].map(side=>({side,shelf_on_bed_mm2:touching(seat,named('bed-'+side)),
  bed_on_brick_mm2:touching(named('bed-'+side),named(side)),brick_on_plinth_mm2:touching(named(side),plinth)}));
 const brick_removed_m3=totalBrick(original)-totalBrick(retained);
 const upper_before_mm2=touching(original.filter(p=>p.family==='brick'),upper);
 const upper_after_mm2=touching([...retained.filter(p=>p.family==='brick'),...brick],upper);
 const clashes_before_recess_m3=Object.fromEntries(['steel','xps'].map(family=>[family,material(family).reduce((sum,p)=>
  sum+assembly.substituted.filter(q=>q.family==='brick'&&portalVolumesOverlap(p,q)).reduce((subtotal,q)=>
   subtotal+(measureRoofContact(p,q)?.volume_mm3??0)/1e9,0),0)]));
 return {support,checked_pairs,body_count:added.length,overlaps,passage_blockers,
  head_on_shelf_mm2:touching(named('head'),seat),toe_clear_height_mm:portal.bearing_z_mm-portal.clear_passage_mm[2],
  upper_before_mm2,upper_after_mm2,upper_contact_gain_mm2:upper_after_mm2-upper_before_mm2,clashes_before_recess_m3,
  cheek_brick_removed_m3:totalBrick(assembly.substituted)-totalBrick(retained),brick_removed_m3,brick_gross_added_m3:volume(brick),
  brick_delta_m3:volume(brick)-brick_removed_m3,bed_m3:volume(beds),xps_delta_m3:volume(material('xps')),
  steel_m3:volume(material('steel')),decor_backing_mm2:{arch:touching(named('arch-trim'),named('head')),key:touching(named('key'),named('head'))},
  decor_arch_m3:volume(named('arch-trim')),decor_key_m3:volume(named('key'))};
}

