function drawPortalPreview(g,view){
 const p=MODEL.experience.entrance_portal,closed=MODEL.experience.facing_angles.closed_entrance;
 const xps=n('wall.external.xps_thickness');
 const old=[['brick',[]],['xps',[0,xps]]].flatMap(([family,depths])=>[1,2].flatMap(floor=>
  facadeSections(floor,g.openings,...depths).flatMap(({id,run,z0,z1,holes,roofCut})=>
   facadeBandBodies(run,z0,z1,holes,roofCut).map((faces,i)=>roofContactSolid(id+':'+i,family,faces)))));
 const {retained,added}=portalCandidate(p,closed,old);
 const cut=view==='section';
 const layerIds={brick:'entryPortalBrick',steel:'entryPortalSteel',bed:'entryPortalBed',xps:'entryPortalXps',decor:'entryPortalDecor'};
 const context=addLayer(g,'entryPortalContext',{visible:false,showEdges:false});
 const layers={};
 for(const [family,id] of Object.entries(layerIds))layers[family]=addLayer(g,id,{visible:false,showEdges:false,
  opacity:cut&&family==='brick' ? .14 : 1});
 if(!cut)for(const q of retained.filter(q=>q.family==='brick'))for(const f of q.faces)g.face(context,f);
 for(const q of added)for(const f of q.faces)g.face(layers[q.family],f,null,q.id);
 for(const layer of [context,...Object.values(layers)])g.commitLayer(layer);
 const names={head:'Кладка над аркой',west:'Западный простенок',east:'Восточный простенок',
  'bed-west':'Западная постель','bed-east':'Восточная постель',shelf:'Полка L125 × 8',web:'Стенка L125 × 8',
  rear:'Замыкающая стенка',cap:'Верхняя полоса',heel:'Нижняя полоса',xps:'Местный XPS','arch-trim':'Д-4 · арочный профиль',key:'Д-2 · замковая накладка'};
 for(const [id,title] of Object.entries(names))expInfo(g,'entry-portal:'+id,{title,status:'entry_portal_trial',
  facts:[...p.input_fact_ids,...(p.decor_fact_ids[id]??[])],sheets:[['house_1',13],['house_1',19],['house_2',16],['house_2',18]],
  note:'Примерка наружной плоскости входа в общей модели.'});
 const visible=[layerIds.brick,layerIds.steel];
 if(!cut)return [...visible,context.id,layerIds.decor];
 const concrete=addLayer(g,'entryPortalConcrete',{visible:false,showEdges:false,opacity:.28});
 const plinth=addLayer(g,'entryPortalPlinth',{visible:false,showEdges:false});
 for(const part of MODEL.floor1.entrance_arch.parts.filter(q=>q.material==='concrete'))
  HouseShapes.prism(g,concrete,part,'entry-portal:concrete');
 const [x0,y0,,x1,y1]=p.replacement_bounds_mm;
 const ground=MODEL.foundation.plinth;
 for(const r of ground.disjoint_rectangles_mm){
  const [a,b,c,d]=r.map(Number),left=Math.max(a,x0),front=Math.max(b,y0),right=Math.min(c,x1),back=Math.min(d,y1+100);
  if(left<right&&front<back)g.box(plinth,left,front,+ground.z_bottom_mm,right,back,+ground.z_top_mm,'entry-portal:plinth',false);
 }
 g.commitLayer(concrete);g.commitLayer(plinth);
 expInfo(g,'entry-portal:concrete',{title:'Бетонная арка ПР-4',facts:['lintel.ПР-4.bottom_clear_width'],sheets:[['house_2',18]]});
 expInfo(g,'entry-portal:plinth',{title:'Ростверк Фм 1 под простенками',sheets:[['house_2',7]]});
 return [...visible,concrete.id,plinth.id,layerIds.bed,layerIds.xps];
}

function focusEntrancePortal(view){
 $('source-dialog').close();
 return activateTab('model','house',()=>{
  const g=renderer,p=MODEL.experience.entrance_portal;
  const layers=drawPortalPreview(g,view),section=view==='section';
  const context=section?[]:['openingFrames1','openingLeaves1','glass1'];
  experience.savedVisibility=new Map([...g.layers.values()].map(layer=>[layer.id,layer.visible]));
  for(const layer of g.layers.values())layer.visible=layers.includes(layer.id)||context.includes(layer.id);
  indexSceneObjects(g);
  g.target=section?[p.centre_x_mm,p.origin_face_mm,p.spring_mm-230]:[p.centre_x_mm,p.origin_face_mm,1550];
  g.span=(section?3650:4550)*g.fitAspect();
  g.yaw=section ? .49 : .12;g.pitch=section ? 1.27 : 1.5;g.pan=[0,0];
  selectSceneObject('entry-portal:'+(section?'shelf':'head'));
  g.layers.get('selection').visible=false;
  renderLayerControls();g.request();
 });
}

