function drawBoilerFinish(g,floorLayer,room,id){
 const tiles=addLayer(g,'boilerTiles',{showEdges:false}),walls=addLayer(g,'boilerPlaster',{showEdges:false});
 const [x0,y0]=room.polygon_mm[0],[x1,y1]=room.polygon_mm[2],z=room.elevation_mm;
 const measured=MODEL.experience.floor_finishes.waterproofing.rows.find(row=>row.id===room.id);
 const geometry=measured.geometry.find(variant=>variant.id===stairState.stairVariant);
 for(const [a,b,c,d] of geometry.floor_rectangles_mm)polygonAt(g,floorLayer,[[a,b],[c,b],[c,d],[a,d]],z-2,id);
 // AR-16 type 4. Tile module and grout width are choices for the visualization.
 for(let x=x0;x<x1;x+=300)for(let y=y0;y<y1;y+=300){
  for(const [a,b,c,d] of geometry.floor_rectangles_mm){
   const left=Math.max(a,x+1.5),right=Math.min(c,Math.min(x+300,x1)-1.5);
   const bottom=Math.max(b,y+1.5),top=Math.min(d,Math.min(y+300,y1)-1.5);
   if(left<right&&bottom<top)g.face(tiles,[[left,bottom,z],[right,bottom,z],[right,top,z],[left,top,z]],[0,0,1],id);
  }
 }
 // The east finish follows the partition solids down to the room floor.
 const plinthTop=Number(MODEL.foundation.plinth.z_top_mm);
 for(const side of geometry.sides){
  if(side.axis===1&&side.outward===1&&side.at_mm===x1)continue;
  const axis=side.axis,cross=1-axis,normal=axis===0?[0,-side.outward,0]:[-side.outward,0,0];
  for(const face of side.backed_faces_mm){
   const section=face.map(p=>[p[axis],p[2]]);
   const cut=HouseShapes.clip(HouseShapes.clip(section,[0,1,-z]),[0,-1,plinthTop]);
   if(HouseShapes.area(cut)<1e-5)continue;
   g.face(walls,cut.map(([u,h])=>axis===0?[u,side.at_mm+2*normal[cross],h]:[side.at_mm+2*normal[cross],u,h]),normal,'wall:boiler-plinth');
  }
 }
 const sides=[['ext16',0,x0,1],['boiler',0,x1,-1],['bearingГ',1,y0,1],['bearingЕ',1,y1,-1]];
 expInfo(g,'finish:boiler-east',{title:'Отделка восточной стены котельной',facts:['wall.boiler.base_support','level.boiler_floor.elevation'],sheets:[['house_1',10],['house_1',17]]});
 for(const solid of FloorGeometry.solids(MODEL.floor1)){
  const side=sides.find(([wall])=>wall===solid.wall_id);
  if(!side)continue;
  const [wall,axis,face,sign]=side,b=solid.bounds,along=1-axis;
  if(Math.abs(b[axis+(sign>0?3:0)]-face)>.01)continue;
  // Reuse masonry cutouts (windows, doors, and the underside of the landing).
  for(const piece of stairWallPatches(b,wall)){
   const edge=piece.polygon_mm.filter(p=>Math.abs(p[axis]-face)<.01).map(p=>p[along]);
   const lo=Math.max(Math.min(...edge),along?y0:x0),hi=Math.min(Math.max(...edge),along?y1:x1);
   if(hi<=lo)continue;
   const points=[lo,hi].map(t=>axis?[t,face]:[face,t]);
   const at=(p,h)=>[p[0]+(axis?0:2*sign),p[1]+(axis?2*sign:0),h];
   const lower=p=>Math.max(z,HouseShapes.z(piece.bottom_plane,p));
   g.face(walls,[at(points[0],lower(points[0])),at(points[1],lower(points[1])),
    ...points.reverse().map(p=>at(p,HouseShapes.z(piece.top_plane,p)))],axis?[0,sign,0]:[sign,0,0],wall==='boiler'?'finish:boiler-east':'wall:'+wall);
  }
 }
}
function drawUpperRoomFloor(g,l,room,id){
 const floorRects=activeSlab().disjoint_rectangles_mm.map(box=>box.map(Number));
 const extension=room.id==='14'&&activeHallExtension();
 if(extension)floorRects.push(extension);
 const floorTiles=floorRects.map(roofContactRect);
 const holes=[];
 if(mode==='house'&&MODEL.roof_frame){
  // Lay the finish around sills on the slab. Their tops meet the finish at +3.300.
  for(const member of roofFrameDisplayMembers().filter(m=>m.family==='beds'||m.post_base_plate)){
   const [x0,y0,z0,x1,y1,z1]=frameSceneBox(member.id);
   if(z0<room.elevation_mm&&room.elevation_mm<=z1)holes.push(roofContactRect([x0,y0,x1,y1]));
  }
 }
 for(const t of HouseGL.triangulate(room.polygon_mm)){
  const triangle=t.map(i=>room.polygon_mm[i]);
  const bearing=floorTiles.map(tile=>HouseShapes.intersect(triangle,tile)).filter(p=>HouseShapes.area(p)>1e-5);
  const patches=holes.reduce((parts,hole)=>parts.flatMap(p=>HouseShapes.subtract(p,hole)),bearing);
  for(const p of patches)
   g.face(l,p.map(q=>[...q,room.elevation_mm]),[0,0,1],id);
 }
}
function drawFinishSurface(g,layer,face,id){
 const {polygon_mm:polygon,finish_plane:plane}=face;
 for(const tri of HouseGL.triangulate(polygon)){
  const points=tri.map(i=>[...polygon[i],HouseShapes.z(plane,polygon[i])]);
  g.face(layer,points,null,id);
 }
}
// Schematic rails and bars. The opening area and pitch are set by the selected product.
function drawGarageGrate(g,layer,outline,id){
 const xs=outline.map(p=>p[0]),ys=outline.map(p=>p[1]);
 const left=Math.min(...xs),right=Math.max(...xs),front=Math.min(...ys),back=Math.max(...ys);
 const z=outline[0][2],width=back-front;
 const strip=(x,y,X,Y)=>g.face(layer,[[x,y,z],[X,y,z],[X,Y,z],[x,Y,z]],[0,0,1],id);
 if(MODEL.foundation.garage_drain.grate.pattern!=='elongated_slots'){
  strip(left,front,right,back);
  return;
 }
 const innerFront=front+width/8,innerBack=back-width/8;
 strip(left,front,right,innerFront);
 strip(left,innerBack,right,back);
 const slots=Math.max(1,Math.round((right-left)/(width/3)));
 const pitch=(right-left)/slots,halfBar=pitch/4;
 for(let i=0;i<=slots;i++){
  const x=left+i*pitch;
  strip(Math.max(left,x-halfBar),innerFront,Math.min(right,x+halfBar),innerBack);
 }
}
function accessFloorAt(x,y){
 const layout=MODEL.foundation.access_finishes;
 const sill=layout.entry.cover_profile_mm, door=MODEL.floor1.openings.find(o=>o.id==='d-entry');
 const midX=(Number(door.bounds_mm[0])+Number(door.bounds_mm[3]))/2;
 if(Math.abs(x-midX)<=n('door.1.block_width')/2&&y>=sill[0][0]&&y<=sill[2][0]){
  if(y>=sill[1][0])return sill[1][1];
  return sill[0][1]+(y-sill[0][0])*(sill[1][1]-sill[0][1])/(sill[1][0]-sill[0][0]);
 }
 for(const part of [layout.boiler,layout.garage,layout.entry]){
  for(const face of part.surfaces){
   if(HouseGL.inside([x,y],face.polygon_mm))return HouseShapes.z(face.finish_plane,[x,y]);
  }
 }
 for(const piece of MODEL.foundation.apron_profile.pieces){
  if(piece.boiler_zone&&HouseGL.inside([x,y],piece.polygon_mm))return HouseShapes.z(piece.top_plane,[x,y]);
 }
 const porch=MODEL.foundation.slab;
 const southOfStairs=x>=+porch.front_x_start_mm && y<+porch.front_y_mm;
 const eastOfStairs=x>+porch.front_extension_start_mm && y<+porch.east_return_y_mm;
 if(southOfStairs||eastOfStairs)return layout.entry.ground_level_mm;
 return null;
}
