 const collector=plan.collector;
 route(sewer,'pipe:collector',[[...collector.upstream_mm,zAt(collector.upstream_chainage_mm)],outlet],study.pipe_diameter_mm/2,'К1 · общий выпуск',['service.outlet.pipe_diameter','service.legacy_outlet.slope'],`Вариант трассы под фундаментом. Уклон ${experience.sewerSlope}% — параметр; ось выпуска −${experience.sewerDepth} мм. Колена и ветви показаны по топологии ВК-1.`,{network:'waste',section:'foundation'});
 const septic=config.septic_point_mm,dx=septic[0]-outlet[0],dy=septic[1]-outlet[1];
