   return `<tr data-sleeve-stock="${row.outer_diameter_mm}"><td>${esc(row.label)}</td><td>Ø${row.outer_diameter_mm}</td><td>${row.schedule_count} шт.${row.plan_reserve?' · резерв':''}</td><td>${row.reference_wall_fact_id?factBtn(row.reference_wall_fact_id,fmt(row.reference_wall_mm)+' мм'):'Открыта'}</td>
    <td>${section?fmt(section.measured_length_mm):'—'}</td><td>${section?fmt(section.mass_per_m_kg,3):'—'}</td><td>${section?fmt(section.mass_for_plan_count_kg,3):'—'}</td></tr>`;
