function focusWaterFit(study,scenario,choice){
 $('source-dialog').close();
 return activateTab(constructionViewer?'foundation':'model','foundation',()=>{
  const g=renderer,[x,y]=choice.centre_mm,[X,Y]=scenario.reference_mm,[bottom,top]=study.slab_elevations_mm,r=study.diameter_mm/2;
  for(const layer of g.layers.values())layer.visible=['slab','beams'].includes(layer.id);
  g.layers.get('slab').opacity=.24;
  g.layers.get('beams').opacity=.48;
  const previous=g.addLayer('waterFitOrigin',[.68,.33,.16],{showEdges:true});
  const current=g.addLayer('waterFit',[.11,.46,.34],{showEdges:true});
  const rebar=g.addLayer('waterFitSteel',[.38,.40,.43],{showEdges:false});
  LAYER_META.waterFitOrigin=['Ориентир ВК-1',previous.color];
  LAYER_META.waterFit=['Примерка В1-1',current.color];
  LAYER_META.waterFitSteel=['Арматура у ввода',rebar.color];
  g.tube(current,[x,y,bottom],[x,y,top],r,24,'water-fit');
  g.ring(current,x,y,top,r);
  g.ring(previous,X,Y,top,r);
  for(const rod of scenario.local_rods)g.rod(rebar,rod.points_mm,rod.diameter_mm/2);
  expInfo(g,'water-fit',{title:'В1-1 · геометрическая примерка',note:`Наименьший зазор ${fmt(choice.minimum_gap_mm,2)} мм. Координаты от 1/А (${fmt(x)}, ${fmt(y)}) мм.`,
   facts:study.source_fact_ids,sheets:[['embeds',1],['house_2',7]]});
  for(const layer of [previous,current,rebar])g.commitLayer(layer);
  indexSceneObjects(g);selectSceneObject('water-fit');
  g.target=[(x+X)/2,(y+Y)/2,(bottom+top)/2];g.span=1500*g.fitAspect();g.yaw=-.36;g.pitch=.6;g.pan=[0,0];
  renderLayerControls();g.request();
 });
}
const passageChoiceLabels={nearest:'Ближайший сдвиг',compatible:'С учётом нахлёстов'};
function openPassageCoordination(){
 return prepareDialog(['foundation','facts'],()=>{
  const s=MODEL.foundation.passage_coordination;
  const matches=s.trials.filter(r=>r.choices.compatible);
  showDialog('ФМ 1 / ВК-1 / I008 И I017','Примерка положений канализационных гильз',`
   <p>Проверены сдвиги до ${s.half_width_mm} мм в каждом направлении с шагом ${s.step_mm} мм. Отступ ${s.comparison_margin_mm} мм принят для сравнения с границами помещений, стенами, ростверками и неполевой арматурой. Гильза Ø200 шире чистого просвета ${s.mesh_opening_mm} мм между рядами Ø12.</p>
   <div class="table-wrap"><table id="passage-coordination"><thead><tr><th>Гильза и помещение</th><th>ВК-1 · X / Y, мм</th><th>Примерка · X / Y, мм</th><th>Сдвиг, мм</th><th>Пересечения с арматурой</th><th>До нахлёстов 6 / 12 м, мм</th><th>Вид</th></tr></thead><tbody>
   ${s.trials.map(row=>{const v=row.choices.compatible;return `<tr data-coordinated-sleeve="${esc(row.id)}"><th>${esc(row.id)}<small class="block-note">${esc(row.room_name)}</small></th><td>${row.original_mm.map(x=>fmt(x)).join(' / ')}</td><td>${v?v.centre_mm.map(x=>fmt(x)).join(' / '):'Уточняется'}</td><td>${v?fmt(v.shift_mm,2):'—'}</td><td>${v?`${row.original_conflicts} → ${v.field_rod_ids.length}`:row.original_conflicts}</td><td>${v?v.cuts.map(p=>fmt(p.nearest_lap_gap_mm,2)).join(' / '):'—'}</td><td>${v?`<button data-coordinated-site="${esc(row.id)}" data-coordinated-choice="compatible">Открыть</button>`:''}</td></tr>`;}).join('')}</tbody></table></div>
   <p>В сборке пяти гильз число пересечений меняется с ${s.baseline_conflicts} до ${matches.reduce((n,r)=>n+r.choices.compatible.field_rod_ids.length,0)}. Дополнительные пересечения с неполевыми стержнями устранены в пределах пробы. Проходки, схемы армирования у отверстий и уклоны подводок требуют увязки.</p>
   <div class="buttons-row"><button data-passage-bypass>Обход стержней</button><button data-coordinated-bores>Все сдвиги · вырезы через слои</button>${sheetBtn('embeds',1,'ВК-1','revision')}${sheetBtn('house_2',7,'КЖ-2')}</div>`);
 });
}
function showCoordinatedSleeve(id,choiceId){
 $('source-dialog').close();
 foundationPassagePreview=null;
 return activateTab(constructionViewer?'foundation':'model','foundation',()=>{
  const g=renderer,s=MODEL.foundation.passage_coordination,row=s.trials.find(r=>r.id===id),v=row.choices[choiceId];
  for(const layer of g.layers.values())layer.visible=['slab','beams'].includes(layer.id);
  g.layers.get('slab').opacity=.14;
  g.layers.get('beams').opacity=.2;
  const original=addLayer(g,'passageTrialOrigin'),shifted=addLayer(g,'passageTrialSleeve');
  const field=addLayer(g,'passageTrialField'),clash=addLayer(g,'passageTrialClash'),laps=addLayer(g,'passageTrialLap');
  const [x,y]=v.centre_mm,[a,b]=row.original_mm,r=row.diameter_mm/2;
  const z=s.slab_z_mm[1];
  g.ring(original,a,b,z,r);
  g.ring(shifted,x,y,z,r);
  g.line(shifted,[a,b,z],[x,y,z]);
  for(const rod of row.local_segments){
   const layer=v.field_rod_ids.includes(rod.id)?clash:field;
   g.polyline(layer,rod.segment_mm.map(p=>[...p,z+2]),false);
  }
  for(const cut of v.cuts){
   if(cut.nearest_lap&&cut.nearest_lap_gap_mm<180)
    g.polyline(laps,cut.nearest_lap.segment_mm.map(p=>[...p,z+8]),false);
  }
  for(const layer of [original,shifted,field,clash,laps])g.commitLayer(layer);
  g.labels=[];g.homeView={target:[(a+x)/2,(b+y)/2,-525],yaw:0,pitch:.04,span:1240};g.home();
  $('scene-title').textContent=id+' · '+row.room_name;
  $('scene-status').textContent=passageChoiceLabels[choiceId];
  $('scene-notice').textContent='Арматура показана в проекции. Красным выделены четыре полевых стержня в габарите гильзы.';
  $('experience-tools').innerHTML='';
  $('foundation-study').insertAdjacentHTML('beforeend',`<p id="passage-local-gap" style="flex-basis:100%">До нахлёстов 6 и 12 м ${v.cuts.map(c=>fmt(c.nearest_lap_gap_mm,2)).join(' / ')} мм.</p>
   <button data-passage-coordination>Все гильзы К1</button>
   <button data-passage-bypass-site="${esc(id)}" data-passage-bypass-position="1">Обход стержней</button>
   <button data-coordinated-site="${esc(id)}" data-coordinated-choice="${choiceId==='compatible'?'nearest':'compatible'}">${passageChoiceLabels[choiceId==='compatible'?'nearest':'compatible']}</button>`);
  $('inspector').innerHTML=`<h3>${esc(id)} · ${passageChoiceLabels[choiceId]}</h3><p>X = ${fmt(x)} мм, Y = ${fmt(y)} мм. Сдвиг ${fmt(v.shift_mm,2)} мм. Зелёный круг — текущая проба, коричневый — ориентир ВК-1.</p>
   <p>До ближайших нахлёстов 6 и 12 м ${v.cuts.map(c=>fmt(c.nearest_lap_gap_mm,2)).join(' / ')} мм.</p>${sheetBtn('embeds',1,'ВК-1','revision')}`;
  indexSceneObjects(g);renderLayerControls();g.request();
 });
}
function bypassCutResult(result){
 if(!result)return '—';
 if(result.preserves_existing_lap_and_limit)return 'Помещается';
 const failures=[];
 if(result.excess_over_limit_mm>0)failures.push(`длиннее на ${fmt(result.excess_over_limit_mm,2)} мм`);
 if(result.lap_overlap_if_bent_mm?.length)failures.push('загиб в нахлёсте');
 if(result.adjacent_steel_overlap)failures.push('пересечение со сталью');
 if(result.adjacent_steel_near_contact)failures.push('возможное касание стали');
 return failures.length?failures.join(', '):'Обход выходит за конец детали';
}
