function showPassageSpliceRefit(limit,id,previous=false){
 $('source-dialog').close();
 foundationPassagePreview=null;
 return activateTab(constructionViewer?'foundation':'model','foundation',()=>{
  const g=renderer,foundation=MODEL.foundation;
  const study=previous?foundation.passage_splice_refit.previous:foundation.passage_splice_refit;
  const trial=study.scenarios.find(r=>r.limit_mm===limit);
  const row=trial.affected_rows.find(r=>r.id===id);
  const site=study.sleeves.find(r=>r.id===row.site_id);
  const [x,y]=site.centre_mm;
  const z=row.route.points_mm[0][2];
  const coordinate=(fixed,v,h=z)=>row.axis==='X'?[v,fixed,h]:[fixed,v,h];
  for(const layer of g.layers.values())layer.visible=layer.id==='slab';
  g.layers.get('slab').opacity=.10;
  const steel=addLayer(g,'passageRefitPieces'),bend=addLayer(g,'passageRefitBend');
  const before=addLayer(g,'passageRefitPrior'),after=addLayer(g,'passageRefitLap'),sleeve=addLayer(g,'passageRefitSleeve');
  const radius=foundation.passage_splice_refit.rules.diameter_mm/2;
  for(const [i,[fixed,a,b]] of row.pieces_mm.entries()){
   if(i===row.bent_piece_index){
    const pts=row.route.points_mm;
    g.rod(bend,[coordinate(fixed,a),...pts,coordinate(fixed,b)],radius);
   }else g.tube(steel,coordinate(fixed,a),coordinate(fixed,b),radius,8);
  }
  const axes=foundation.mesh_seat_study.cases.find(c=>c.id==='steel_face').axes_mm;
  for(const offset of trial.straight_adjustments.filter(a=>a.position===row.position&&a.site_ids.includes(site.id))){
   const [fixed,start,end]=offset.after_mm;
   const h=axes[(offset.position===1?'lower_':'upper_')+offset.axis.toLowerCase()];
   const point=v=>offset.axis==='X'?[v,fixed,h]:[fixed,v,h];
   g.tube(steel,point(start),point(end),radius,8);
  }
  const station=row.pieces_mm[0][0];
  for(const [a,b] of row.baseline_laps_mm)g.polyline(before,[coordinate(station-28,a,z+8),coordinate(station-28,b,z+8)],false);
  for(const [a,b] of row.laps_mm)g.polyline(after,[coordinate(station+28,a,z+8),coordinate(station+28,b,z+8)],false);
  g.ring(sleeve,x,y,z+9,site.diameter_mm/2);
  for(const l of [steel,bend,before,after,sleeve])g.commitLayer(l);
  const lo=row.pieces_mm[0][1],hi=row.pieces_mm.at(-1)[2];
  const focus={target:[x,y,z+9],span:2560,yaw:0,pitch:.08};
  const full={...focus,target:coordinate(station,(lo+hi)/2,z+9),span:(hi-lo)*1.14};
  g.labels=[];g.homeView=focus;g.home();
  $('scene-title').textContent=`${row.site_id} · стыки стержня ${row.id}`;
  $('scene-status').textContent=`Детали до ${limit/1000} м · поз. ${row.position}`;
  $('scene-notice').textContent='Коричневым отмечены прежние интервалы, жёлтым — нахлёсты после переноса.';
  $('experience-tools').innerHTML='';
  $('foundation-study').insertAdjacentHTML('beforeend',`
   <p style="flex-basis:100%">Длина детали с обходом ${fmt(row.cut_lengths_mm[row.bent_piece_index],3)} мм. Коричневый · прежние стыки, жёлтый · новые.</p>
   <button id="refit-focus">У гильзы</button><button id="refit-full">Весь ряд</button>
   <button data-passage-splice-refit="${limit}" ${previous?'data-refit-previous':''}>Таблица раскроя</button>`);
  $('refit-focus').onclick=()=>{g.homeView=focus;g.home();};
  $('refit-full').onclick=()=>{g.homeView=full;g.home();};
  indexSceneObjects(g);renderLayerControls();g.request();
 });
}
