function showFoundationSewer(variant,depth){
 if(experience.selectedServices)setServiceLayout(false);
 $('source-dialog').close();
 foundationPassagePreview=variant==='selected'?{reserve:true,sewerShift:'selected',electricChoice:'nearest'}:{reserve:false,sewerShift:variant==='source'?null:'bypass'};
 if(variant==='selected')selectWaterPlacement('coordinated-E');
 return activateTab(constructionViewer?'foundation':'model','foundation',()=>{
  const g=renderer,f=MODEL.foundation,s=f.sewer_route_study;
  const trial=[s.selected,...s.variants].find(v=>v.id===variant),runs=[...trial.branches,trial.collector];
  const radius=s.pipe_diameter_mm/2,top=f.passage_coordination.slab_z_mm[1];
  const zAt=chainage=>-depth+s.slope*chainage;
  for(const layer of g.layers.values())layer.visible=layer.id==='slab';
  g.layers.get('slab').opacity=.14;
  const bed=addLayer(g,'sewerProfileBed',{opacity:.28}),axis=addLayer(g,'sewerProfileAxis'),rise=addLayer(g,'sewerProfileRisers');
  const gap=addLayer(g,'sewerProfileGap');
  g.polyline(bed,core.map(p=>[...p,s.base_bottom_mm]),true);
  for(const run of runs){
   const start=[...run.upstream_mm,zAt(run.upstream_chainage_mm)],end=[...run.downstream_mm,zAt(run.downstream_chainage_mm)];
   if(run.plan_length_mm)g.tube(axis,start,end,radius,16);
   if(run.id!=='collector'){
    g.tube(rise,start,[...run.upstream_mm,top],radius,16);
    g.ring(rise,...run.upstream_mm,top,Number(MODEL.services.find(site=>site.id===run.id).sleeve)/2);
   }
  }
  const [x,y]=trial.limiting_point_mm;
  const crown=zAt(trial.limiting_chainage_mm)+radius;
  g.line(gap,[x,y,s.base_bottom_mm],[x,y,crown]);
  for(const l of [bed,axis,rise,gap])g.commitLayer(l);
  g.labels=[];
  const general={target:[6300,5960,-800],span:15500,yaw:-.14,pitch:.52};
  const close={target:[x+600,y-500,(crown+s.base_bottom_mm)/2],span:3000,yaw:-.48,pitch:.82};
  g.homeView=general;g.home();
  $('scene-title').textContent='К1 · трасса под плитой';
  $('scene-status').textContent=`Ось выпуска −${fmt(depth)} мм`;
  const difference=s.base_bottom_mm-crown;
  const note=difference<0?`Заход верха трубы в основание до ${fmt(-difference,2)} мм.`:`До низа основания минимум ${fmt(difference,2)} мм.`;
  $('scene-notice').textContent=note;
  $('experience-tools').innerHTML='';
  $('foundation-study').insertAdjacentHTML('beforeend',`<p style="flex-basis:100%">${note} Ближайший участок · ${esc(trial.limiting_run_id)}.</p>
   <button id="sewer-profile-close">У ${esc(trial.limiting_run_id)}</button><button id="sewer-profile-full">Вся трасса</button>
   <button data-foundation-sewer="${variant}">Обмер трассы</button>`);
  $('sewer-profile-close').onclick=()=>{g.homeView=close;g.home();};
  $('sewer-profile-full').onclick=()=>{g.homeView=general;g.home();};
  indexSceneObjects(g);renderLayerControls();g.request();
 });
}
function showPassageBypass(id,position){
 $('source-dialog').close();
 foundationPassagePreview=null;
 return activateTab(constructionViewer?'foundation':'model','foundation',()=>{
  const g=renderer,s=MODEL.foundation.passage_bypass,site=s.sites.find(row=>row.id===id);
  const [x,y]=site.centre_mm,pivot=[x,y];
  const bars=site.bars.filter(bar=>bar.position===position);
  for(const layer of g.layers.values())layer.visible=['slab','beams'].includes(layer.id);
  g.layers.get('slab').opacity=.13;
  g.layers.get('beams').opacity=.18;
  const sleeve=addLayer(g,'passageBypassSleeve'),route=addLayer(g,'passageBypassRoute');
  const axes=addLayer(g,'passageBypassAxis'),clash=addLayer(g,'passageBypassConflict');
  const obstacles=addLayer(g,'passageBypassObstacle');
  for(const bar of bars){
   const i=bar.axis==='X'?0:1,[a,b]=bar.original_axis_mm;
   const span=bar.trial?.axis_span_mm||[pivot[i]-290,pivot[i]+290];
   const points=span.map(v=>{
    const p=[...a];p[i]=Math.max(Math.min(a[i],b[i]),Math.min(Math.max(a[i],b[i]),v));return p;
   });
   if(bar.trial){
    g.polyline(axes,points,false);
    g.rod(route,bar.trial.points_mm,bar.diameter_mm/2);
   }else{
    g.rod(clash,points,bar.diameter_mm/2);
    const obstruction=bar.best_rejected?.obstacle;
    if(obstruction)g.rod(obstacles,obstruction.points_mm,obstruction.diameter_mm/2);
   }
  }
  const levels=bars.map(bar=>bar.original_axis_mm[0][2]),z=Math.max(...levels)+13;
  g.ring(sleeve,x,y,z,site.diameter_mm/2);
  if(site.adjustment_mm){
   const original=addLayer(g,'passageBypassOrigin'),[a,b]=site.prior.centre_mm;
   g.ring(original,a,b,z,site.diameter_mm/2);
   g.line(sleeve,[a,b,z],[x,y,z]);
   g.commitLayer(original);
  }
  for(const layer of [sleeve,axes,route,clash,obstacles])g.commitLayer(layer);
  const label=position===1?'Нижняя сетка':'Верхняя сетка';
  const count=bars.filter(bar=>bar.trial).length;
  g.labels=[];g.homeView={target:[x,y,z],yaw:0,pitch:.12,span:1370};g.home();
  $('scene-title').textContent=`${id} · обход стержней`;
  $('scene-status').textContent=label;
  $('scene-notice').textContent=`Обходы для ${count} из ${bars.length} стержней.`+(site.adjustment_mm?` Центр сдвинут на ${fmt(site.adjustment_mm,2)} мм.`:'');
  $('experience-tools').innerHTML='';
  $('foundation-study').insertAdjacentHTML('beforeend',`<p style="flex-basis:100%">Обходы найдены для ${count} из ${bars.length} стержней.</p>
   ${site.adjustment_mm?`<p style="flex-basis:100%">Бежевый круг · прежний центр. Сдвиг ${fmt(site.adjustment_mm,2)} мм.</p>`:''}
   <button data-passage-bypass>Все обходы К1</button>
   <button data-passage-bypass-site="${esc(id)}" data-passage-bypass-position="${position===1?2:1}">${position===1?'Обходы верхней сетки':'Обходы нижней сетки'}</button>`);
  $('inspector').innerHTML=`<h3>${esc(id)} · ${label}</h3><p>Координаты центра от 1/А ${fmt(x)} / ${fmt(y)} мм. Радиус загиба ${s.radius_mm} мм.</p>
   <ul>${bars.map(bar=>`<li>${esc(bar.id)} · ${bar.trial?`+${fmt(bar.trial.length_addition_mm,2)} мм`:'обход требует доработки'}</li>`).join('')}</ul>`;
  indexSceneObjects(g);renderLayerControls();g.request();
 });
}
