function showFoundationApron(id){
 $('source-dialog').close();
 return activateTab(constructionViewer?'foundation':'model','foundation',()=>{
  const g=renderer,r=MODEL.foundation.apron_study,v=r.variants.find(row=>row.id===id);
  for(const layer of g.layers.values())layer.visible=['slab','beams'].includes(layer.id);
  const put=(layer,rects,z0,z1)=>{
   for(const bounds of rects){
    const [a,b,c,d]=bounds.map(Number);
    g.box(layer,a,b,z0,c,d,z1,layer.id,false);
   }
   g.commitLayer(layer);
  };
  const vertical=addLayer(g,'apronVertical',{showEdges:false,order:12});
  for(const row of r.vertical){
   const [z0,z1]=row.z_mm.map(Number);
   for(const bounds of row.rectangles_mm){
    const [a,b,c,d]=bounds.map(Number);
    g.box(vertical,a,b,z0,c,d,z1,'apronVertical',false);
   }
  }
  g.commitLayer(vertical);
  const height=Number(r.dimensions.horizontal_layer_mm),top=Number(r.dimensions.display_upper_z_mm);
  put(addLayer(g,'apronTop',{showEdges:false,order:11}),v.rectangles_mm,top-height,top);
  put(addLayer(g,'apronBottom',{showEdges:false,order:10}),v.rectangles_mm,top-2*height,top-height);
  if(v.excluded_by_slab_mm.length){
   const warning=addLayer(g,'apronExclusion',{showEdges:false,opacity:.80,order:14});
   for(const b of v.excluded_by_slab_mm)g.face(warning,roofContactRect(b.map(Number)).map(p=>[...p,top+8]),[0,0,1],warning.id);
   g.commitLayer(warning);
  }
  g.apronVariant=id;g.yaw=-.25;g.pitch=.47;g.span=21600*g.fitAspect();g.labels=[];
  $('scene-title').textContent='Примерка утепления Фм 1';
  $('scene-notice').textContent=apronLabels[id]+'. Отметка горизонтального XPS условная и служит для сравнения геометрии.';
  renderLayerControls();g.request();
 });
}

