function foundationGeometrySVG(){
 const f=MODEL.foundation,p=f.slab.render_polygon_mm.map(p=>p.map(Number));
 return `<svg class="plan-svg geometry-plan" viewBox="-1800 -17800 20600 19600" role="img" aria-label="Восстановленный вариант контура Фм 1 с ростверками и прямым восточным краем, на проверке"><g transform="scale(1,-1)"><polygon points="${p.map(a=>a.join(',')).join(' ')}" fill="#e7eadb" stroke="#637d5a" stroke-width="34"/>${f.plinth.disjoint_rectangles_mm.map(r=>`<rect x="${r[0]}" y="${r[1]}" width="${+r[2]-r[0]}" height="${+r[3]-r[1]}" fill="#94aa7e"/>`).join('')}${Object.entries(MODEL.axis_view_variant.x).map(([a,x])=>`<path d="M${x},-900V16800" stroke="#bcc8b1" stroke-width="10" stroke-dasharray="110 160"/>`).join('')}<path d="M${f.slab.front_x_start_mm},${f.slab.front_y_mm} H${f.slab.front_extension_start_mm} V${f.slab.east_return_y_mm} H${f.slab.edge_x_mm} v${f.slab.edge_length_mm}" stroke="#bd6732" stroke-width="55"/></g>${f.points.slice(0,p.length).map((q,i)=>`<text x="${+q.x_mm+120}" y="${-q.y_mm-100}" font-size="190" fill="#637354">P${i+1}</text>`).join('')}<text x="4500" y="900" font-size="225" fill="#637354">Фм 1 · размерный вариант по осям · I002/I012/I013</text></svg>`;
}
function foundationBalanceTable(){const rows=MODEL.foundation.calculations.filter(c=>['foundation.geometry.area','foundation.geometry.plinth_area','foundation.geometry.slab_volume','foundation.geometry.plinth_volume','foundation.geometry.total_volume'].includes(c.id));return `<div class="table-wrap"><table><thead><tr><th>Показатель</th><th>Геометрия варианта, ≈</th><th>Ведомость КЖ-4</th><th>Разница, ≈</th></tr></thead><tbody>${rows.map(c=>`<tr><td>${esc(c.label)}</td><td class="number updated">${fmt(c.value,8)} ${unit(c.unit)}</td><td class="number">${c.printed?'<del>'+esc(c.printed)+' '+unit(c.unit)+'</del>':'—'}</td><td class="number ${c.difference?'check-bad':''}">${c.difference?fmt(c.difference,4):'—'}</td></tr>`).join('')}</tbody></table></div>`;}
function foundationBalanceCard(){const f=MODEL.foundation;return `<div class="card" id="foundation-balance"><h3>Край параллельно фасаду</h3><p>Параллельно оси 6 проложен край длиной ${fmt(f.slab.edge_length_mm)} мм по наружной грани выступа стены. Передний край площадки проходит на ${fmt(f.slab.front_y_mm)} мм от оси А. По решению владельца от 26.11.2026 справа от ступеней убрано ${fmt(f.revision.removed_front_m2)} м² плиты. Ростверки проходят внутри этого края.</p>${foundationBalanceTable()}<p>КЖ-4 относится к исходной форме. Ещё у варианта с дугой оставалось расхождение по объёму В25 (I013).</p><div class="buttons-row"><button data-foundation-geometry>Координаты и формулы ↗</button><button data-print-foundation>↓ План для печати · А3</button>${sheetBtn('house_2',7,'КЖ-2 · контур','revision')}${sheetBtn('house_2',9,'КЖ-4 · ведомость')}</div></div>`;}
function openFoundationGeometry(){
 const f=MODEL.foundation,gate=f.plinth.cuts.find(c=>c.id==='garage_gate');
 showDialog('КЖ-2 / ВОССТАНОВЛЕННЫЙ ВАРИАНТ','Геометрия фундамента и открытые зависимости',`<p>Редакция от 26 ноября 2026. Восточный край плиты проходит по прямой X = ${fmt(f.slab.edge_x_mm)} мм от Y = ${fmt(f.slab.east_return_y_mm)} до Y = ${fmt(+f.slab.east_return_y_mm + +f.slab.edge_length_mm)} мм. У ворот восточный торец ростверка продлён с X = ${fmt(gate.source_bounds_mm[2])} до X = ${fmt(gate.bounds_mm[2])} мм по грани проёма Д-3. Оси X рассчитаны по сумме частей. Прежняя дуга R12190 и её расхождения доступны на исходном листе. Открыты I002/I012/I013.</p>${foundationGeometrySVG()}${foundationBalanceTable()}<h3 style="margin-top:28px">Координаты и формулы привязок</h3><p class="tiny muted">P1…P${f.slab.point_ids.length} — внешний контур плиты. Остальные точки — внешний контур ростверка. Нулевые координаты — условное начало (1,А), не геодезическая привязка.</p><div class="table-wrap"><table><thead><tr><th>Точка</th><th>X / Y, мм</th><th>Связь с записями источника</th></tr></thead><tbody>${f.points.map((p,i)=>`<tr><td class="number">P${i+1}<br><small>${esc(p.id)}</small></td><td class="number">${p.x_mm} / ${p.y_mm}</td><td><details><summary>Формулы и ${p.input_fact_ids.length} входов</summary><div class="formula">X = ${esc(p.x_formula)}<br>Y = ${esc(p.y_formula)}</div>${p.input_fact_ids.map(id=>factBtn(id,FACTS.get(id)?.label)).join('<br>')}</details></td></tr>`).join('')}</tbody></table></div><h3 style="margin-top:28px">Разрывы ростверков</h3><table><thead><tr><th>Участок</th><th>Границы [X0,Y0,X1,Y1], мм</th></tr></thead><tbody>${f.plinth.cuts.map(c=>`<tr><td>${esc(c.purpose)}</td><td class="number">${c.bounds_mm.join(' / ')}</td></tr>`).join('')}</tbody></table><p class="tiny muted">Разрывы убраны только из ростверков над плитой. Тело плиты под воротами и дверями сохраняется. Положение арматурных стыков, анкеров и местных усилений этими границами не задаётся.</p>${sheetBtn('house_2',7,'Открыть исходный лист КЖ-2','source')}`);}
